local config = {
  ui_story_5081_50810100_1_dialog_content = "(Dalam angin yang berhembus dan pasir yang membara, rekan-rekan yang tersisa dan saya mencoba keras untuk melarikan diri...)",
  ui_story_5081_50810100_2_dialog_content = "(Di belakang kita muncul lautan Eclipsite...)",
  ui_story_5081_50810100_3_dialog_content = "(Dan di depan kita terbentang sebuah kastil yang sangat besar, simbol dari harapan dan putus asa...)",
  ui_story_5081_50810100_4_dialog_content = "(Tapi sekarang sepertinya seperti fatamorgana yang jauh, gelembung halus yang tidak pernah dimaksudkan untuk disentuh.)",
  ui_story_5081_50810100_5_dialog_content = "Apakah ini benar-benar akhirnya?",
  ui_story_5081_50810100_6_dialog_content = "Drat... Sepertinya kali ini aku tidak akan bisa pulang! Argh!",
  ui_story_5081_50810100_7_dialog_content = "Kicauan! Sork, tidak!",
  ui_story_5081_50810100_8_dialog_content = "Aku akan pergi bersamamu! Kita adalah pasangan sampai akhir yang pahit, cicit...",
  ui_story_5081_50810100_9_dialog_content = "Sork! Bekk!",
  ui_story_5081_50810100_10_dialog_content = "Sekarang bukan saatnya untuk berduka atas rekan-rekanmu yang telah gugur...",
  ui_story_5081_50810100_11_dialog_content = "Aku benci mengakuinya, tapi saat ini... kaulah harapan terakhir kami untuk bertahan hidup!",
  ui_story_5081_50810100_12_dialog_content = "Jangan berhenti! Terus berlanjut tidak peduli apa yang terjadi!",
  ui_story_5081_50810100_13_dialog_content = "Odi!",
  ui_story_5081_50810100_14_dialog_content = "A-Aku akan melanjutkan keinginanmu! Aku bersumpah akan sampai ke istana dan menemukannya...",
  ui_story_5081_50810100_15_dialog_content = "Tidak, tunggu, aku baru saja akan mengatakan sesuatu yang keren...",
  ui_story_5081_50810100_16_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5081_50810100_17_dialog_content = "Sudah selesai...",
  ui_story_5081_50810100_18_dialog_content = "Maaf semuanya, tapi aku... tidak bisa...",
  ui_story_5081_50810100_19_dialog_content = "...",
  ui_story_5081_50810100_20_dialog_content = "<color=#e8d9bb>Bip, bip!</color>",
  ui_story_5081_50810100_21_dialog_content = "Kami kalah lagi!",
  ui_story_5081_50810100_22_dialog_content = "Kurasa kita benar-benar tidak bisa mengalahkan level ini tanpa \"B,\" apalagi mencapai peringkat tinggi.",
  ui_story_5081_50810100_23_dialog_content = "Tapi \"B\" sudah menyampaikan sikapnya dengan jelas...",
  ui_story_5081_50810100_24_dialog_content = "Anda... tidak suka bermain game, kan?",
  ui_story_5081_50810100_25_dialog_content = "Maaf... Seharusnya aku tidak pernah mengganggumu!",
  ui_story_5081_50810100_26_dialog_content = "Sekarang \"B\" tidak bisa menerima saya, apakah benar-benar tidak ada yang bisa kita lakukan?",
  ui_story_5081_50810100_27_dialog_content = "<color=#e8d9bb>Semua ini dimulai beberapa hari yang lalu ketika sebuah permintaan mendesak dari Federasi Illumina muncul.</color>",
  ui_story_5081_50810100_28_dialog_content = "Sebenarnya, aku benar-benar tidak ingin datang ke Illumina pada saat ini.",
  ui_story_5081_50810100_29_dialog_content = "Semua orang sangat sibuk... Rasanya seperti badai besar sedang menghampiri.",
  ui_story_5081_50810100_30_dialog_content = "!",
  ui_story_5081_50810100_31_dialog_content = "Hah? Bukankah itu Petugas Intelijen Yingel?",
  ui_story_5081_50810100_32_dialog_content = "...",
  ui_story_5081_50810100_33_dialog_content = "D-Dia benar-benar mengabaikanku!",
  ui_story_5081_50810100_34_dialog_content = "Dia tampak sangat stres, meski... Dia tidak sedang dalam misi rahasia lainnya, kan?",
  ui_story_5081_50810100_35_dialog_content = "Kamu muncul tepat waktu, PlayerName.",
  ui_story_5081_50810100_36_dialog_content = "Oh, sebenarnya aku baru saja tiba.",
  ui_story_5081_50810100_37_dialog_content = "Mari kita lewati obrolan kecil. Anda harus tahu bahwa itu bukan alasan saya meminta untuk bertemu dengan Anda kali ini.",
  ui_story_5081_50810100_38_dialog_content = "Komite sedang melakukan banyak penyesuaian baru pada strukturnya. Alami, ini telah memberikan tekanan yang cukup besar pada semua laboratorium penelitian dan pengembangan kami...",
  ui_story_5081_50810100_39_dialog_content = "Mengatakan setiap proyek benar-benar berantakan sekarang adalah pernyataan yang meremehkan.",
  ui_story_5081_50810100_40_dialog_content = "Jadi... kau meminta bantuanku?",
  ui_story_5081_50810100_41_dialog_content = "Meskipun kamu mungkin tidak bisa membantu dengan proyek itu sendiri...",
  ui_story_5081_50810100_42_dialog_content = "Saya memang punya tugas yang sangat cocok dengan kemampuanmu.",
  ui_story_5081_50810100_43_dialog_content = "Apa tugasnya?",
  ui_story_5081_50810100_44_dialog_content = "Saya ingin kamu menyelidiki keberadaan Tech Officer Gronru. Dia tiba-tiba menghilang dari posnya beberapa hari yang lalu dan belum pernah terlihat sejak itu.",
  ui_story_5081_50810100_45_dialog_content = "Gronru? Dia hilang?",
  ui_story_5081_50810100_46_dialog_content = "Benar. Sumber kami menunjukkan bahwa dia sudah meninggalkan Illumina, tetapi keberadaan saat ini tidak diketahui.",
  ui_story_5081_50810100_47_dialog_content = "Kami berada di tengah masa-masa sulit Federasi Illumina. Jika kabar ini tersebar...",
  ui_story_5081_50810100_48_dialog_content = "\"Apakah dia membelot dari Illumina? Bisakah dia bekerja sama dengan musuh? Atau mungkin dia telah menjadi mata-mata untuk Hantu-hantu sejak awal?\"",
  ui_story_5081_50810100_49_dialog_content = "... Mungkin saja salah satu dari rumor-rumor ini akan menyebar seperti api yang membesar.",
  ui_story_5081_50810100_50_dialog_content = "Itu sedikit berlebihan!",
  ui_story_5081_50810100_51_dialog_content = "(Bagaimanapun juga, aku harus mencoba menghubungi Gronru di terminalnya...)",
  ui_story_5081_50810100_52_dialog_content = "Saya khawatir itu adalah kebenaran. Mengingat situasi saat ini, menghindari spekulasi publik semacam ini adalah prioritas utama kami.",
  ui_story_5081_50810100_53_dialog_content = "Sejumlah orang kami sendiri sudah ditugaskan untuk menangani masalah ini melalui saluran resmi.",
  ui_story_5081_50810100_54_dialog_content = "Faktanya, saya mendengar Federasi Illumina siap untuk memobilisasi seluruh jaringan intelijen daratan mereka untuk mengejarnya.",
  ui_story_5081_50810100_55_dialog_content = "Uh-oh—",
  ui_story_5081_50810100_56_dialog_content = "Jadi... Apa yang akan mereka lakukan pada Gronru setelah mereka menemukannya? Mereka tidak akan menghukumnya, bukan?",
  ui_story_5081_50810100_57_dialog_content = "Siapa tahu? Lagipula, ini bukan bidang keahlian saya.",
  ui_story_5081_50810100_58_dialog_content = "Dengan alasan pencegahan, atau mungkin karena takut menciptakan konflik yang lebih besar, Komite bertanya kepada saya apakah saya memiliki solusi lain.",
  ui_story_5081_50810100_59_dialog_content = "Itulah saatnya aku memutuskan untuk menyerahkan misi ini kepadamu.",
  ui_story_5081_50810100_60_dialog_content = "Kami membutuhkan kamu untuk menemukan rekan kerja kami yang AWOL dan membawanya kembali sebelum tindakan resmi diambil.",
  ui_story_5081_50810100_61_dialog_content = "Aku mengerti, tapi aku harus bertanya...",
  ui_story_5081_50810100_62_dialog_content = "Bisa jadi Gronru pergi karena betapa sibuknya Illumina saat ini?",
  ui_story_5081_50810100_63_dialog_content = "Mungkin stres membuatnya terlalu tertekan, jadi dia perlu menjauh dari pekerjaannya untuk sementara waktu?",
  ui_story_5081_50810100_64_dialog_content = "Siapa yang bisa mengatakan dia tidak akan muncul di Illumina begitu saja setelah aku pergi?",
  ui_story_5081_50810100_65_dialog_content = "Sayangnya, itu tidak mungkin.",
  ui_story_5081_50810100_66_dialog_content = "Orang biasa tidak akan pernah mengerti Gronru ketika berbicara tentang stres.",
  ui_story_5081_50810100_67_dialog_content = "Gadis itu selalu memiliki rasa moral yang lemah, jadi sesuatu seperti ini tidak akan pernah membuatnya merasa stres.",
  ui_story_5081_50810100_68_dialog_content = "Faktanya, itulah alasan tepat mengapa kami menempatkannya sebagai pemimpin proyek pengembangan terpenting Illumina.",
  ui_story_5081_50810100_69_dialog_content = "Kamu benar. Gronru adalah seorang jenius... tapi dia masih perlu istirahat dari pekerjaan sesekali.",
  ui_story_5081_50810100_70_dialog_content = "Dalam hal apapun, kami mengandalkan kamu. Kamu tidak ingin Gronru jatuh ke tangan keriput dan tua dari Committee, bukan?",
  ui_story_5081_50810100_71_dialog_content = "Kamu tidak perlu mengatakannya seperti itu. Saya bersedia membantu dalam kondisi apapun!",
  ui_story_5081_50810100_72_dialog_content = "Hanya saja Gronru memiliki banyak hobi, yang berarti dia bisa berada di hampir semua tempat di dunia.",
  ui_story_5081_50810100_73_dialog_content = "Dia mungkin memberi makan merpati di Lumopolis pada siang hari dan kemudian menonton drama di Teluk Twin Pavilions pada malam hari.",
  ui_story_5081_50810100_74_dialog_content = "Bepergian ke semua tempat itu tidak akan murah, terutama untuk saya...",
  ui_story_5081_50810100_75_dialog_content = "Jangan khawatir tentang biaya. Saya akan berbicara dengan Komite dan memastikan Anda mendapatkan kompensasi yang layak.",
  ui_story_5081_50810100_76_dialog_content = "Setelah semua, menemukan Tech Officer lebih cepat daripada nanti akan meminimalkan kerusakan pada Illumina. Saya yakin mereka akan mengerti.",
  ui_story_5081_50810100_77_dialog_content = "Saya menghargainya! Oh, ada satu hal lagi...",
  ui_story_5081_50810100_78_dialog_content = "Saya baru saja bertemu dengan Petugas Intelijen Yingel, dan dia tampak sangat sibuk. Dia bahkan tidak menyapa saya sama sekali.",
  ui_story_5081_50810100_79_dialog_content = "Apakah dia baik-baik saja?",
  ui_story_5081_50810100_80_dialog_content = "Yingel, eh... Dengan segala yang telah terjadi akhir-akhir ini, posisinya bahkan lebih terpengaruh daripada orang lain.",
  ui_story_5081_50810100_81_dialog_content = "Mungkin dia membenamkan dirinya dalam pekerjaannya untuk menghindari berpikir tentang hal-hal lain.",
  ui_story_5081_50810100_82_dialog_content = "... Kamu yakin kalian tidak hanya memaksanya untuk bekerja lembur?",
  ui_story_5081_50810100_83_dialog_content = "Sebaliknya, setiap orang di sini berharap dia berhenti memaksakan diri terlalu keras.",
  ui_story_5081_50810100_84_dialog_content = "Tidak peduli bagaimana Anda melihatnya, dia adalah anggota penting dan berbakat dari Illumina Federation. Lembur berlebihan sama tidak dapat diterimanya dengan meninggalkan pos tanpa izin.",
  ui_story_5081_50810100_85_dialog_content = "Jika kamu bilang begitu... Saya rasa semua orang di Illumina sedang mengalami masa yang cukup sulit sekarang.",
  ui_story_5081_50810100_86_dialog_content = "Tinggalkan saja pencarian Gronru padaku.",
  ui_story_5081_50810100_87_dialog_content = "Kita sudah menjadi teman untuk waktu yang lama sekarang, jadi saya punya beberapa ide tentang di mana dia mungkin berada.",
  ui_story_5081_50810100_88_dialog_content = "Aku akan terus memberi kabar!",
  ui_story_5081_50810100_89_dialog_content = "(Mari kita daftar tempat-tempat di mana Gronru mungkin berada—)",
  ui_story_5081_50810100_90_dialog_content = "(Tempat yang paling mungkin adalah Umbraton, ibu kota hiburan dari Astra!)",
  ui_story_5081_50810100_91_dialog_content = "Teknik canggih untuk membuat seluruh dunia terkagum-kagum! Karya masterful dari direktur terbaru Teater Sweet Dreams akan diperkenalkan malam ini!",
  ui_story_5081_50810100_92_dialog_content = "Pertunjukan yang menggemparkan panggung! Pesta indah untuk indera! Pertemuan tahunan musisi legendaris dimulai hari ini!",
  ui_story_5081_50810100_93_dialog_content = "... Lihat saja kerumunan ini!",
  ui_story_5081_50810100_94_dialog_content = "Setiap tempat dipenuhi hingga kapasitas maksimal dengan pengunjung. Menemukan Gronru di kekacauan ini akan seperti mencari jarum dalam tumpukan jerami...",
  ui_story_5081_50810100_95_dialog_content = "Tidak ada respon di terminal juga... Sepertinya permainan petak umpet ini tidak akan berakhir dalam waktu dekat.",
  ui_story_5081_50810100_96_dialog_content = "Apa yang harus kulakukan... Hah? Apakah itu—",
  ui_story_5081_50810100_97_dialog_content = "...",
  ui_story_5081_50810100_98_dialog_content = "Apa yang dilakukan Rediesel Wrench di sini?",
  ui_story_5081_50810100_99_dialog_content = "Dan mengapa mereka menyelinap seperti itu? Mereka tidak di sini untuk membuat masalah, bukan?",
  ui_story_5081_50810100_100_dialog_content = "Jika mereka memulai pertengkaran dengan geng lokal sekarang, segalanya hanya akan menjadi lebih sulit bagi saya.",
  ui_story_5081_50810100_101_dialog_content = "Aku harus pergi memberi peringatan kepada mereka.",
  ui_story_5081_50810201_1_dialog_content = "Cepat! Mari kita susul!",
  ui_story_5081_50810201_2_dialog_content = "Heheh, target terkunci!",
  ui_story_5081_50810201_3_dialog_content = "Ehem—",
  ui_story_5081_50810201_4_dialog_content = "?",
  ui_story_5081_50810201_5_dialog_content = "Maaf, tapi apa sebenarnya yang kalian berdua pikir kalian lakukan?",
  ui_story_5081_50810201_6_dialog_content = "Tsk, jadi kamu juga di sini, PlayerName...",
  ui_story_5081_50810201_7_dialog_content = "Jangan bilang kamu berkompetisi melawan kami!",
  ui_story_5081_50810201_8_dialog_content = "Nah, kalau bukan Bos! Mungkin kita bisa membuat kesepakatan?",
  ui_story_5081_50810201_9_dialog_content = "Dengan nama terkenal Anda, mungkin kita bisa mendapatkan prioritas untuk diri kita sendiri.",
  ui_story_5081_50810201_10_dialog_content = "Maaf, tapi aku sama sekali tidak tahu apa yang kamu bicarakan.",
  ui_story_5081_50810201_11_dialog_content = "Apakah kalian baru saja mengikuti seseorang?",
  ui_story_5081_50810201_12_dialog_content = "Oh tidak, kami hanya melakukan sedikit pemeriksaan latar belakang pada lawan kami.",
  ui_story_5081_50810201_13_dialog_content = "Untuk menyederhanakannya, kami datang untuk menilai kekuatan tempur musuh kami dan mengidentifikasi keuntungan apa pun yang mungkin mereka miliki...",
  ui_story_5081_50810201_14_dialog_content = "Setelah semua, ini terbatas. Hanya mereka yang memiliki keterampilan yang bisa mengambilnya dari orang lain.",
  ui_story_5081_50810201_15_dialog_content = "S-Sapu sesuatu?",
  ui_story_5081_50810201_16_dialog_content = "Tentu saja! Lihat saja semua orang-orang ini!",
  ui_story_5081_50810201_17_dialog_content = "Tidak mungkin! Benar-benar tidak! Aku tidak akan membiarkanmu—",
  ui_story_5081_50810201_18_dialog_content = "Mengapa kita tidak bisa—",
  ui_story_5081_50810201_19_dialog_content = "Curilah dari Umbraton!",
  ui_story_5081_50810201_20_dialog_content = "Beli game itu!",
  ui_story_5081_50810201_21_dialog_content = "Hah?",
  ui_story_5081_50810201_22_dialog_content = "Jadi, biarkan saya memahami ini dengan benar...",
  ui_story_5081_50810201_23_dialog_content = "Sebuah permainan fantasi yang baru saja diekskavasi akan segera dipulihkan, dan sekarang sedang dijual perdana di Umbraton.",
  ui_story_5081_50810201_24_dialog_content = "Tapi mereka hanya memiliki salinan terbatas, dan mereka hanya membiarkan para gamer membelinya jika mereka lulus tes mereka.",
  ui_story_5081_50810201_25_dialog_content = "Jadi kamu datang ke sini dari Rediesel Desert hanya untuk lulus tes ini dan mendapatkan salinan game.",
  ui_story_5081_50810201_26_dialog_content = "Dan sekarang kamu sedang menguntit gamer lain yang berpikiran sama untuk mendapatkan pemahaman yang lebih baik tentang tes...",
  ui_story_5081_50810201_27_dialog_content = "Kalian benar-benar berusaha keras hanya untuk membeli video game, haha...",
  ui_story_5081_50810201_28_dialog_content = "Ah... Kapan kamu mulai memiliki pandangan kasar tentang Rediesel Wrench, bos?",
  ui_story_5081_50810201_29_dialog_content = "Kupikir setelah bertahun-tahun berteman dan melawan musuh, kita seharusnya bisa saling memahami dengan lebih baik.",
  ui_story_5081_50810201_30_dialog_content = "Eh... Maaf?",
  ui_story_5081_50810201_31_dialog_content = "Kurasa kamu benar-benar tidak mengerti tentang Rediesel Wrench... atau nilai dari game fantasi seperti ini!",
  ui_story_5081_50810201_32_dialog_content = "... Apakah itu benar-benar intinya di sini?",
  ui_story_5081_50810201_33_dialog_content = "Untuk Aurorian menggali video game dari reruntuhan dan memulihkannya ke kondisi kerja...",
  ui_story_5081_50810201_34_dialog_content = "Apa kau tahu berapa banyak pekerjaan yang diperlukan untuk itu?",
  ui_story_5081_50810201_35_dialog_content = "B-Berapa harganya?",
  ui_story_5081_50810201_36_dialog_content = "Memperbaiki mesin game adalah bagian termudah dari prosesnya!",
  ui_story_5081_50810201_37_dialog_content = "Memahami kode asli dan isi dari sebuah game, lalu melengkapi bagian yang rusak atau hilang—itu sangat sulit!",
  ui_story_5081_50810201_38_dialog_content = "Dan jangan mulai bicara tentang tantangan menerjemahkan bahasa kuno dalam game ke dalam bahasa Aurorian!",
  ui_story_5081_50810201_39_dialog_content = "Jenis pekerjaan ini adalah salah satu usaha terbesar di zaman kita!",
  ui_story_5081_50810201_40_dialog_content = "A-Aku rasa aku paham sekarang... Kayaknya merilis sebuah permainan tidak semudah yang kukira...",
  ui_story_5081_50810201_41_dialog_content = "Tepat sekali. Lebih lagi, teknologi dan keahlian Illumina biasanya diperlukan untuk pekerjaan penggalian dan restorasi skala besar seperti ini.",
  ui_story_5081_50810201_42_dialog_content = "Itulah yang membuat semakin mengejutkan bahwa game seperti ini dijual pertama kali di Umbraton!",
  ui_story_5081_50810201_43_dialog_content = "Itulah juga mengapa kita harus mendapatkan salinan edisi khusus. Bahkan jika mereka menggandakan harga permainan, atau bahkan melipatgandakannya tiga kali, kita akan membayar berapapun harganya!",
  ui_story_5081_50810201_44_dialog_content = "Sepertinya ini akan sangat mahal ya... Kamu baik-baik saja dengan ini, Jomu?",
  ui_story_5081_50810201_45_dialog_content = "Tentu saja! Semakin mahal harganya sekarang, semakin berharga nilainya di masa depan!",
  ui_story_5081_50810201_46_dialog_content = "Jika saya harus memilih jenis permainan favorit, itu adalah yang membuat orang mengeluarkan uang mereka dengan berlebihan.",
  ui_story_5081_50810201_47_dialog_content = "Jadi kamu bersedia membeli permainan fantasi ini bahkan <color=#FFB400>dengan harga premium</color>... Saya hampir tidak percaya, Jomu.",
  ui_story_5081_50810201_48_dialog_content = "Kalian semua mengumpulkan sampah dan bagian lainnya untuk membangun kembali Colossus, tapi entah bagaimana kalian bersedia membayar uang yang baik untuk video game.",
  ui_story_5081_50810201_49_dialog_content = "Anda hanya tidak mengerti, PlayerName.",
  ui_story_5081_50810201_50_dialog_content = "Aku sudah memberitahumu berapa banyak waktu dan usaha yang dibutuhkan untuk menemukan, menggali, memulihkan, dan merilis permainan seperti ini...",
  ui_story_5081_50810201_51_dialog_content = "Apakah kamu pikir pekerjaan semacam ini bisa dilakukan oleh studio setengah matang dengan sumber daya minimal?",
  ui_story_5081_50810201_52_dialog_content = "Sepertinya tidak.",
  ui_story_5081_50810201_53_dialog_content = "Beritahu saya, menurutmu apa aspek terpenting dari sebuah video game?",
  ui_story_5081_50810201_54_dialog_content = "Itu... dapat dimainkan?",
  ui_story_5081_50810201_55_dialog_content = "Salah! Itu para gamer!",
  ui_story_5081_50810201_56_dialog_content = "Jika kamu melakukan sesuatu yang tercela, seperti memaksa profesional untuk mengembangkan game kamu atau mencuri versi edisi terbatas...",
  ui_story_5081_50810201_57_dialog_content = "Kamu akan dikucilkan oleh seluruh komunitas game!",
  ui_story_5081_50810201_58_dialog_content = "Tidak peduli sehebat apa permainan yang kamu miliki, tidak ada seorang pun yang akan berada di sekitarmu untuk berbagi kegembiraannya.",
  ui_story_5081_50810201_59_dialog_content = "Ini adalah hasil paling tragis yang bisa dibayangkan oleh setiap gamer! Tidak kah kamu mengerti?",
  ui_story_5081_50810201_60_dialog_content = "Benar! Bahkan permainan seperti Tetrablox menjadi lebih menyenangkan ketika dua orang ikut bermain!",
  ui_story_5081_50810201_61_dialog_content = "Lebih jauh lagi, ada banyak orang terkenal di dalam komunitas game—orang-orang yang pasti tidak ingin Anda sakiti.",
  ui_story_5081_50810201_62_dialog_content = "Terutama karena mereka mungkin sedang mencari banyak periferal gaming baru... Heheheh.",
  ui_story_5081_50810201_63_dialog_content = "Pemain game, huh...",
  ui_story_5081_50810201_64_dialog_content = "Saya cukup yakin ada banyak orang seperti itu di Rediesel Wrench, 'kan?",
  ui_story_5081_50810201_65_dialog_content = "Kalian pasti kehabisan game untuk dimainkan jika kalian bersedia datang jauh-jauh ke Umbraton untuk mereka...",
  ui_story_5081_50810201_66_dialog_content = "Hai! Mari kita luruskan sesuatu di sini: kita benar-benar mampu menggali mesin game dan cartridge semuanya sendiri!",
  ui_story_5081_50810201_67_dialog_content = "Tapi orang-orang bodoh yang canggung itu tidak tahu cara merawat barang dengan benar, jadi barang-barang kita selalu rusak!",
  ui_story_5081_50810201_68_dialog_content = "Kamu pikir aku bisa memperbaiki kekacauan seperti ini sendiri? Tidak, sama sekali tidak...",
  ui_story_5081_50810201_69_dialog_content = "Jika aku bisa membawa beberapa ilmuwan Illuminan kembali bersamaku, aku yakin aku bisa membuat game yang akan mengguncang seluruh dunia!",
  ui_story_5081_50810201_70_dialog_content = "Tunggu sebentar, saya rasa saya mungkin tahu ilmuwan Illumina yang tepat untuk pekerjaan ini...",
  ui_story_5081_50810201_71_dialog_content = "Ah! Aku terlalu asyik berbicara dengan kalian dan hampir lupa!",
  ui_story_5081_50810201_72_dialog_content = "(Aku bertanya-tanya apakah hilangnya Gronru ada hubungannya dengan pra-penjualan game fantasi ini?)",
  ui_story_5081_50810201_73_dialog_content = "(Waktunya tidak bisa lebih tepat lagi...)",
  ui_story_5081_50810201_74_dialog_content = "(Memulai pencarianku dengan game ini sama sekali bukan pilihan yang buruk. Nah, sekarang...)",
  ui_story_5081_50810201_75_dialog_content = "Hmm... Bisakah kamu beri tahu aku di mana mereka menjual game ini?",
  ui_story_5081_50810201_76_dialog_content = "Tentu saja, temanku! Aku bahkan akan memberimu diskon dua puluh persen untuk informasi itu—",
  ui_story_5081_50810201_77_dialog_content = "Taring Tersembunyi.",
  ui_story_5081_50810201_78_dialog_content = "Hmm…",
  ui_story_5081_50810201_79_dialog_content = "Ya, benar—Taring Tersembunyi!",
  ui_story_5081_50810201_80_dialog_content = "Mekah bagi setiap gamer di Astra! Satu-satunya arcade tertinggi di Umbraton!",
  ui_story_5081_50810201_81_dialog_content = "Aku masih belum membayar informasi itu padamu, tahu kan...",
  ui_story_5081_50810201_82_dialog_content = "Ini juga tempat berkumpulnya para gamer level tinggi. Sebagian besar, jika tidak semua, rekor video game Astra telah ditetapkan di sana.",
  ui_story_5081_50810201_83_dialog_content = "... Kedengarannya seperti aula kehormatan yang nyata, kurasa.",
  ui_story_5081_50810201_84_dialog_content = "(Saya bertanya-tanya apakah skor tinggi Gronru ada yang direkam di sana?)",
  ui_story_5081_50810201_85_dialog_content = "(Kamu pasti di jalur yang benar sekarang, Caelestite! Pertahankan!)",
  ui_story_5081_50810201_86_dialog_content = "Sayangnya, kamu mungkin tidak akan bisa mendapatkan salinan meskipun kamu menambahkan nama kamu ke daftar sekarang.",
  ui_story_5081_50810201_87_dialog_content = "Hah? Tapi saya pikir ini adalah penjualan perdana! Apakah saya seharusnya memesan tempat di daftar tunggu?",
  ui_story_5081_50810201_88_dialog_content = "Itu tidak ada hubungannya dengan daftar tunggu...",
  ui_story_5081_50810201_89_dialog_content = "Kartu video game sangat berharga, jadi arcade melakukan tinjauan ketat terhadap setiap pembeli potensial.",
  ui_story_5081_50810201_90_dialog_content = "Ini semua untuk mencegah calo dan pelaku jahat lainnya terlibat sehingga gamer sejati memiliki kesempatan untuk menikmati game.",
  ui_story_5081_50810201_91_dialog_content = "Tidak heran Jomu tampak begitu gugup tentang hal itu.",
  ui_story_5081_50810201_92_dialog_content = "Haha, sangat lucu, bos. Perhatikan kata-kataku: Aku akan mendapatkan hak untuk membeli salinan dari \"B\" secara adil dan jujur!",
  ui_story_5081_50810201_93_dialog_content = "\"B\"?",
  ui_story_5081_50810201_94_dialog_content = "Itu benar. Langkah paling krusial dalam mengamankan salinan game ini adalah bermain melawan \"B.\"",
  ui_story_5081_50810201_95_dialog_content = "Sebagai pemilik Hidden Fangs, dia juga salah satu gamer terhebat di Astra...",
  ui_story_5081_50810201_96_dialog_content = "Itulah cara \"B\" menguji kamu untuk melihat apakah cinta kamu terhadap video game itu nyata atau tidak.",
  ui_story_5081_50810201_97_dialog_content = "Saya tidak berpikir seorang pemula seperti Anda bisa menanganinya.",
  ui_story_5081_50810201_98_dialog_content = "A-Apa yang kamu bicarakan? Aku juga sudah main banyak game!",
  ui_story_5081_50810201_99_dialog_content = "Heheheh. Aku hanya perlu memberitahumu sedikit lebih banyak tentang \"B,\" sehingga kamu bisa berkubang dalam keputusasaan...",
  ui_story_5081_50810301_1_dialog_content = "<color=#e8d9bb>Sebuah tubuh yang sepenuhnya terbuat dari permainan.</color>",
  ui_story_5081_50810301_2_dialog_content = "<color=#e8d9bb>Dengan komputer sebagai hati, dan data sebagai darah.</color>",
  ui_story_5081_50810301_3_dialog_content = "<color=#e8d9bb>Dia telah bermain ribuan permainan tanpa kalah satu kali pun.</color>",
  ui_story_5081_50810301_4_dialog_content = "<color=#e8d9bb>Keberadaannya adalah misteri baik bagi Aurorian maupun Eclipsite.</color>",
  ui_story_5081_50810301_5_dialog_content = "<color=#e8d9bb>Pada sebagian besar hari, dia bersembunyi di sudut-sudut tergelap arcade, bergumam pada dirinya sendiri tentang betapa tidak bergunanya dia.</color>",
  ui_story_5081_50810301_6_dialog_content = "<color=#e8d9bb>Dia hanya memiliki satu keinginan dalam hidup: jumlah game yang tak terbatas untuk dimainkan!</color>",
  ui_story_5081_50810301_7_dialog_content = "...",
  ui_story_5081_50810301_8_dialog_content = "Berhenti saja! Ceritanya makin lama makin gila!",
  ui_story_5081_50810301_9_dialog_content = "Jadi untuk menjelaskannya dengan sederhana... \"B\" adalah seorang gamer yang telah memainkan banyak sekali game dan belum pernah kalah satu kali pun?",
  ui_story_5081_50810301_10_dialog_content = "Untuk lebih tepatnya—",
  ui_story_5081_50810301_11_dialog_content = "Dia memiliki beberapa catatan penyelesaian tercepat dan skor tertinggi di seluruh Astra, dan dia juga pemain Tetrablox paling terkenal sepanjang masa.",
  ui_story_5081_50810301_12_dialog_content = "Dia terus mencetak rekor dalam mode infinity Tetrablox juga. Beberapa bahkan mengatakan dia telah mencapai level terakhir dari permainan itu...",
  ui_story_5081_50810301_13_dialog_content = "Bisakah game seperti itu benar-benar memiliki level terakhir?",
  ui_story_5081_50810301_14_dialog_content = "Dari yang aku dengar, permainan ini membeku setelah kamu menyelesaikan sejumlah level tertentu...",
  ui_story_5081_50810301_15_dialog_content = "Bagaimanapun juga, ini bukan sesuatu yang bisa dilakukan oleh Aurorian biasa.",
  ui_story_5081_50810301_16_dialog_content = "Apakah dia semacam monster game yang muncul dari kedalaman terdalam reruntuhan kuno? Bisa jadi dia adalah!",
  ui_story_5081_50810301_17_dialog_content = "Tenang, aku sudah paham. Dia benar-benar jago main video game...",
  ui_story_5081_50810301_18_dialog_content = "Dalam setiap kasus, banyak penantang yang pergi ke Hidden Fangs mencari \"B,\" hanya untuk pergi dengan terhuyung-huyung dalam kekalahan!",
  ui_story_5081_50810301_19_dialog_content = "Sebenarnya, saya hanya ingin bertanya seputar beberapa informasi. Saya sama sekali tidak tertarik untuk menantang \"B\"!",
  ui_story_5081_50810301_20_dialog_content = "Orang ini juga tidak terdengar mudah didekati...",
  ui_story_5081_50810301_21_dialog_content = "Jangan khawatir, bos! Saya lebih dari senang untuk bertanya atas nama Anda, dan untuk diskon lima persen—",
  ui_story_5081_50810301_22_dialog_content = "Kamu akan baik-baik saja, jadi pergilah ke sana dan lihatlah sendiri! Ada berbagai jenis gamer di sana, kamu akan melihat.",
  ui_story_5081_50810301_23_dialog_content = "Terima kasih teman-teman. Tunjukkan jalannya!",
  ui_story_5081_50810301_24_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5081_50810301_25_dialog_content = "... Ini benar-benar tempatnya?",
  ui_story_5081_50810301_26_dialog_content = "Ini jauh lebih nyaman daripada yang saya kira!",
  ui_story_5081_50810301_27_dialog_content = "Saya bahkan merasa nostalgia, seolah-olah saya akan duduk dan memainkan salah satu game favorit saya.",
  ui_story_5081_50810301_28_dialog_content = "Ini hanya arcade, tahu. Seperti apa yang kamu bayangkan?",
  ui_story_5081_50810301_29_dialog_content = "Kamu serius bertanya itu padaku setelah deskripsi gila yang baru saja kamu berikan?",
  ui_story_5081_50810301_30_dialog_content = "Setidaknya, aku pikir itu akan penuh dengan gangster Umbraton atau sesuatu...",
  ui_story_5081_50810301_31_dialog_content = "Saya yakin pemilik toko kecil yang nyaman ini pasti adalah seseorang yang sangat mencintai hidup!",
  ui_story_5081_50810301_32_dialog_content = "...",
  ui_story_5081_50810301_33_dialog_content = "Hah?",
  ui_story_5081_50810301_34_dialog_content = "!",
  ui_story_5081_50810301_35_dialog_content = "Saya tidak tahu tentang hidup, tapi dia pasti sangat suka game...",
  ui_story_5081_50810301_36_dialog_content = "Hmm? Ada apa, PlayerName? Sepertinya ada yang mengganggu Anda.",
  ui_story_5081_50810301_37_dialog_content = "Untuk beberapa alasan... rasanya seperti ada yang memperhatikanku.",
  ui_story_5081_50810301_38_dialog_content = "Kamu hanya berkhayal. Pencahayaan di sini tidak terlalu terang, setelah semua.",
  ui_story_5081_50810301_39_dialog_content = "Selain itu, semua orang terlalu sibuk bermain game untuk memperhatikan kamu...",
  ui_story_5081_50810301_40_dialog_content = "Kamu benar, saya rasa saya hanya khawatir tanpa alasan.",
  ui_story_5081_50810301_41_dialog_content = "Jadi, di mana pemilik arcade itu? Untuk sesuatu yang penting seperti pra-penjualan game, hampir tidak ada iklan tentang itu.",
  ui_story_5081_50810301_42_dialog_content = "Bisakah dia sedang menguji seseorang untuk melihat apakah mereka layak membeli permainan ini?",
  ui_story_5081_50810301_43_dialog_content = "Jangan khawatir, bos. Pemiliknya adalah orang yang sangat bersemangat, dan saya yakin dia akan menjawab Anda jika Anda memanggilnya—tentu saja, dengan keras.",
  ui_story_5081_50810301_44_dialog_content = "Oke, uh... Permisi! Bisakah saya berbicara dengan \"B\"?",
  ui_story_5081_50810301_45_dialog_content = "?",
  ui_story_5081_50810301_46_dialog_content = "Apakah itu penantang baru?",
  ui_story_5081_50810301_47_dialog_content = "Tunggu, saya pikir saya pernah melihat pakaian itu sebelumnya... Bukankah dia orang terkenal?",
  ui_story_5081_50810301_48_dialog_content = "Ya! Ini akan menjadi keren!",
  ui_story_5081_50810301_49_dialog_content = "Kamu menjebakku, Jomu!",
  ui_story_5081_50810301_50_dialog_content = "Maaf bos, tetapi karena Anda tidak membayar untuk informasi saya, saya harus memikirkan cara lain untuk mengumpulkan kompensasi saya. Semoga beruntung!",
  ui_story_5081_50810301_51_dialog_content = "...",
  ui_story_5081_50810301_52_dialog_content = "Kamu punya banyak nyali, memanggil \"B\" seperti itu...",
  ui_story_5081_50810301_53_dialog_content = "Selamat datang di Hidden Fangs! Semoga kamu siap untuk tantangan!",
  ui_story_5081_50810301_54_dialog_content = "...Hah?",
  ui_story_5081_50810301_55_dialog_content = "Oh? Nah, jika bukan PlayerName!",
  ui_story_5081_50810301_56_dialog_content = "Ini PlayerName, cicit!",
  ui_story_5081_50810301_57_dialog_content = "Sork? Bekk?",
  ui_story_5081_50810301_58_dialog_content = "Apa yang kalian berdua lakukan di sini?",
  ui_story_5081_50810301_59_dialog_content = "Itu baris saya, teman! Apa yang kamu... Hei! Jomu juga di sini!",
  ui_story_5081_50810301_60_dialog_content = "Berhenti bersembunyi di belakang PlayerName, kamu pemalas! Kembalikan uang yang kamu hutang kepadaku, atau else...",
  ui_story_5081_50810301_61_dialog_content = "Selamatkan aku, bos!",
  ui_story_5081_50810301_62_dialog_content = "Tidak ada kesempatan, terutama setelah kamu menjebakku seperti itu...",
  ui_story_5081_50810301_63_dialog_content = "Yah... Sayangnya, aku hanya membawa cukup uang untuk membeli game ini hari ini, kamu tahu.",
  ui_story_5081_50810301_64_dialog_content = "Sebagai karyawan di toko ini, tentunya kamu tidak ingin saya pergi dengan tangan kosong, bukan?",
  ui_story_5081_50810301_65_dialog_content = "Sork bekerja di sini?",
  ui_story_5081_50810301_66_dialog_content = "Dia baru saja menyambutmu seperti seorang karyawan, bukan?",
  ui_story_5081_50810301_67_dialog_content = "Yah... Ceritanya panjang.",
  ui_story_5081_50810301_68_dialog_content = "Awalnya, Bekk dan saya dipekerjakan untuk membeli beberapa game baru untuk seorang klien di sini di Umbraton.",
  ui_story_5081_50810301_69_dialog_content = "Tapi pada akhirnya, kita ditipu oleh seorang penjual yang tidak jujur dan berakhir dengan banyak kartrid sampah.",
  ui_story_5081_50810301_70_dialog_content = "Tanpa uang dan bisnis yang harus diselesaikan, kami memutuskan untuk menghabiskan malam di arcade ini...",
  ui_story_5081_50810301_71_dialog_content = "Jadi, pemiliknya cukup baik untuk menawarkan kalian pekerjaan selama kalian di sini?",
  ui_story_5081_50810301_72_dialog_content = "Jenis? Hehe, lebih tepatnya penasaran.",
  ui_story_5081_50810301_73_dialog_content = "Pemilik ingin melihat seberapa baik Bekk dan aku bekerja sama, jadi dia mengundang kami untuk bermain sebuah permainan.",
  ui_story_5081_50810301_74_dialog_content = "Jika kita menang, dia akan menutupi semua kerugian kita. Jika kita kalah, kita harus bekerja untuknya.",
  ui_story_5081_50810301_75_dialog_content = "Sial! Kita nyaris menang juga...",
  ui_story_5081_50810301_76_dialog_content = "Kami kalah tipis, cuit!",
  ui_story_5081_50810301_77_dialog_content = "Kalian berdua \"kalah tipis\"? Ha, jangan buat aku tertawa!",
  ui_story_5081_50810301_78_dialog_content = "Jika ini tentang \"B\" yang kita bicarakan di sini, dia mungkin telah menginjak-injak kalian sampai ke tanah!",
  ui_story_5081_50810301_79_dialog_content = "Apa? Bagaimana kamu tahu dia menggunakan kakinya? Itulah cara dia bisa menggunakan dua pengendali sekaligus...",
  ui_story_5081_50810301_80_dialog_content = "Dia mengalahkan kami dengan menggunakan tangan dan kaki sekaligus!",
  ui_story_5081_50810301_81_dialog_content = "D-Dia melakukannya?",
  ui_story_5081_50810301_82_dialog_content = "Pokoknya, satu hal mengarah ke hal lain, dan sekarang kita berdua bekerja di sini...",
  ui_story_5081_50810301_83_dialog_content = "Ketika tidak sibuk, kami bahkan bisa bermain permainan meja dengan pelanggan kami.",
  ui_story_5081_50810301_84_dialog_content = "Orang bisa benar-benar tenggelam dalam game strategi di sini—itu bukan sesuatu yang bisa kamu temukan di kebanyakan tempat...",
  ui_story_5081_50810301_85_dialog_content = "Meskipun permainan negosiasi jauh lebih baik, cuit!",
  ui_story_5081_50810301_86_dialog_content = "Jadi kalian berdua terjebak dalam permainan di sini juga, ya?",
  ui_story_5081_50810301_87_dialog_content = "Benar-benar ada sesuatu yang istimewa tentang tempat ini... tapi mengapa saya tidak melihat pemilik toko di mana pun?",
  ui_story_5081_50810301_88_dialog_content = "\"B\" memiliki warisan demi-human yang langka, sama seperti kita. Tidak mudah baginya untuk keluar saat siang hari.",
  ui_story_5081_50810301_89_dialog_content = "Dia juga menghadapi banyak masalah di masa lalu karena keturunannya. Jadi, tolong...",
  ui_story_5081_50810301_90_dialog_content = "Coba untuk memahami.",
  ui_story_5081_50810301_91_dialog_content = "A-Aku benar-benar paham!",
  ui_story_5081_50810301_92_dialog_content = "Aku hanya punya sesuatu untuk ditanyakan padanya, itu saja. Apakah kamu mau menyampaikan pesan kepadanya?",
  ui_story_5081_50810301_93_dialog_content = "Tentu saja, PlayerName.",
  ui_story_5081_50810301_94_dialog_content = "Biarkan aku menyelesaikan permainan ini... Maksudku, menangani pelanggan-pelanggan ini, dan aku akan langsung mengerjakannya.",
  ui_story_5081_50810301_95_dialog_content = "Tentu.",
  ui_story_5081_50810301_96_dialog_content = "Hah? Saya bertanya-tanya kemana Odi dan Jomu pergi...",
  ui_story_5081_50810301_97_dialog_content = "Apa kamu bercanda? Aku telah menyusun banyak strategi baru hanya agar bisa mendapatkan salinan gameku!",
  ui_story_5081_50810301_98_dialog_content = "Lihat, saya bahkan memodifikasi controller saya sendiri... Lihatlah jika kamu mau!",
  ui_story_5081_50810301_99_dialog_content = "Wah, keren sekali!",
  ui_story_5081_50810301_100_dialog_content = "Maafkan saya teman, tapi apakah kamu ingin bermain beberapa putaran Rediesel Hold 'em denganku? Saya pikir kita mungkin cukup seimbang!",
  ui_story_5081_50810301_101_dialog_content = "Tapi di tempat asal saya, biasanya yang kalah menanggung biaya pemenang untuk sisa hari itu. Tertarik?",
  ui_story_5081_50810301_102_dialog_content = "Tentu, saya siap!",
  ui_story_5081_50810301_103_dialog_content = "Sepertinya semua orang sedang bersenang-senang banyak.",
  ui_story_5081_50810301_104_dialog_content = "Saya harus memainkan sesuatu juga, agar saya tidak terlalu menonjol...",
  ui_story_5081_50810301_105_dialog_content = "Hmm, apa yang harus dipilih...",
  ui_story_5081_50810301_106_dialog_content = "Ini tampak cukup menyenangkan. Aurora All-Star Racing—Aku harusnya cukup mahir dalam game balap, bukan?",
  ui_story_5081_50810301_107_dialog_content = "Sepertinya sebaiknya aku memasukkan token dan mencari tahu!",
  ui_story_5081_50810301_108_dialog_content = "Wow, lihatlah semua pilihan kendaraan ini! Aku bahkan bisa memilih senjata juga!",
  ui_story_5081_50810301_109_dialog_content = "Baiklah, saya pikir saya sudah memahami sekarang. Ayo pergi!",
  ui_story_5081_50810301_110_dialog_content = "<color=#e8d9bb>Meskipun grafik permainan cukup sederhana, pemain masih merasa seolah-olah mereka telah dipindahkan ke dunia baru.</color>",
  ui_story_5081_50810301_111_dialog_content = "<color=#e8d9bb>Gambar yang detail, ditambah dengan presentasi yang dibesar-besarkan dan efek suara khusus, menciptakan pengalaman yang mendalam.</color>",
  ui_story_5081_50810301_112_dialog_content = "Apakah ini cara saya harus mengambil tikungan? Saya benar-benar mengerti sekarang!",
  ui_story_5081_50810301_113_dialog_content = "Saya mengumpulkan Lumina setiap kali saya melayang di sekitar sudut, jadi apakah saya harus menembakkannya ke Eclipsites? Tebak saya harus mencobanya!",
  ui_story_5081_50810301_114_dialog_content = "Tunggu... Eclipsite ini sedikit terlalu kuat, bukan?",
  ui_story_5081_50810301_115_dialog_content = "Uh-oh... Kenapa aku tidak bisa melihat jejak-jejak Lumina?",
  ui_story_5081_50810301_116_dialog_content = "Oh, pria... Game ini tidak mencakup kemampuan terkuat Caelestite! Ini benar-benar tidak adil!",
  ui_story_5081_50810301_117_dialog_content = "Sebenarnya, ini adalah aspek <color=#FFB400>teradil</color> dari game ini.",
  ui_story_5081_50810301_118_dialog_content = "Hah?",
  ui_story_5081_50810301_119_dialog_content = "<color=#e8d9bb>Pemain 2 telah masuk ke dalam permainan!</color>",
  ui_story_5081_50810301_120_dialog_content = "Pemain lain... telah bergabung dalam permainanku?",
  ui_story_5081_50810301_121_dialog_content = "... J-Jangan lihat aku!",
  ui_story_5081_50810301_122_dialog_content = "Hanya tetapkan mata Anda pada layar Anda, atau Anda akan menabrak.",
  ui_story_5081_50810301_123_dialog_content = "Maaf!",
  ui_story_5081_50810301_124_dialog_content = "Ini pertama kalinya aku bermain, jadi maaf jika aku menghalangi jalanmu...",
  ui_story_5081_50810301_125_dialog_content = "Jangan khawatir, akan kutunjukkan cara bermain.",
  ui_story_5081_50810301_126_dialog_content = "Kamu memiliki banyak potensi. Fokuskan perhatianmu, dan itu tidak akan menjadi masalah.",
  ui_story_5081_50810301_127_dialog_content = "O-Oke kalau begitu...",
  ui_story_5081_50810301_128_dialog_content = "<color=#e8d9bb>Peringatan! Peringatan! Gelombang besar Eclipsite sedang mendekat!</color>",
  ui_story_5081_50810301_129_dialog_content = "Bersiaplah, kita lakukan ini bersama.",
  ui_story_5081_50810301_130_dialog_content = "Baik!",
  ui_story_5081_50810302_1_dialog_content = "?",
  ui_story_5081_50810302_2_dialog_content = "A-Aku masih hidup?",
  ui_story_5081_50810302_3_dialog_content = "Aku tidak percaya kita berhasil keluar dari gerombolan Eclipsite itu!",
  ui_story_5081_50810302_4_dialog_content = "Apakah ini berarti aku hampir menyelesaikan tahap ini?",
  ui_story_5081_50810302_5_dialog_content = "... Apakah kamu bersenang-senang?",
  ui_story_5081_50810302_6_dialog_content = "Menyenangkan? Tentu saja menyenangkan! Saya hanya tidak yakin bisa bermain selama itu tanpa bantuanmu.",
  ui_story_5081_50810302_7_dialog_content = "Itu tidak selalu benar. Kamu harus mengandalkan dirimu sendiri untuk bagian selanjutnya... tapi aku yakin kamu akan baik-baik saja.",
  ui_story_5081_50810302_8_dialog_content = "Hah?",
  ui_story_5081_50810302_9_dialog_content = "<color=#e8d9bb>Pemain 2 telah meninggalkan permainan!</color>",
  ui_story_5081_50810302_10_dialog_content = "Kamu pergi begitu saja?",
  ui_story_5081_50810302_11_dialog_content = "... Aku sudah bilang jangan menatapku! Tatap layarnya!",
  ui_story_5081_50810302_12_dialog_content = "Benar! Saya tidak bisa kehilangan fokus sekarang...",
  ui_story_5081_50810302_13_dialog_content = "Kamu sudah membantu saya melewati bagian terberat, jadi sekarang terserah saya untuk menyelesaikan sisanya!",
  ui_story_5081_50810302_14_dialog_content = "Apa pun yang dilemparkan game ini padaku, aku bisa menanganinya! Belokan tajam, Eclipsites, sebut saja!",
  ui_story_5081_50810302_15_dialog_content = "Oh? Saya tidak menyadari bahwa kamu juga bermain, PlayerName... dan kamu tampak cukup bersemangat!",
  ui_story_5081_50810302_16_dialog_content = "Tunggu, ini adalah tahapan Tempest Gorge, bukan? Saya tahu Anda sama sekali tidak sadar betapa sulitnya balapan ini, tapi coba untuk tidak langsung kalah...",
  ui_story_5081_50810302_17_dialog_content = "Wow! Ayo lihat, Odi. Dia sudah melewati lima belokan hairpin berturut-turut di Tempest Gorge!",
  ui_story_5081_50810302_18_dialog_content = "Tidak mungkin! Bahkan aku tidak bisa melewati gelombang Eclipsite itu... Aku menolak untuk menerima ini!",
  ui_story_5081_50810302_19_dialog_content = "Wow! Lihat ini, semuanya!",
  ui_story_5081_50810302_20_dialog_content = "Hah? Kenapa tiba-tiba semua orang mengerubungiku?",
  ui_story_5081_50810302_21_dialog_content = "<color=#e8d9bb>Dengan tatapan penuh harap dari semua orang, membersihkan panggung tiba-tiba menjadi lebih sulit.</color>",
  ui_story_5081_50810302_22_dialog_content = "<color=#e8d9bb>Tapi pada akhirnya, arcade meledak dalam sorak sorai saat balapan berakhir dengan kesuksesan yang menarik dan sukses.</color>",
  ui_story_5081_50810302_23_dialog_content = "Wow!",
  ui_story_5081_50810302_24_dialog_content = "Seorang pemula berhasil melewati Tempest Gorge dalam percobaan pertamanya? Bagaimana itu mungkin?",
  ui_story_5081_50810302_25_dialog_content = "Saya yakin pria ini sebenarnya adalah seorang gamer profesional!",
  ui_story_5081_50810302_26_dialog_content = "Darimana asalmu, orang baru? Apakah kamu kemari untuk memamerkan kemampuanmu?",
  ui_story_5081_50810302_27_dialog_content = "I-Apakah tahapan ini benar-benar sebegitu sulitnya?",
  ui_story_5081_50810302_28_dialog_content = "Jangan salah paham, semua orang! Saya tidak istimewa, dan ini adalah kali pertama saya di sini. Selain itu, saya mendapatkan banyak bantuan dari pemain lain...",
  ui_story_5081_50810302_29_dialog_content = "Ketika aku berjuang melalui belokan tajam itu, dia duduk tepat di sebelahku... Hah?",
  ui_story_5081_50810302_30_dialog_content = "Benarkah? Karena saya tidak melihat siapa pun.",
  ui_story_5081_50810302_31_dialog_content = "Barusan dia ada di sini!",
  ui_story_5081_50810302_32_dialog_content = "Seorang Aurorian kecil... yang tampaknya belum sepenuhnya terbangun...",
  ui_story_5081_50810302_33_dialog_content = "Kurasa dia mungkin adalah demi-human kelelawar, dan rambutnya terlihat seperti lampu-lampu di arcade...",
  ui_story_5081_50810302_34_dialog_content = "Heh... Kau punya ide tidak sih, siapa yang baru saja kau deskripsikan?",
  ui_story_5081_50810302_35_dialog_content = "Cuit! Manusia kecil setengah kelelawar!",
  ui_story_5081_50810302_36_dialog_content = "Itu terdengar sangat mirip dengan Batia, pemilik arcade!",
  ui_story_5081_50810401_1_dialog_content = "...",
  ui_story_5081_50810401_2_dialog_content = "Rasanya seperti aku sedang menunggu untuk diwawancarai...",
  ui_story_5081_50810401_3_dialog_content = "Jangan tampak begitu gugup. Jika \"B\" bersedia bermain denganmu, itu pasti berarti kamu telah menarik perhatiannya.",
  ui_story_5081_50810401_4_dialog_content = "Aku bisa memanggilnya kalau kau mau.",
  ui_story_5081_50810401_5_dialog_content = "Kita tidak akan mendapatkan pesanan lebih awal hari ini jika kita tidak mendapatkan penantang baru.",
  ui_story_5081_50810401_6_dialog_content = "Itu berarti kita harus terus bekerja di sini, cit cit cuit!",
  ui_story_5081_50810401_7_dialog_content = "Saya mengerti. Mari kita lakukan ini!",
  ui_story_5081_50810401_8_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5081_50810401_9_dialog_content = "... Oh.",
  ui_story_5081_50810401_10_dialog_content = "... Hmm.",
  ui_story_5081_50810401_11_dialog_content = "... Fiuh.",
  ui_story_5081_50810401_12_dialog_content = "Permisi...",
  ui_story_5081_50810401_13_dialog_content = "Eh... Iya!",
  ui_story_5081_50810401_14_dialog_content = "... Apa ada yang salah dengan sapaanku barusan?",
  ui_story_5081_50810401_15_dialog_content = "<size=30>(... Atau mungkin saya seharusnya berkomunikasi dengannya dalam istilah arcade?)</size>",
  ui_story_5081_50810401_16_dialog_content = "Tidak... Hmm...",
  ui_story_5081_50810401_17_dialog_content = "!",
  ui_story_5081_50810401_18_dialog_content = "D-Apakah kamu... membutuhkan sesuatu dariku?",
  ui_story_5081_50810401_19_dialog_content = "Ini bukan hal istimewa, sungguh.",
  ui_story_5081_50810401_20_dialog_content = "Aku seorang Caelestite, dan namaku sama dengan yang aku gunakan dalam game.",
  ui_story_5081_50810401_21_dialog_content = "Aku datang ke sini mencari seseorang. Bisakah kamu beritahu jika kamu telah melihat...",
  ui_story_5081_50810401_22_dialog_content = "A-Aku tidak! Aku pasti tidak menerima anak-anak ketika mereka kabur dari rumah dan membiarkan mereka bermain video game di sini!",
  ui_story_5081_50810401_23_dialog_content = "K-K-Kamu salah tempat... Sumpah!",
  ui_story_5081_50810401_24_dialog_content = "Hah? Apakah aku benar-benar terlihat seperti orang tua yang tidak puas bagimu?",
  ui_story_5081_50810401_25_dialog_content = "Oh, kurasa tidak...",
  ui_story_5081_50810401_26_dialog_content = "Itu karena saya bukan! Saya datang mencari seseorang yang tampak sangat muda tetapi sebenarnya jauh lebih tua dari yang tampaknya! Dia adalah salah satu ilmuwan terhebat Illumina!",
  ui_story_5081_50810401_27_dialog_content = "Dia meninggalkan semua tugas penting laboratoriumnya dan menghilang tanpa penjelasan apa pun baru-baru ini.",
  ui_story_5081_50810401_28_dialog_content = "Dia sangat menikmati video game, jadi saya pikir ini akan menjadi tempat yang baik untuk mulai mencari...",
  ui_story_5081_50810401_29_dialog_content = "Namanya Gronru. Apakah kamu tahu sesuatu tentang dia?",
  ui_story_5081_50810401_30_dialog_content = "Aku tidak mau.",
  ui_story_5081_50810401_31_dialog_content = "I-Begitukah...",
  ui_story_5081_50810401_32_dialog_content = "(Itu adalah respons yang sangat cepat... sedikit terlalu cepat, jika kamu bertanya padaku.)",
  ui_story_5081_50810401_33_dialog_content = "(Apakah dia mencoba menghindari membuat keributan? Masuk akal, mengingat ini seharusnya menjadi surga bagi semua gamer... Tunggu, gamer...)",
  ui_story_5081_50810401_34_dialog_content = "Maaf! Saya rasa saya telah mengajukan pertanyaan yang salah.",
  ui_story_5081_50810401_35_dialog_content = "Orang-orang di sini mungkin menggunakan nama pemain mereka, 'kan?",
  ui_story_5081_50810401_36_dialog_content = "Sekarang apa nama pemain Gronru lagi? Benar! Dia dikenal dengan Gronkenstein Ruu! Apakah kamu pernah mendengar tentang dia?",
  ui_story_5081_50810401_37_dialog_content = "Gronken apa?",
  ui_story_5081_50810401_38_dialog_content = "Gronkenstein Ruu!",
  ui_story_5081_50810401_39_dialog_content = "Grompen... Stein?",
  ui_story_5081_50810401_40_dialog_content = "Tidak, Gronkenst—aduh! Aku menggigit lidahku!",
  ui_story_5081_50810401_41_dialog_content = "Pokoknya... Aku tidak kenal ilmuwan terkenal mana pun.",
  ui_story_5081_50810401_42_dialog_content = "Saya telah memiliki banyak pemain datang ke toko saya akhir-akhir ini... Itu agak mustahil... untuk mengingat semua nama mereka.",
  ui_story_5081_50810401_43_dialog_content = "Maaf, tapi... Saya rasa saya tidak bisa banyak membantu.",
  ui_story_5081_50810401_44_dialog_content = "Tunggu sebentar, biarkan aku berpikir. Mungkin ada petunjuk lain yang bisa aku gunakan di sini...",
  ui_story_5081_50810401_45_dialog_content = "Anda... tidak suka bermain game, kan?",
  ui_story_5081_50810401_46_dialog_content = "Hah?",
  ui_story_5081_50810401_47_dialog_content = "Kamu tidak datang ke sini untuk bermain game... Kamu datang untuk mencari seseorang.",
  ui_story_5081_50810401_48_dialog_content = "Ketika kita bekerja sama dalam Aurora All-Star Racing dan berhasil melewati Tempest Gorge...",
  ui_story_5081_50810401_49_dialog_content = "Tidak ada bedanya dengan sekarang. Kamu tidak ingin menonjol, jadi kamu merasa harus bermain, kan?",
  ui_story_5081_50810401_50_dialog_content = "Maaf... Seharusnya aku tidak pernah mengganggumu!",
  ui_story_5081_50810401_51_dialog_content = "H-Hei! Jangan bilang begitu.",
  ui_story_5081_50810401_52_dialog_content = "Aku sangat senang saat kita bermain bersama tadi! Itu sangat mengasyikkan!",
  ui_story_5081_50810401_53_dialog_content = "Tapi begitu aku tenang, aku ingat betapa pentingnya misi saya, dan saya harus kembali ke tugas yang ada di tangan. Itulah sebabnya...",
  ui_story_5081_50810401_54_dialog_content = "...",
  ui_story_5081_50810401_55_dialog_content = "Apakah aku membuatnya kabur karena terlalu fokus pada misiku?",
  ui_story_5081_50810401_56_dialog_content = "Kamu harus mencoba berbicara dengannya lagi. Mengasihani diri sendiri tidak akan memberimu kebaikan apa pun.",
  ui_story_5081_50810401_57_dialog_content = "Anda seharusnya tahu cara mendekatinya sekarang. Lagipula, hobinya cukup jelas.",
  ui_story_5081_50810401_58_dialog_content = "Maksudmu video game...",
  ui_story_5081_50810401_59_dialog_content = "Dan bahkan jika itu bukan untuk mendekatinya lagi, kamu baru saja menyebut nama pemain Gronru, bukan?",
  ui_story_5081_50810401_60_dialog_content = "Mengapa kamu tidak bermain beberapa game dan melihat apakah namanya muncul di papan peringkat?",
  ui_story_5081_50810401_61_dialog_content = "Itu seharusnya bisa memberitahu kamu apakah dia baru saja berada di sini atau tidak.",
  ui_story_5081_50810401_62_dialog_content = "Oke! Itu ide yang bagus, Odi!",
  ui_story_5081_50810401_63_dialog_content = "Lagipula, karena kamu baru saja menyelesaikan Tempest Gorge, aku ingin melihat apakah keterampilanmu adalah yang sebenarnya.",
  ui_story_5081_50810401_64_dialog_content = "Aku akan menanggung token, jadi ayo main beberapa pertandingan bersamaku!",
  ui_story_5081_50810401_65_dialog_content = "Tentu, aku akan segera ke sana.",
  ui_story_5081_50810401_66_dialog_content = "Apa itu? Odi yang bayar hari ini? Yah, hitung saya masuk!",
  ui_story_5081_50810401_67_dialog_content = "Aku juga tidak boleh melewatkan ini...",
  ui_story_5081_50810401_68_dialog_content = "Hitung kami juga! Cuit!",
  ui_story_5081_50810401_69_dialog_content = "Teman-teman...",
  ui_story_5081_50810401_70_dialog_content = "Ayo semua orang, mari kita cari tanda-tanda Gronru di skor tertinggi!",
  ui_story_5081_50810402_1_dialog_content = "<color=#e8d9bb>GAME OVER!</color>",
  ui_story_5081_50810402_2_dialog_content = "Kami kalah lagi? Urgh, bodo amat! Masukkan lebih banyak token!",
  ui_story_5081_50810402_3_dialog_content = "Sebenarnya, kita semua kehabisan token...",
  ui_story_5081_50810402_4_dialog_content = "Apa? Jomu, pergi dapatkan kami lebih banyak lagi!",
  ui_story_5081_50810402_5_dialog_content = "Eh? Aku? Kau pasti bercanda... Sork, kenapa tidak kau beli beberapa lagi?",
  ui_story_5081_50810402_6_dialog_content = "Aku? Tapi aku adalah karyawan di sini!",
  ui_story_5081_50810402_7_dialog_content = "Akan sedikit canggung, bukan? Lagipula, tadi kamu bermain seperti sampah, Jomu! Setidaknya buatlah dirimu berguna dengan cara apapun!",
  ui_story_5081_50810402_8_dialog_content = "Jomu bermain seperti sampah, kicauan!",
  ui_story_5081_50810402_9_dialog_content = "A-Aku memang tidak pandai dalam jenis permainan ini! Kamu tidak menyalahkanku, 'kan? Bos?",
  ui_story_5081_50810402_10_dialog_content = "Nah, terlebih karena aku juga tidak terlalu pandai. Odi harus membantuku sepanjang waktu.",
  ui_story_5081_50810402_11_dialog_content = "Masalah sebenarnya adalah bahkan dengan keterampilan kita yang digabungkan, saya tidak berpikir kita akan pernah melihat skor tinggi Gronru...",
  ui_story_5081_50810402_12_dialog_content = "Karena kita bahkan tidak bisa masuk ke papan peringkat!",
  ui_story_5081_50810402_13_dialog_content = "Saya tahu... Kami membutuhkan bantuan Batia untuk melakukan ini, tetapi...",
  ui_story_5081_50810402_14_dialog_content = "...",
  ui_story_5081_50810402_15_dialog_content = "Sepertinya dia tidak ingin ada hubungan apapun denganku sekarang!",
  ui_story_5081_50810402_16_dialog_content = "Heheh, aku tidak begitu yakin, PlayerName.",
  ui_story_5081_50810402_17_dialog_content = "Setelah bekerja di toko selama beberapa hari, saya bisa memberitahu Anda bahwa dia jarang mendekati pelanggan untuk bermain dengan mereka.",
  ui_story_5081_50810402_18_dialog_content = "Dia bersedia bermitra denganmu saat kamu masuk ke tempat ini, yang berarti dia pasti sangat menyukaimu.",
  ui_story_5081_50810402_19_dialog_content = "Cuit! PlayerName memiliki potensi tersembunyi!",
  ui_story_5081_50810402_20_dialog_content = "Tapi dia terlihat sangat kecewa padaku tadi...",
  ui_story_5081_50810402_21_dialog_content = "Saya cukup yakin ini hanya acara pra-penjualan ini yang membebani sarafnya.",
  ui_story_5081_50810402_22_dialog_content = "Dia terus-menerus menilai pemain dan menerima tantangan sepanjang waktu, di atas tugas-tugas biasanya sebagai pemilik arcade...",
  ui_story_5081_50810402_23_dialog_content = "Dia mungkin hanya terlalu lelah untuk memperhatikan kata-katamu sekarang.",
  ui_story_5081_50810402_24_dialog_content = "Ini bukan salahmu, PlayerName!",
  ui_story_5081_50810402_25_dialog_content = "... Menurutmu benar-benar begitu?",
  ui_story_5081_50810402_26_dialog_content = "Kamu bisa sangat lambat kadang-kadang, tahu itu? Belum tahu juga, ya?",
  ui_story_5081_50810402_27_dialog_content = "Tahu apa?",
  ui_story_5081_50810402_28_dialog_content = "\"B\" adalah seorang yang suka menyendiri! Dia memiliki kecemasan sosial!",
  ui_story_5081_50810402_29_dialog_content = "Mengambil alih toko seperti ini sudah cukup sulit bagi seseorang seperti dia.",
  ui_story_5081_50810402_30_dialog_content = "Tapi untuk memberikan tempat bagi para gamer seperti kita untuk berkumpul dan bermain...",
  ui_story_5081_50810402_31_dialog_content = "Dia telah berusaha keras untuk mengatasi kecemasan sosialnya dan menjaga tempat ini tetap berjalan!",
  ui_story_5081_50810402_32_dialog_content = "Mengetahui itu, masuk akal jika dia tidak bisa memberimu jawaban ketika kamu bertanya tentang hal-hal di luar video game, 'kan?",
  ui_story_5081_50810402_33_dialog_content = "Oh, begitu…",
  ui_story_5081_50810402_34_dialog_content = "(Tapi tetap saja, aku benar-benar tidak ingin melepaskan petunjuk bagus seperti ini...)",
  ui_story_5081_50810402_35_dialog_content = "(Aku tidak bisa menghilangkan perasaan bahwa Gronru somehow terhubung dengan tempat ini!)",
  ui_story_5081_50810402_36_dialog_content = "Bos? Bos!",
  ui_story_5081_50810402_37_dialog_content = "Hah? Apa lagi, Jomu? Jangan bilang kamu akan mencoba menipuku lagi...",
  ui_story_5081_50810402_38_dialog_content = "Menipumu? Kata-katamu sangat menyakitkan, Bos! Saya kebetulan lebih peduli tentang kepentinganmu daripada orang lain!",
  ui_story_5081_50810402_39_dialog_content = "Dan saya telah datang dengan ide khusus untukmu.",
  ui_story_5081_50810402_40_dialog_content = "Dan itu akan menjadi?",
  ui_story_5081_50810402_41_dialog_content = "Mengapa kamu tidak mencoba untuk \"menuntaskan B-Stage\"?",
  ui_story_5081_50810402_42_dialog_content = "Apa sekarang?",
  ui_story_5081_50810402_43_dialog_content = "Karena pemilik toko tidak mungkin bisa menangani setiap penantang, dia telah menyiapkan sejumlah tahapan unik pada beberapa mesin game di arcade.",
  ui_story_5081_50810402_44_dialog_content = "Jika kamu bisa menghabisi mereka...",
  ui_story_5081_50810402_45_dialog_content = "Dia bahkan mungkin mengizinkan kamu untuk menyalin versi asli dari permainan ini!",
  ui_story_5081_50810402_46_dialog_content = "Setelah itu, kita bisa membuat banyak salinan dan menjualnya sebagai versi resmi!",
  ui_story_5081_50810402_47_dialog_content = "Kita juga bisa menyembunyikan sebagian konten di balik tembok berbayar dan menghasilkan lebih banyak per salinan, heehee...",
  ui_story_5081_50810402_48_dialog_content = "Kita akan mendapatkan banyak uang dalam sekejap!",
  ui_story_5081_50810402_49_dialog_content = "... Dan kita akan menjadi orang yang paling dibenci dalam komunitas game! Bukankah kamu bilang menyinggung mereka adalah ide yang buruk?",
  ui_story_5081_50810402_50_dialog_content = "Itulah sebabnya kami akan melakukan segalanya atas namamu, bos! Tak ada yang akan mencurigai Caelestite legendaris, setelah semua...",
  ui_story_5081_50810402_51_dialog_content = "Baiklah, sudah cukup dengan rencana gila Anda. Saya sudah bertemu begitu banyak gamer di sini hari ini...",
  ui_story_5081_50810402_52_dialog_content = "Mereka semua sangat baik, dan mereka benar-benar mencintai video game. Saya menolak untuk menipu mereka!",
  ui_story_5081_50810402_53_dialog_content = "Ayo bos! Jangan seperti itu!",
  ui_story_5081_50810402_54_dialog_content = "Hei, apakah itu...",
  ui_story_5081_50810402_55_dialog_content = "Hah? Apa yang terjadi di sana?",
  ui_story_5081_50810402_56_dialog_content = "Sepertinya ada penantang baru bagi saya. Aku akan menyambut mereka!",
  ui_story_5081_50810402_57_dialog_content = "Baiklah, coba untuk tidak menyelinap pada mereka dengan \"sambutan\" seram mu lagi...",
  ui_story_5081_50810402_58_dialog_content = "Mungkin itulah alasan Anda tidak banyak melakukan penjualan!",
  ui_story_5081_50810402_59_dialog_content = "Seorang lagi yang tidak tahu tempatnya, huh? Ayo PlayerName, mari pergi.",
  ui_story_5081_50810402_60_dialog_content = "... Pergi ke mana?",
  ui_story_5081_50810402_61_dialog_content = "Pergi lihat apa yang sedang heboh! Sekarang aku berpikir tentang itu, kamu belum melihat keterampilan Batia dalam aksi, bukan?",
  ui_story_5081_50810402_62_dialog_content = "Memang tidak ada, sih...",
  ui_story_5081_50810402_63_dialog_content = "(Ini mungkin kesempatan bagus untuk lebih mengenal Batia juga.)",
  ui_story_5081_50810402_64_dialog_content = "Akan kucoba semampuku untuk menonton dan belajar!",
  ui_story_5081_50810501_1_dialog_content = "Maaf, tapi apakah pemilik Hidden Fangs ada di sini?",
  ui_story_5081_50810501_2_dialog_content = "Oh? Apakah ini penantang terbaru?",
  ui_story_5081_50810501_3_dialog_content = "Saya pernah melihatnya sebelumnya! Dia adalah penembak bayaran dari Umbraton dan seorang penggemar barang antik yang mengaku sendiri!",
  ui_story_5081_50810501_4_dialog_content = "Apakah ada orang penting yang mempekerjakannya untuk kemari?",
  ui_story_5081_50810501_5_dialog_content = "Sama sekali tidak. Saya datang ke sini atas kemauan saya sendiri.",
  ui_story_5081_50810501_6_dialog_content = "Saya diberitahu bahwa saya bisa membeli salinan edisi terbatas dari sebuah game dengan menantang pemilik arcade, seorang yang bernama \"B.\"",
  ui_story_5081_50810501_7_dialog_content = "Hei, Allura! Senang melihatmu di sini!",
  ui_story_5081_50810501_8_dialog_content = "PlayerName? ... Sungguh kejutan yang tak terduga.",
  ui_story_5081_50810501_9_dialog_content = "Apakah kamu sudah mendapatkan salinan dari permainan itu?",
  ui_story_5081_50810501_10_dialog_content = "Hmm…",
  ui_story_5081_50810501_11_dialog_content = "Sepertinya tidak. Sayang sekali, karena membelinya dari kamu mungkin akan menghemat waktu saya. Meskipun begitu...",
  ui_story_5081_50810501_12_dialog_content = "Saya tertarik untuk melihat seberapa terampil sejatinya orang yang disebut \"B\" ini.",
  ui_story_5081_50810501_13_dialog_content = "Penantang lain... Selamat datang.",
  ui_story_5081_50810501_14_dialog_content = "Oh? Jadi gadis kecil ini adalah \"B\"?",
  ui_story_5081_50810501_15_dialog_content = "Tidak buruk, hanya butuh empat puluh enam detik untuk muncul di hadapanku... Apakah kamu menerima tantanganku?",
  ui_story_5081_50810501_16_dialog_content = "Saya ingin bertanya sesuatu terlebih dahulu... Mengapa Anda ingin membeli game ini?",
  ui_story_5081_50810501_17_dialog_content = "Tentu saja, untuk menambahkannya ke koleksi berhargaku.",
  ui_story_5081_50810501_18_dialog_content = "Sebuah game fantasi yang sepenuhnya dipulihkan adalah fusi sempurna antara teknologi dan hiburan, serta merupakan barang antik yang langka dan berharga.",
  ui_story_5081_50810501_19_dialog_content = "Data yang disimpan dalam kartridnya sama berharganya dengan kata-kata yang tertulis dalam kitab-kitab kuno yang telah saya kumpulkan.",
  ui_story_5081_50810501_20_dialog_content = "Jika saya gagal mendapatkan game fantasi ini, nilai seluruh koleksi saya akan turun sebesar satu koma lima persen.",
  ui_story_5081_50810501_21_dialog_content = "Seorang pengumpul data, huh...",
  ui_story_5081_50810501_22_dialog_content = "Baik. Aku terima tantanganmu.",
  ui_story_5081_50810501_23_dialog_content = "Apa? Betulkah?",
  ui_story_5081_50810501_24_dialog_content = "Tapi sepertinya Allura juga tidak datang untuk bermain video game...",
  ui_story_5081_50810501_25_dialog_content = "Mengumpulkan data juga merupakan bagian yang sangat penting dari menjadi seorang gamer, PlayerName.",
  ui_story_5081_50810501_26_dialog_content = "Selain desain dan karya seni kartrid, data video game kuno yang tersimpan di dalamnya juga sangat berharga.",
  ui_story_5081_50810501_27_dialog_content = "Tindakan mengumpulkan itu sendiri juga merupakan aspek penting dari bermain game...",
  ui_story_5081_50810501_28_dialog_content = "Arcade ini bukan hanya rumah bagi para gamer—ini juga rumah bagi para kolektor yang antusias!",
  ui_story_5081_50810501_29_dialog_content = "Kamu bisa memilih game mana pun yang kamu suka, asalkan bisa dimainkan di sini.",
  ui_story_5081_50810501_30_dialog_content = "Itulah jenis kepercayaan diri yang saya harapkan dari seorang gamer legendaris.",
  ui_story_5081_50810501_31_dialog_content = "Ini adalah pilihan saya, Kaisar Cahaya, Versi 98.",
  ui_story_5081_50810501_32_dialog_content = "... Betapa tak terduga.",
  ui_story_5081_50810501_33_dialog_content = "Mungkin salah jika saya berasumsi, tapi melihat penampilanmu... Saya yakin kamu akan lebih memilih game tembak-menembak sebelum yang lain.",
  ui_story_5081_50810501_34_dialog_content = "Kamu tidak salah beranggapan, tapi saya datang dengan persiapan untuk memainkan game ini, dan saya tidak berniat mengubah keputusan saya.",
  ui_story_5081_50810501_35_dialog_content = "Yang saya kagumi tentang game ini adalah bahwa itu klasik dan mudah diakses.",
  ui_story_5081_50810501_36_dialog_content = "... Apa sih yang mereka bicarakan?",
  ui_story_5081_50810501_37_dialog_content = "Penantang ingin bermain game pertarungan klasik, tetapi \"B\" berpikir dia seharusnya memilih game tembak-tembakan sebagai gantinya.",
  ui_story_5081_50810501_38_dialog_content = "Jadi apa artinya \"Versi 98\"? Jangan bilang padaku... Apakah itu bisa berarti Tahun 1998 dari Kalender Pagi?",
  ui_story_5081_50810501_39_dialog_content = "Tepat sekali. 1998 adalah tahun yang baik untuk hiburan di Umbraton, dan banyak game fantastis yang dirilis selama waktu itu...",
  ui_story_5081_50810501_40_dialog_content = "Ah! Mereka akan segera memulai!",
  ui_story_5081_50810501_41_dialog_content = "Tampaknya Anda tidak perlu pemanasan atau bahkan memeriksa daftar gerakan Anda...",
  ui_story_5081_50810501_42_dialog_content = "Kalau begitu... mari kita mulai.",
  ui_story_5081_50810501_43_dialog_content = "Wow! Penantang pertama hari ini telah mengambil tempatnya—",
  ui_story_5081_50810501_44_dialog_content = "Dan \"B,\" juara yang tak terbantahkan, telah masuk ke akunnya sendiri!",
  ui_story_5081_50810501_45_dialog_content = "Ada dia! Nama pemain legendarisnya!",
  ui_story_5081_50810501_46_dialog_content = "Itu dia, tidak ada keraguan tentang itu! Akhirnya kita bisa melihat dia beraksi!",
  ui_story_5081_50810501_47_dialog_content = "L-Live komentasi? Apakah kamu mencoba kembali ke pekerjaan lama atau sesuatu, Odi?",
  ui_story_5081_50810501_48_dialog_content = "Tidak ada pertempuran epik yang lengkap tanpa beberapa makanan dan minuman pilihan! Camilan dan minuman Umbraton dijual di sini!",
  ui_story_5081_50810501_49_dialog_content = "Pria ini, di sisi lain, tidak pernah berhenti bekerja... Tunggu, bukankah camilan ini dari Rediesel Desert?",
  ui_story_5081_50810501_50_dialog_content = "Diam, Bos! Maksudku... Tentu saja, aku membuat beberapa penyesuaian untuk sesuai dengan selera lokal.",
  ui_story_5081_50810501_51_dialog_content = "Pokoknya, kalau kamu terus-terusan buang-buang waktu di sini, kamu akan melewatkan akhir dari putaran pertama!",
  ui_story_5081_50810501_52_dialog_content = "A-Apa?",
  ui_story_5081_50810501_53_dialog_content = "<color=#e8d9bb>K.O.! Sempurna!</color>",
  ui_story_5081_50810501_54_dialog_content = "Luar biasa!",
  ui_story_5081_50810501_55_dialog_content = "\"B\" mengambil inisiatif sejak awal ronde! Dengan lompatan dan larinya, dia melempar lawannya dan tidak memberi kesempatan padanya hingga akhir!",
  ui_story_5081_50810501_56_dialog_content = "Tanpa ruang untuk melawan, penantang tidak punya pilihan selain mengakui kekalahan!",
  ui_story_5081_50810501_57_dialog_content = "Bermain habis-habisan di babak pertama? Saya berencana untuk melakukan serangan balik setelah satu setengah detik...",
  ui_story_5081_50810501_58_dialog_content = "Tetapi dia berhasil meraih kemenangan dalam waktu kurang dari satu detik.",
  ui_story_5081_50810501_59_dialog_content = "Meski begitu, aku rasa aku sedikit lebih mengerti gaya bermainmu sekarang. Mari kita lanjutkan.",
  ui_story_5081_50810501_60_dialog_content = "Huh, kamu benar-benar pikir kamu sudah tahu semuanya?",
  ui_story_5081_50810501_61_dialog_content = "Aku akan memberimu sepuluh kesempatan untuk mengalahkanku. Jika kamu bisa, aku akan membiarkanmu membeli salinan dari game ini.",
  ui_story_5081_50810501_62_dialog_content = "Maka kau sangat meremehkanku. Ayo pergi!",
  ui_story_5081_50810501_63_dialog_content = "(Ketika Batia tenggelam dalam sebuah game, seolah-olah dia menjadi orang yang benar-benar berbeda.)",
  ui_story_5081_50810501_64_dialog_content = "(Yakin, serius, tak terbatas, tetapi yang paling penting... sepertinya dia sedang bersenang-senang.)",
  ui_story_5081_50810501_65_dialog_content = "(Bisakah ini dia yang sebenarnya?)",
  ui_story_5081_50810501_66_dialog_content = "(Aku harus terus mengawasi, baik permainan ini dan pemain legendaris ini...)",
  ui_story_5081_50810502_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810502_2_dialog_content = "Selesai! Setelah sepuluh kali mencoba, penantang tidak mampu meraih satu kemenangan pun!",
  ui_story_5081_50810502_3_dialog_content = "Meskipun begitu, dia tetap menekan dan berhasil mendorong \"B\" ke sudut beberapa kali...",
  ui_story_5081_50810502_4_dialog_content = "Tidak bisa dipungkiri! Penantang hari ini layak mendapatkan pengakuan, jika tidak hanya untuk semangat bertarungnya yang luar biasa!",
  ui_story_5081_50810502_5_dialog_content = "<size=30>Kamu sedikit terlalu bersemangat, Odi...</size>",
  ui_story_5081_50810502_6_dialog_content = "...",
  ui_story_5081_50810502_7_dialog_content = "Tidak bisa dipercaya... Aku merasa aku akan kalah, tapi aku tidak menyangka akan kalah sehebat ini.",
  ui_story_5081_50810502_8_dialog_content = "Seperti yang diharapkan dari legenda \"B.\" Aku mengaku kalah.",
  ui_story_5081_50810502_9_dialog_content = "Anda dipersilakan untuk menantang saya dalam permainan lain, jika Anda mau...",
  ui_story_5081_50810502_10_dialog_content = "Tidak perlu. Saya sepenuhnya sadar akan jarak kemampuan antara kita sekarang. Tidak ada gunanya melanjutkan.",
  ui_story_5081_50810502_11_dialog_content = "Aku mengerti... tapi keterampilanmu masih layak dihargai.",
  ui_story_5081_50810502_12_dialog_content = "Saya bisa katakan kamu banyak berlatih di menit-menit terakhir, tapi kamu melakukan pekerjaan yang baik dalam memanfaatkan kelebihanmu dan menutupi kelemahanmu.",
  ui_story_5081_50810502_13_dialog_content = "Pengetahuan Anda tentang set gerakan karakter Anda, rasio kerusakan, efek skill, dan bahkan frame mereka sangat tinggi.",
  ui_story_5081_50810502_14_dialog_content = "Dengan lebih banyak waktu dan latihan, mungkin...",
  ui_story_5081_50810502_15_dialog_content = "Kamu bisa mengalahkanku dalam satu pertandingan... asalkan aku tidak menggunakan karakter terbaikku, tentu saja.",
  ui_story_5081_50810502_16_dialog_content = "\"B\" benar-benar mengakui tantangannya?",
  ui_story_5081_50810502_17_dialog_content = "Meskipun dia akan membatasi dirinya sendiri, saya tidak bisa percaya \"B\" mengakui bahwa ada orang yang bisa benar-benar mengalahkannya!",
  ui_story_5081_50810502_18_dialog_content = "Oh? Saya tidak tahu jika saya memiliki potensi seperti itu... tetapi analisis Anda sepenuhnya benar.",
  ui_story_5081_50810502_19_dialog_content = "Untuk menambahkan permainan fantasi itu ke koleksi saya, saya melakukan beberapa latihan menit terakhir pada permainan klasik ini.",
  ui_story_5081_50810502_20_dialog_content = "Alasan saya tidak memilih game lain adalah karena saya tidak seberpengalaman itu. Namun...",
  ui_story_5081_50810502_21_dialog_content = "Uh... A-Apakah kamu masih ingin menantangku dalam sesuatu?",
  ui_story_5081_50810502_22_dialog_content = "Tidak. Ini kartu bisnis saya.",
  ui_story_5081_50810502_23_dialog_content = "Aku, anu, tidak tahu harus bagaimana dengan ini.",
  ui_story_5081_50810502_24_dialog_content = "Hanya peganglah itu, jika kamu mau.",
  ui_story_5081_50810502_25_dialog_content = "Lagi pula, aku pasti ingin merasakan <color=#FFB400>kegembiraan bermain game</color> sekarang.",
  ui_story_5081_50810502_26_dialog_content = "Terutama ketika bermain game yang sangat detail seperti ini... Ah, aku tidak boleh kalah seburuk hari ini lagi!",
  ui_story_5081_50810502_27_dialog_content = "Apakah kamu... senang bermain tadi?",
  ui_story_5081_50810502_28_dialog_content = "Ya, saya lakukan. Awalnya, saya hanya ingin menambahkan beberapa permainan ke koleksi barang antik saya.",
  ui_story_5081_50810502_29_dialog_content = "Tapi sekarang, saya akhirnya menyadari betapa lebih menyenangkan bermain mereka... dan permainan ini jauh lebih kompleks dari yang saya bayangkan!",
  ui_story_5081_50810502_30_dialog_content = "Jika ada lebih banyak game seperti ini di luar sana, saya sangat menghargai jika kamu memperkenalkannya kepada saya!",
  ui_story_5081_50810502_31_dialog_content = "Mengerti... Sebenarnya, aku rasa kita mungkin punya beberapa kartrid ekstra yang tersimpan... Kamu boleh mencobanya juga...",
  ui_story_5081_50810502_32_dialog_content = "Dan... jika aku menemukan permainan yang mirip, aku akan memberitahumu segera.",
  ui_story_5081_50810502_33_dialog_content = "J-Juga, kamu lulus. Kamu sekarang layak untuk membeli salinan dari permainan fantasi ini!",
  ui_story_5081_50810502_34_dialog_content = "Hah? Tapi kukira aku tersesat?",
  ui_story_5081_50810502_35_dialog_content = "Menang atau kalah tidak menentukan layaknya seorang pemain... Yang paling penting adalah mereka menikmati bermain game!",
  ui_story_5081_50810502_36_dialog_content = "Oh, begitu…",
  ui_story_5081_50810502_37_dialog_content = "Sepertinya saatnya kembali bekerja. Saya bisa membantu membayar untuk itu di sini, nona.",
  ui_story_5081_50810502_38_dialog_content = "Selamat! Akhirnya, ada yang berhak membeli permainan ini!",
  ui_story_5081_50810502_39_dialog_content = "Saya sangat cemburu! Tapi setelah melihat mereka berhadapan, saya tahu saya tidak punya kesempatan...",
  ui_story_5081_50810502_40_dialog_content = "Kalian semua terlalu baik.",
  ui_story_5081_50810502_41_dialog_content = "Arcade ini benar-benar tempat yang luar biasa.",
  ui_story_5081_50810502_42_dialog_content = "Baiklah! Di tengah gemuruh tepuk tangan, pendatang baru muncul dari Hidden Fangs, tersenyum dan meraih kemenangan!",
  ui_story_5081_50810502_43_dialog_content = "Dan meskipun masih banyak penantang di arcade, mereka tampak tidak begitu yakin pada diri mereka sendiri sekarang!",
  ui_story_5081_50810502_44_dialog_content = "Kamu tidak perlu menambahkan bagian terakhir itu, Odi! Lagipula... A-Aku mulai berpikir aku tidak cukup terampil untuk—",
  ui_story_5081_50810502_45_dialog_content = "Belumkah kamu menyadarinya, PlayerName? Bagaimana kamu masih bisa berpikir bahwa tantangan ini hanya berdasarkan keterampilan saja?",
  ui_story_5081_50810502_46_dialog_content = "Pikirkan, kau bodoh! Apa alasan \"B\" memutuskan untuk bekerja sama denganmu lebih awal?",
  ui_story_5081_50810502_47_dialog_content = "Alasannya, huh...",
  ui_story_5081_50810502_48_dialog_content = "Apakah ini cara saya harus mengambil tikungan? Saya benar-benar mengerti sekarang!",
  ui_story_5081_50810502_49_dialog_content = "Saya mengumpulkan Lumina setiap kali saya melayang di sekitar sudut, jadi apakah saya harus menembakkannya ke Eclipsites? Tebak saya harus mencobanya!",
  ui_story_5081_50810502_50_dialog_content = "Saat itu... Aku benar-benar tersesat dalam permainan.",
  ui_story_5081_50810502_51_dialog_content = "Mungkin dia berpikir saya benar-benar menyukai permainan ketika melihat saya seperti itu, jadi dia memutuskan untuk bergabung dengan saya.",
  ui_story_5081_50810502_52_dialog_content = "Tidak perlu \"mungkin\"! Apakah kamu benar-benar berpikir kamu menarik perhatiannya hanya dengan kemampuanmu saja?",
  ui_story_5081_50810502_53_dialog_content = "Hei, tidak perlu begitu blak-blakan!",
  ui_story_5081_50810502_54_dialog_content = "Selama kamu bersedia untuk menghargai, memahami, dan menikmati game di sini, kamu tidak akan kesulitan memahaminya.",
  ui_story_5081_50810502_55_dialog_content = "Kamu tidak akan menemukan orang yang lebih ramah, lebih antusias daripada \"B\" jika kamu melakukannya!",
  ui_story_5081_50810502_56_dialog_content = "Ada satu hal lagi... Dia mengkonsumsi banyak mana setiap kali dia bersemangat, dan juga memiliki waktu pendinginan yang cukup lama!",
  ui_story_5081_50810502_57_dialog_content = "Aku mengerti. Mencari Gronru mungkin juga situasi yang serupa.",
  ui_story_5081_50810502_58_dialog_content = "Aku hanya perlu mencoba memahami mereka... dan merasakan video game yang sangat mereka cintai untuk diriku sendiri.",
  ui_story_5081_50810502_59_dialog_content = "Setelah saya melakukannya, akhirnya saya akan dapat melihat segalanya dari perspektif mereka dan mendekati keduanya.",
  ui_story_5081_50810502_60_dialog_content = "Mungkin Gronru hanya menunggu seseorang yang juga mengerti dia.",
  ui_story_5081_50810502_61_dialog_content = "Kami telah menunggu Anda mengatakan itu, Bos! Dan saya sudah mengambil inisiatif mendaftarkan kita berdua!",
  ui_story_5081_50810502_62_dialog_content = "Sekarang mari kita tantang \"B\" dan buat keberuntungan kita!",
  ui_story_5081_50810502_63_dialog_content = "Maaf, tapi apakah ini tempat saya bisa menantang orang yang dikenal sebagai \"B\"?",
  ui_story_5081_50810502_64_dialog_content = "Ah! Penantang lain! Mari kita lihat!",
  ui_story_5081_50810502_65_dialog_content = "Tunggu aku, bos!",
  ui_story_5081_50810601_1_dialog_content = "Apa ini, penantang yang tak terduga!",
  ui_story_5081_50810601_2_dialog_content = "Berdasarkan pakaian yang dia kenakan, saya rasa dia berasal dari Lumopolis!",
  ui_story_5081_50810601_3_dialog_content = "Apakah ada yang akan menjawab saya? Saya di sini untuk menantang \"B\"!",
  ui_story_5081_50810601_4_dialog_content = "Siapa yang bertanggung jawab di sini?",
  ui_story_5081_50810601_5_dialog_content = "Beretta?",
  ui_story_5081_50810601_6_dialog_content = "PlayerName? Apakah kamu bekerja di sini secara kebetulan?",
  ui_story_5081_50810601_7_dialog_content = "Jika begitu, bisakah kamu membantu saya mendaftar untuk tantangan ini?",
  ui_story_5081_50810601_8_dialog_content = "Tidak, saya pikir kamu mencari pemilik toko... Oh, dia datang!",
  ui_story_5081_50810601_9_dialog_content = "...",
  ui_story_5081_50810601_10_dialog_content = "Bagus sekali!",
  ui_story_5081_50810601_11_dialog_content = "Maafkan saya karena tidak menyadari kehadiranmu sebelumnya. Nama saya Beretta, dan saya adalah medik lapangan dari Lumopolis.",
  ui_story_5081_50810601_12_dialog_content = "Bagaimana saya bisa memanggil Anda? Dan bagaimana saya bisa mendaftar untuk menantang legendaris \"B\"?",
  ui_story_5081_50810601_13_dialog_content = "Kamu bisa panggil aku Batia. Permainan apa yang ingin kamu mainkan untuk tantangan ini?",
  ui_story_5081_50810601_14_dialog_content = "Setiap game baik saja, tetapi saya lebih suka bermain game terberat dan paling melelahkan milikmu!",
  ui_story_5081_50810601_15_dialog_content = "Sejujurnya, ini adalah pertama kalinya saya mengunjungi tempat seperti ini. Dengan begitu banyak penantang dan kesulitan yang terlihat...",
  ui_story_5081_50810601_16_dialog_content = "Meskipun sebelumnya saya tidak pernah bermain game dengan serius, ini adalah tempat yang sempurna untuk menguji tekad saya!",
  ui_story_5081_50810601_17_dialog_content = "... Ini hanya arcade, bukan lapangan latihan... Kamu hanya akan menemukan gamer berkumpul di sini.",
  ui_story_5081_50810601_18_dialog_content = "Jika kamu ingin menguji tekadmu... S-saya sarankan pergi ke tempat lain.",
  ui_story_5081_50810601_19_dialog_content = "Game adalah cara yang bagus untuk menguji kemauan seseorang! Saya dengar banyak prajurit terbaik Illumina berlatih dengan cara ini!",
  ui_story_5081_50810601_20_dialog_content = "Sayangnya, Lumopolis tidak memiliki metode pelatihan seperti ini. Ketika aku mendengar bahwa Umbraton memiliki tempat seperti ini, aku harus datang dan melihatnya sendiri!",
  ui_story_5081_50810601_21_dialog_content = "Sekarang, bolehkah saya menantang si \"B\" ini untuk pertandingan latihan?",
  ui_story_5081_50810601_22_dialog_content = "A-Aku \"B.\"",
  ui_story_5081_50810601_23_dialog_content = "Tapi aku menolak tantangan dari seseorang yang tidak tahu aturan permainan...",
  ui_story_5081_50810601_24_dialog_content = "Jika kamu benar-benar ingin menantangku... t-tolong pilih permainan dan pelajari cara memainkannya terlebih dahulu.",
  ui_story_5081_50810601_25_dialog_content = "Baiklah, akan kulakukan itu! Terima kasih!",
  ui_story_5081_50810601_26_dialog_content = "Sebenarnya dia sedang belajar cara bermain!",
  ui_story_5081_50810601_27_dialog_content = "... Apakah ini benar-benar baik-baik saja? Aku pikir dia bahkan lebih fokus pada tujuannya daripada aku!",
  ui_story_5081_50810601_28_dialog_content = "Saya pikir \"B\" hanya tidak tahu bagaimana cara menghadapi seseorang seperti dia.",
  ui_story_5081_50810601_29_dialog_content = "Mengalahkan lawan-lawannya secepat mungkin adalah cara dia biasanya melakukan hal-hal.",
  ui_story_5081_50810601_30_dialog_content = "Sesuatu memberitahu saya bahwa itu tidak akan berfungsi dengan baik pada seseorang seperti Beretta...",
  ui_story_5081_50810601_31_dialog_content = "Ahh! Bagaimana ini bisa terjadi?",
  ui_story_5081_50810601_32_dialog_content = "Aku di sini lebih dulu, bukan?",
  ui_story_5081_50810601_33_dialog_content = "Maniak latihan itu tidak tahu apa-apa tentang video game, bukan? Ini akan memakan waktu yang sangat lama!",
  ui_story_5081_50810601_34_dialog_content = "Mungkin kita harus mencari metode yang lebih meragukan, Bos...",
  ui_story_5081_50810601_35_dialog_content = "Jangan khawatir, aku sangat cepat belajar. Mereka juga memiliki game bertarung, yang seharusnya cocok untukku!",
  ui_story_5081_50810601_36_dialog_content = "Sepertinya Beretta akan memilih game yang sama dengan Allura. Saya rasa itu yang dimaksud dengan \"klasik dan mudah diakses,\" ya?",
  ui_story_5081_50810601_37_dialog_content = "Pengendali semua sudah rusak. Permainan ini pasti sangat populer.",
  ui_story_5081_50810601_38_dialog_content = "Permisi... tapi, apa ada yang benar-benar mendengar?",
  ui_story_5081_50810601_39_dialog_content = "Kalian berdua... bisa menantangku.",
  ui_story_5081_50810601_40_dialog_content = "Hmm? Apa maksudmu dengan itu?",
  ui_story_5081_50810601_41_dialog_content = "Kalian berdua bisa bekerja sama melawanku. Aku masih akan menang... jadi tidak masalah.",
  ui_story_5081_50810601_42_dialog_content = "Aku mengagumi kepercayaan dirimu, tetapi aku harus menolak.",
  ui_story_5081_50810601_43_dialog_content = "Kalah dalam pertandingan dua lawan satu pasti memalukan, tapi menang melawanmu tidak lebih baik.",
  ui_story_5081_50810601_44_dialog_content = "Meskipun pemuda ini tampaknya sangat lemah, angka masih menguntungkan kita.",
  ui_story_5081_50810601_45_dialog_content = "Saya menolak untuk menerima ini—kecuali kamu bersekutu dengan seseorang sendiri!",
  ui_story_5081_50810601_46_dialog_content = "Kamu maniak latihan... Kita akan segera melihat siapa yang sebenarnya lemah!",
  ui_story_5081_50810601_47_dialog_content = "Seorang rekan? ... Aku tidak membutuhkannya. Tidak ada alasan bagi saya untuk merepotkan siapa pun, sejak...",
  ui_story_5081_50810601_48_dialog_content = "Jika kamu tidak keberatan—",
  ui_story_5081_50810601_49_dialog_content = "Apakah tidak masalah jika saya bekerja sama dengan Anda?",
  ui_story_5081_50810601_50_dialog_content = "Hah?",
  ui_story_5081_50810601_51_dialog_content = "Haha, saya tidak yakin apakah saya sedang membalas budi atau ini sesuatu yang lain...",
  ui_story_5081_50810601_52_dialog_content = "Tapi tadi kita membentuk tim yang cukup bagus, menurutmu bagaimana?",
  ui_story_5081_50810601_53_dialog_content = "Jika bukan karena kamu, saya tidak akan pernah bisa menyelesaikan stage yang begitu sulit. Jadi sekarang giliran saya untuk menjadi Player 2-mu!",
  ui_story_5081_50810601_54_dialog_content = "Kamu...",
  ui_story_5081_50810601_55_dialog_content = "Melihat semua penantang serius ini juga membuatku bersemangat.",
  ui_story_5081_50810601_56_dialog_content = "Saya yakin saya bisa menikmati permainan ini sepenuhnya jika kamu membiarkan saya bermain di timmu!",
  ui_story_5081_50810601_57_dialog_content = "J-Jika itu benar-benar yang kamu rasakan...",
  ui_story_5081_50810601_58_dialog_content = "Lalu, ayo bermain bersama!",
  ui_story_5081_50810601_59_dialog_content = "...",
  ui_story_5081_50810601_60_dialog_content = "Terima kasih untuk itu, bos! Anda tahu apa yang harus dilakukan sekarang, bukan?",
  ui_story_5081_50810601_61_dialog_content = "A-Apa yang kamu bicarakan?",
  ui_story_5081_50810601_62_dialog_content = "Dengan sabotase kalian, pertandingan dua lawan dua ini akan berubah menjadi pertarungan tiga lawan satu!",
  ui_story_5081_50810601_63_dialog_content = "Bahkan dengan orang gila latihan ini di tim kita, kita masih punya peluang untuk mengalahkannya! Hahahaha!",
  ui_story_5081_50810601_64_dialog_content = "Aku akan pastikan memberimu bagianmu setelahnya!",
  ui_story_5081_50810601_65_dialog_content = "... Kamu pikir aku akan <color=#FFB400>menggagalkan</color> pertandingan?",
  ui_story_5081_50810601_66_dialog_content = "Itu dia! Saatnya kamu merasakan kekuatan dari Caelestite Terakhir!",
  ui_story_5081_50810602_1_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_2_dialog_content = "Bos, tidak! Ini bukan yang kita sepakati!",
  ui_story_5081_50810602_3_dialog_content = "Berhenti main-main, lemah! Kamu akan membuat kami kalah dalam pertandingan!",
  ui_story_5081_50810602_4_dialog_content = "Betul! Dan untuk catatan, saya tidak setuju dengan apa pun! Sekarang hadapilah, saya siap untuk terus mendukungmu, Batia!",
  ui_story_5081_50810602_5_dialog_content = "Kalau begitu, aku akan membiarkan kamu menangani pertarungan ini.",
  ui_story_5081_50810602_6_dialog_content = "Hah?",
  ui_story_5081_50810602_7_dialog_content = "Fokus, permainannya sudah dimulai!",
  ui_story_5081_50810602_8_dialog_content = "Oke! Tunggu, Jomu, aku belum siap! Kamu tidak punya sopan santun?",
  ui_story_5081_50810602_9_dialog_content = "Maaf, Bos, tapi saya hanya bermain permainan! Begitu pertandingan dimulai, apapun bisa terjadi!",
  ui_story_5081_50810602_10_dialog_content = "Konsentrasi adalah bagian penting dari latihan, PlayerName! Aku juga akan berusaha sekuat tenaga!",
  ui_story_5081_50810602_11_dialog_content = "I-Itu sedikit—",
  ui_story_5081_50810602_12_dialog_content = "Tenanglah, aku masih di sini.",
  ui_story_5081_50810602_13_dialog_content = "Mainkan sebaik mungkin. Kami tidak akan kalah.",
  ui_story_5081_50810602_14_dialog_content = "Kamu benar. Bagaimanapun, aku tidak bisa kalah dengan \"B\" legendaris di sisiku!",
  ui_story_5081_50810602_15_dialog_content = "Jomu tidak begitu baik, dan Beretta benar-benar baru dalam permainan ini. Saya hanya perlu menangani mereka dengan tangan yang tenang dan fokus...",
  ui_story_5081_50810602_16_dialog_content = "Oh? Sepertinya tantangan ganda ini telah memasuki fase yang benar-benar baru!",
  ui_story_5081_50810602_17_dialog_content = "\"B\" telah bertukar peran dengan The Last Caelestite dan sekarang bermain sebagai pendukung! Dia pasti memiliki banyak kepercayaan padanya!",
  ui_story_5081_50810602_18_dialog_content = "Dan di sisi ini, Training Freak dan Weakling sedang berjuang untuk mendapatkan kerja sama tim mereka dengan baik!",
  ui_story_5081_50810602_19_dialog_content = "Hai, Odi! Kita satu tim, ingat? Itu nama jenis apa?",
  ui_story_5081_50810602_20_dialog_content = "Sementara Training Freak menyerang lawannya secara langsung, Weakling terus melakukan provokasi yang menjengkelkan! Apakah ini bisa jadi tipuan semacam itu?",
  ui_story_5081_50810602_21_dialog_content = "Sekaranglah kesempatan kita!",
  ui_story_5081_50810602_22_dialog_content = "<color=#e8d9bb>Apa, apa—plak!</color>",
  ui_story_5081_50810602_23_dialog_content = "Aduh! The Last Caelestite sedang dipukuli tanpa ampun! Bar HP itu tidak terlihat terlalu baik, orang-orang! Berapa lama lagi dia bisa bertahan?",
  ui_story_5081_50810602_24_dialog_content = "Urgh... M-Mungkin kita harus bertukar kembali?",
  ui_story_5081_50810602_25_dialog_content = "Jangan panik. Saya sudah sepenuhnya mengendalikan teman satu timnya.",
  ui_story_5081_50810602_26_dialog_content = "Untuk dia, cukup awasi gerak-geriknya... baik di dalam maupun di luar game.",
  ui_story_5081_50810602_27_dialog_content = "Cara untuk menang seharusnya sangat jelas.",
  ui_story_5081_50810602_28_dialog_content = "B-Benarkah? Mari kita lihat...",
  ui_story_5081_50810602_29_dialog_content = "Ambil itu! Dan itu! Aku tak akan berhenti apapun yang terjadi!",
  ui_story_5081_50810602_30_dialog_content = "<color=#e8d9bb>Tik, tik, tik, tik, dor—</color>",
  ui_story_5081_50810602_31_dialog_content = "Itu kesempatanku!",
  ui_story_5081_50810602_32_dialog_content = "Di bawah serangan brutal Training Freak, The Last Caelestite akhirnya menunjukkan taringnya dan membalas! Tapi, bisakah dia menjaga tekanannya?",
  ui_story_5081_50810602_33_dialog_content = "Dia melakukannya! Sepertinya Freak Latihan telah membuat kesalahan...",
  ui_story_5081_50810602_34_dialog_content = "Serangan itu terus berdatangan! Apakah ini bisa jadi akhirnya?",
  ui_story_5081_50810602_35_dialog_content = "<color=#e8d9bb>K.O.!</color>",
  ui_story_5081_50810602_36_dialog_content = "Dia berhasil! Caelestite Terakhir menang!",
  ui_story_5081_50810602_37_dialog_content = "Menonton dari pinggir lapangan dan mengganggu, \"B\" memimpin rekan setimnya menuju kemenangan hanya dengan bimbingan saja!",
  ui_story_5081_50810602_38_dialog_content = "...",
  ui_story_5081_50810602_39_dialog_content = "B-Terbaik dua dari tiga?",
  ui_story_5081_50810602_40_dialog_content = "Aku kalah kali ini... Tidak ada lagi yang bisa dikatakan.",
  ui_story_5081_50810602_41_dialog_content = "Meskipun keterampilan saya dalam bertarung, saya benar-benar dan sepenuhnya dikalahkan. Tampaknya jenis pelatihan ini harus ditangani dengan lebih serius.",
  ui_story_5081_50810602_42_dialog_content = "Maafkan saya. Saya sombong karena menantang Anda.",
  ui_story_5081_50810602_43_dialog_content = "Ada perbedaan besar antara permainan bertarung dan pertempuran sesungguhnya. Teknik yang terlibat juga sepenuhnya berbeda.",
  ui_story_5081_50810602_44_dialog_content = "Menggabungkan kedua hal itu... tidak pernah berakhir dengan baik.",
  ui_story_5081_50810602_45_dialog_content = "Apakah begitu? Menarik. May Bisakah kamu menjelaskan konsep ini seperti seorang guru kepada murid-muridnya?",
  ui_story_5081_50810602_46_dialog_content = "G-Guru? T-Tidak, aku tidak bisa... Aku tidak pantas menjadi guru siapa pun.",
  ui_story_5081_50810602_47_dialog_content = "Ah, sayang sekali...",
  ui_story_5081_50810602_48_dialog_content = "Tidak apa-apa, aku bisa menjelaskannya kepada kamu di tempat Batia.",
  ui_story_5081_50810602_49_dialog_content = "...Hah?",
  ui_story_5081_50810602_50_dialog_content = "PlayerName? Tentu saja! Keterampilan Anda barusan juga cukup mengejutkan.",
  ui_story_5081_50810602_51_dialog_content = "Hanya berkat saran Batia, aku bisa melihat gerakanmu, dan aku pikir...",
  ui_story_5081_50810602_52_dialog_content = "Kamu memperlakukan permainan ini seperti pertarungan sungguhan, bukan?",
  ui_story_5081_50810602_53_dialog_content = "Tentu saja! Entah itu kecepatan reaksi, pelacakan gerakan, atau posisi yang tepat...",
  ui_story_5081_50810602_54_dialog_content = "Semua aspek ini sama pentingnya dalam video game seperti dalam pertempuran langsung!",
  ui_story_5081_50810602_55_dialog_content = "Kamu benar, tapi mereka tidak sepenuhnya sama.",
  ui_story_5081_50810602_56_dialog_content = "Kok bisa?",
  ui_story_5081_50810602_57_dialog_content = "Dalam game pertarungan, input yang sangat kecil dan presisi dapat menghasilkan hasil yang sangat kuat.",
  ui_story_5081_50810602_58_dialog_content = "Tapi tadi kamu menekan tombol dan menarik tuas kontrol dengan keras, seolah-olah kamu mencoba menyalurkan kekuatan sebenarnya ke dalam game.",
  ui_story_5081_50810602_59_dialog_content = "Ada berbagai macam karakter dalam video game, dan mereka tidak selalu dapat melakukan aksi yang kamu inginkan. Itulah sebabnya...",
  ui_story_5081_50810602_60_dialog_content = "Bukan hanya kamu membuang-buang kekuatanmu, tetapi kamu juga mempengaruhi inputmu secara negatif, yang memberiku kesempatan yang aku butuhkan untuk melawan.",
  ui_story_5081_50810602_61_dialog_content = "... Jadi hanya dengan memahami konsep sederhana ini saja kamu bisa mengalahkanku?",
  ui_story_5081_50810602_62_dialog_content = "Ya... Tapi lagi-lagi, itu hanya berkat saran Batia.",
  ui_story_5081_50810602_63_dialog_content = "Aku... tidak melakukan apa-apa. Itu hanya akal sehat, hanya itu saja.",
  ui_story_5081_50810602_64_dialog_content = "Aku mengerti.",
  ui_story_5081_50810602_65_dialog_content = "Itulah mengapa prajurit Illumina <color=#FFB400>menyesuaikan diri mereka</color> untuk sesuai dengan <color=#FFB400>daya tembak</color> senjata mereka... Semua ini sekarang menjadi masuk akal!",
  ui_story_5081_50810602_66_dialog_content = "Game bisa digunakan untuk latihan... Atau lebih tepatnya, latihan bisa dilihat sebagai semacam permainan!",
  ui_story_5081_50810602_67_dialog_content = "Pengalaman ini telah menjadi mengejutkan dan pencerahan!",
  ui_story_5081_50810602_68_dialog_content = "Terima kasih, Batia! Apakah tidak masalah jika saya kembali untuk menantang Anda di masa depan?",
  ui_story_5081_50810602_69_dialog_content = "?",
  ui_story_5081_50810602_70_dialog_content = "T-Tergantung... K-Kamu punya...",
  ui_story_5081_50810602_71_dialog_content = "Hmm?",
  ui_story_5081_50810602_72_dialog_content = "Saya pikir dia ingin bertanya apakah kamu senang tadi, dan apakah kamu menikmati bermain game itu.",
  ui_story_5081_50810602_73_dialog_content = "Tentu saja! Itu adalah pengalaman yang sangat mendebarkan! Saya tidak tahu kalau video game bisa seasyik ini!",
  ui_story_5081_50810602_74_dialog_content = "Dan sesuatu memberitahu saya bahwa saya akan mendapatkan lebih banyak pengalaman jika saya terus memainkannya!",
  ui_story_5081_50810602_75_dialog_content = "Dalam usaha ini, saya tidak akan pernah goyah!",
  ui_story_5081_50810602_76_dialog_content = "Lalu... Tolong terima ini.",
  ui_story_5081_50810602_77_dialog_content = "Dia lulus! T-Tidak mungkin! Dia tidak tahu betapa berharganya permainan itu...",
  ui_story_5081_50810602_78_dialog_content = "Apakah kamu merekomendasikan game ini padaku? Baiklah! Saya pasti akan berlatih siang dan malam setelah saya mendapatkan salinan saya!",
  ui_story_5081_50810602_79_dialog_content = "Saya menantikan duel kita selanjutnya!",
  ui_story_5081_50810602_80_dialog_content = "Uh... B-B-Baiklah!",
  ui_story_5081_50810602_81_dialog_content = "Dan begitu aku menguasai rahasia pelatihan video game Illumina...",
  ui_story_5081_50810602_82_dialog_content = "Saya mungkin memiliki kesempatan untuk akhirnya menebus kekalahan saya melawan Yingel!",
  ui_story_5081_50810602_83_dialog_content = "Yingel?",
  ui_story_5081_50810602_84_dialog_content = "Seorang petugas intelijen di Illumina Federation, ya.",
  ui_story_5081_50810602_85_dialog_content = "Setelah kekalahan saya di tangannya selama Latihan Militer Bersama, saya sering berpikir tentang cara terbaik untuk meraih kemenangan atasnya.",
  ui_story_5081_50810602_86_dialog_content = "Bahkan aku bertemu dengannya dalam perjalanan ke sini!",
  ui_story_5081_50810602_87_dialog_content = "Tapi dia begitu sibuk sampai-sampai dia tidak menyadari keberadaanku...",
  ui_story_5081_50810602_88_dialog_content = "dia...",
  ui_story_5081_50810602_89_dialog_content = "!",
  ui_story_5081_50810602_90_dialog_content = "Hah? Bukankah itu Petugas Intelijen Yingel?",
  ui_story_5081_50810602_91_dialog_content = "...",
  ui_story_5081_50810602_92_dialog_content = "Tebak aku bukan satu-satunya yang diabaikan.",
  ui_story_5081_50810602_93_dialog_content = "Ada apa?",
  ui_story_5081_50810602_94_dialog_content = "Oh, tidak apa-apa.",
  ui_story_5081_50810602_95_dialog_content = "(Apa yang dilakukan oleh seorang perwira intelijen tingkat tinggi dari Illumina di Umbraton? Apakah dia juga mencari Gronru?)",
  ui_story_5081_50810602_96_dialog_content = "Nah, jika kamu melihatnya, beri tahu dia tentang tantangan yang akan kuhadapi!",
  ui_story_5081_50810602_97_dialog_content = "A-Akan melakukan.",
  ui_story_5081_50810602_98_dialog_content = "Game fantasi—sumber penghasilan terbesarku! Aku berhasil... Akhirnya aku pantas mendapatkannya! Wow!",
  ui_story_5081_50810602_99_dialog_content = "Kamu masih saja bicara tentang itu, Jomu? ... Hah? Apa yang sedang kamu lakukan di lantai?",
  ui_story_5081_50810602_100_dialog_content = "Aku melakukannya... Aku lulus... Blegh...",
  ui_story_5081_50810602_101_dialog_content = "Sepertinya dia sedikit mabuk gerak karena bermain terlalu lama... Aku tahu dia tidak cocok untuk jenis game ini!",
  ui_story_5081_50810602_102_dialog_content = "Jika saya tahu dia bersedia mengambil risiko nyawanya demi uang, saya tidak akan pernah membawanya bersama.",
  ui_story_5081_50810602_103_dialog_content = "Meskipun dia tidak pernah berhenti berbicara tentang menghasilkan uang, ketika saya melihatnya bermain sebelumnya...",
  ui_story_5081_50810602_104_dialog_content = "Jomu tampak seperti dia sangat bersenang-senang, 'kan?",
  ui_story_5081_50810602_105_dialog_content = "... Aku hampir saja berhasil menipu \"B\" tadi... Sayang sekali...",
  ui_story_5081_50810602_106_dialog_content = "(Bahkan seorang pedagang yang rakus akan uang seperti Jomu bisa terjebak dalam bermain video game. Saya rasa itu adalah daya tarik mereka.)",
  ui_story_5081_50810602_107_dialog_content = "Kepalaku berputar... Air... Aku butuh air...",
  ui_story_5081_50810602_108_dialog_content = "Tunggu sebentar, aku akan pergi mendapatkan minuman untukmu dan Odi. Setelah semua komentar itu, aku yakin dia juga haus.",
  ui_story_5081_50810602_109_dialog_content = "Pikirkan ini sebagai hadiah terima kasih karena telah membawaku ke sini hari ini.",
  ui_story_5081_50810602_110_dialog_content = "Aku akan segera kembali!",
  ui_story_5081_50810701_1_dialog_content = "<color=#e8d9bb>Dung—</color>",
  ui_story_5081_50810701_2_dialog_content = "Apakah ini hanya perasaanku, atau memang mesin-mesin ini terlihat seperti berasal dari Illumina?",
  ui_story_5081_50810701_3_dialog_content = "Apa ya minuman yang Jomu dan Odi mau?",
  ui_story_5081_50810701_4_dialog_content = "Mungkin sesuatu yang \"klasik dan mudah diakses\"?",
  ui_story_5081_50810701_5_dialog_content = "<color=#e8d9bb>Dung—</color>",
  ui_story_5081_50810701_6_dialog_content = "...",
  ui_story_5081_50810701_7_dialog_content = "Aku tahu ada seseorang yang memperhatikanku.",
  ui_story_5081_50810701_8_dialog_content = "Siapa di sana?",
  ui_story_5081_50810701_9_dialog_content = "Ahh! M-maafkan aku!",
  ui_story_5081_50810701_10_dialog_content = "Hah? Rupanya kau, Batia.",
  ui_story_5081_50810701_11_dialog_content = "Maaf telah berteriak tadi, saya pikir ada orang yang mencoba mencuri token saya atau semacamnya.",
  ui_story_5081_50810701_12_dialog_content = "I-Begitukah... U-Um...",
  ui_story_5081_50810701_13_dialog_content = "Wow! Apakah itu... es krim? Tapi kenapa kamu tidak memakannya? Sepertinya itu akan segera meleleh!",
  ui_story_5081_50810701_14_dialog_content = "I-Ini untukmu...",
  ui_story_5081_50810701_15_dialog_content = "Tunggu... Kamu membeli ini hanya untukku?",
  ui_story_5081_50810701_16_dialog_content = "Ya.",
  ui_story_5081_50810701_17_dialog_content = "Maka sebaiknya aku cepat memakannya! Untungnya, ini belum sepenuhnya meleleh...",
  ui_story_5081_50810701_18_dialog_content = "Aku tidak yakin itu masih bisa disebut \"es\" krim lagi sih.",
  ui_story_5081_50810701_19_dialog_content = "Tapi tidak apa-apa! Kita bisa selalu beli lagi! Lagipula, masih bisa dimakan kok. Wah, itu dingin!",
  ui_story_5081_50810701_20_dialog_content = "Betulkah? Saya sangat senang bahwa kamu menyukainya.",
  ui_story_5081_50810701_21_dialog_content = "Juga... Aku ingin berterima kasih.",
  ui_story_5081_50810701_22_dialog_content = "Untuk bekerja sama denganku... d-dan membantuku menangani penantang yang terlalu antusias itu.",
  ui_story_5081_50810701_23_dialog_content = "Seharusnya aku yang berterima kasih padamu! Saya tidak akan pernah memiliki kesempatan tanpa bantuanmu.",
  ui_story_5081_50810701_24_dialog_content = "Dan karena kamu baik hati membawakan aku es krim, bagaimana kalau aku yang traktir minuman? Jus atau kopi?",
  ui_story_5081_50810701_25_dialog_content = "Um... T-Tomat jus, tolong...",
  ui_story_5081_50810701_26_dialog_content = "Tunggu sebentar!",
  ui_story_5081_50810701_27_dialog_content = "<color=#e8d9bb>Dung—</color>",
  ui_story_5081_50810701_28_dialog_content = "Ini dia! Jadi kamu suka minuman seperti ini, ya?",
  ui_story_5081_50810701_29_dialog_content = "Uh-huh... Aku jarang keluar siang hari, jadi aku mengandalkan hal-hal seperti ini untuk nutrisi... Cukup efektif juga.",
  ui_story_5081_50810701_30_dialog_content = "Uh, maaf bertanya... tapi apakah ini ada hubungannya dengan menjadi setengah kelelawar?",
  ui_story_5081_50810701_31_dialog_content = "Memang... itulah mengapa keluar menjadi masalah besar bagi saya.",
  ui_story_5081_50810701_32_dialog_content = "Berinteraksi dengan orang lain... juga tidak mudah bagiku.",
  ui_story_5081_50810701_33_dialog_content = "Aku adalah Aurorian seperti orang lain... tapi tidak sepenuhnya.",
  ui_story_5081_50810701_34_dialog_content = "Ada banyak hal yang bisa dilakukan orang lain... yang tidak pernah bisa saya lakukan.",
  ui_story_5081_50810701_35_dialog_content = "Apakah itu sebabnya kamu tetap bermain game sampai kamu menjadi yang terbaik di dalamnya?",
  ui_story_5081_50810701_36_dialog_content = "I-Itu memalukan, bukan?",
  ui_story_5081_50810701_37_dialog_content = "Tentu saja tidak! Bahkan, itu adalah pencapaian yang tidak bisa dipercaya!",
  ui_story_5081_50810701_38_dialog_content = "Menjadi yang terbaik dalam satu game adalah prestasi yang mengesankan bagi setiap gamer.",
  ui_story_5081_50810701_39_dialog_content = "Namun, nama Anda berada di puncak setiap papan peringkat di sini—atau bahkan di seluruh Astra!",
  ui_story_5081_50810701_40_dialog_content = "\"B\" sudah menjadi pahlawan dan simbol dengan haknya sendiri—mungkin bahkan legenda! Ketika saya datang ke toko ini...",
  ui_story_5081_50810701_41_dialog_content = "Saya melakukannya dengan niat untuk memperluas wawasan saya juga!",
  ui_story_5081_50810701_42_dialog_content = "...",
  ui_story_5081_50810701_43_dialog_content = "T-Tapi kamu tidak datang ke sini dengan niat untuk bermain-main.",
  ui_story_5081_50810701_44_dialog_content = "Haha, itu benar! Ketika saya pertama kali muncul, tujuan saya jelas—untuk menemukan teman yang hilang saya Gronru.",
  ui_story_5081_50810701_45_dialog_content = "Tahu kan, dia adalah orang yang memperkenalkan saya pada banyak permainan.",
  ui_story_5081_50810701_46_dialog_content = "Sebagian besar waktu, saya hanya menerima mereka karena dia memberikannya kepada saya.",
  ui_story_5081_50810701_47_dialog_content = "Dan saya hanya akan memainkannya karena mereka datang dari seorang teman.",
  ui_story_5081_50810701_48_dialog_content = "Itulah mengapa saya tidak pernah membayangkan bahwa saya akan menyukai arcade sebanyak ini sekarang.",
  ui_story_5081_50810701_49_dialog_content = "Ketika aku memikirkan semua pertandingan yang kita mainkan hari ini...",
  ui_story_5081_50810701_50_dialog_content = "Aku menyadari betapa senangnya aku berada di sini.",
  ui_story_5081_50810701_51_dialog_content = "Hmm... Aku paham.",
  ui_story_5081_50810701_52_dialog_content = "Kamu benar-benar mampu menikmati video game.",
  ui_story_5081_50810701_53_dialog_content = "Aku tidak tahu apakah ini karena sejarahku, tujuanku, atau mungkin beberapa tanggung jawab yang sedang kubebankan...",
  ui_story_5081_50810701_54_dialog_content = "Tapi... agak sulit bagiku untuk menerima bahwa aku menyukai hal semacam ini.",
  ui_story_5081_50810701_55_dialog_content = "Jadi, bisa bermain video game seperti ini, tanpa takut dihakimi, membantu saya menghadapi konflik batin itu secara langsung...",
  ui_story_5081_50810701_56_dialog_content = "Jika aku bisa menikmati game seperti kamu dan Gronru, aku yakin kita akan bisa lebih memahami satu sama lain.",
  ui_story_5081_50810701_57_dialog_content = "<size=30>Gronru... Aku sangat iri dia punya teman seperti kamu...</size>",
  ui_story_5081_50810701_58_dialog_content = "Jadi, Anda memang mengenal dia?",
  ui_story_5081_50810701_59_dialog_content = "S-Semacam itu... Dia adalah gamer veteran setelah semua, dan dia telah membuat banyak kontribusi khusus untuk komunitas.",
  ui_story_5081_50810701_60_dialog_content = "T-Tapi itu saja yang saya tahu tentang dia... Tolong jangan tanyakan saya pertanyaan lagi!",
  ui_story_5081_50810701_61_dialog_content = "Wow... Kedua orang itu sangat megah!",
  ui_story_5081_50810701_62_dialog_content = "Oh! Eh, apakah kamu mendengar itu? Sepertinya kita mungkin memiliki beberapa penantang baru di arcade!",
  ui_story_5081_50810701_63_dialog_content = "K-Kita mungkin harus pergi melihatnya!",
  ui_story_5081_50810701_64_dialog_content = "(Dia meminta untuk bertemu dengan para penantang sendiri? Itu pemandangan yang jarang...)",
  ui_story_5081_50810701_65_dialog_content = "(Sepertinya dia menghindari topik. Apakah dia sedang membicarakan tentang Gronru?)",
  ui_story_5081_50810701_66_dialog_content = "(Meski terlihat mencurigakan, saya pikir bermain game adalah peluang terbaik saya untuk mengetahui lebih banyak.)",
  ui_story_5081_50810701_67_dialog_content = "Tentu, mari kita menuju ke sana!",
  ui_story_5081_50810701_68_dialog_content = "<color=#e8d9bb>Pada titik itu, dua penantang dengan gaya yang sangat unik sudah menarik perhatian seluruh arcade.</color>",
  ui_story_5081_50810701_69_dialog_content = "<color=#e8d9bb>Salah satunya duduk di sofa dengan gaya yang keren.</color>",
  ui_story_5081_50810701_70_dialog_content = "Apakah toko ini sengaja didesain untuk terlihat begitu retro?",
  ui_story_5081_50810701_71_dialog_content = "Lampu dan dekorasi semuanya bergaya, dan mereka ditempatkan dengan sangat sempurna di seluruh arcade.",
  ui_story_5081_50810701_72_dialog_content = "Saya tidak sabar untuk berusaha sekuat tenaga untuk tantangan ini!",
  ui_story_5081_50810701_73_dialog_content = "<color=#e8d9bb>Yang lainnya melompat-lompat di sekitar toko dengan gembira seperti kelinci.</color>",
  ui_story_5081_50810701_74_dialog_content = "Wow, apakah ini mesin cakar? Hadiah di dalamnya sangat manis sekali!",
  ui_story_5081_50810701_75_dialog_content = "Dan ini pasti tempat kamu menukarkan poin untuk hadiah! Oh, aku mau semua yang mereka miliki...",
  ui_story_5081_50810701_76_dialog_content = "Katakanlah, bisakah saya membawa pulang setiap hadiah jika saya terus menang?",
  ui_story_5081_50810701_77_dialog_content = "Hmph!",
  ui_story_5081_50810701_78_dialog_content = "Tentu kamu bisa. Triknya adalah menang sebanyak itu terlebih dahulu.",
  ui_story_5081_50810701_79_dialog_content = "Tapi itu tidak perlu. Sebagai pemilik arcade, saya memiliki keputusan akhir di sini.",
  ui_story_5081_50810701_80_dialog_content = "Jika kamu bisa mengalahkan saya dalam sebuah permainan, kamu bisa mengambil apa saja yang kamu inginkan, dan sebanyak yang kamu inginkan.",
  ui_story_5081_50810701_81_dialog_content = "Oh? Sekarang kita bicara...",
  ui_story_5081_50810701_82_dialog_content = "Saya telah mendengar tentang gamer legendaris \"B\" dan arkadenya, tetapi saya tidak pernah mengharapkan dia seberani ini. Saya suka itu!",
  ui_story_5081_50810701_83_dialog_content = "Wow, itu sangat murah hati dari Anda! Dalam hal ini... Saya akan berusaha sebaik mungkin untuk mengalahkan Anda!",
  ui_story_5081_50810701_84_dialog_content = "Wow! Sepertinya kita memiliki beberapa penantang baru! Mari kita beri tepuk tangan untuk Wild Witch dan Cutie Cake!",
  ui_story_5081_50810701_85_dialog_content = "Dua pemain akan melakukan tantangan mereka pada saat yang sama! <size=30>Tapi pertanyaan saya adalah, siapa sebenarnya mereka? Seorang pencapaian yang sombong dan seorang kolektor barang dagangan?</size>",
  ui_story_5081_50810701_86_dialog_content = "Ayo semangat untuk pertandingan seru lainnya di bawah ini—",
  ui_story_5081_50810702_1_dialog_content = "Sepertinya api dalam video game tidak sepanas api nyata...",
  ui_story_5081_50810702_2_dialog_content = "Aku sudah berusaha sebaik mungkin juga! Sepertinya aku harus membeli semua barang lucu ini untuk diriku sendiri...",
  ui_story_5081_50810702_3_dialog_content = "Pak, Tuan Buaya, bolehkah saya mencoba lencana itu sebentar?",
  ui_story_5081_50810702_4_dialog_content = "Maaf nona, tapi kamu harus menukarkan token untuk itu.",
  ui_story_5081_50810702_5_dialog_content = "Oh, oke! Aku akan pergi mendapatkannya sekarang juga!",
  ui_story_5081_50810702_6_dialog_content = "... Dan dia hanya kabur begitu saja?",
  ui_story_5081_50810702_7_dialog_content = "Katakanlah, kamu tidak tertarik untuk bersekutu denganku, 'kan?",
  ui_story_5081_50810702_8_dialog_content = "Dengan gamer legendaris \"B\" di sisi saya, kita bisa memulai era baru gaming di dunia!",
  ui_story_5081_50810702_9_dialog_content = "Ketika hari itu tiba, arcade kamu mungkin akan dipenuhi oleh semua pelanggan baru yang akan kamu miliki!",
  ui_story_5081_50810702_10_dialog_content = "A... Uh... Meskipun mengembangkan komunitas game bukanlah hal yang buruk...",
  ui_story_5081_50810702_11_dialog_content = "Aku belum pernah melakukan hal yang se-ekstrem itu, dan... dan aku benar-benar tidak ingin melakukannya juga! Maaf...",
  ui_story_5081_50810702_12_dialog_content = "Kuat tapi rendah hati, dan tetap pada apa yang kamu tahu, ya?",
  ui_story_5081_50810702_13_dialog_content = "Tidak apa-apa. Yang terpenting adalah kamu berhasil menarik perhatianku.",
  ui_story_5081_50810702_14_dialog_content = "Cari aku kapan saja jika kamu ingin bersekutu.",
  ui_story_5081_50810702_15_dialog_content = "D-Apakah kamu juga punya salah satu dari itu?",
  ui_story_5081_50810702_16_dialog_content = "Salah satu dari apa?",
  ui_story_5081_50810702_17_dialog_content = "Sebuah kartu dengan nama Anda di atasnya. Saya mendapatkan satu sebelumnya.",
  ui_story_5081_50810702_18_dialog_content = "Dia maksudnya kartu nama.",
  ui_story_5081_50810702_19_dialog_content = "Haha, tentu saja saya punya! Ini dia, berharap mendengar kabar dari kamu segera.",
  ui_story_5081_50810702_20_dialog_content = "Fiuh…",
  ui_story_5081_50810702_21_dialog_content = "Aku akan bilang itu berjalan cukup lancar, mengingat semua hal...",
  ui_story_5081_50810702_22_dialog_content = "Mengapa kamu tidak bertanya apakah mereka bersenang-senang kali ini?",
  ui_story_5081_50810702_23_dialog_content = "Anu…",
  ui_story_5081_50810702_24_dialog_content = "D-Apakah saya mengajukan pertanyaan yang salah lagi?",
  ui_story_5081_50810702_25_dialog_content = "B-Bahkan untuk seseorang seperti saya, mudah untuk melihat bahwa mereka memang bersenang-senang memainkan permainan itu...",
  ui_story_5081_50810702_26_dialog_content = "Namun, saat aku melihat mereka dalam game barusan...",
  ui_story_5081_50810702_27_dialog_content = "Mereka tampaknya tidak seantusias atau seasyik kamu, bukan?",
  ui_story_5081_50810702_28_dialog_content = "Kamu begitu marah padaku karena aku tidak fokus dalam permainan... Aku harap mereka tidak membuatmu marah juga!",
  ui_story_5081_50810702_29_dialog_content = "Tidak benar-benar, tidak. Kedua orang itu lebih seperti tipe sosial ketika bermain game.",
  ui_story_5081_50810702_30_dialog_content = "Apakah kamu ingat apa yang dikatakan oleh ahli barang antik itu sebelumnya?",
  ui_story_5081_50810702_31_dialog_content = "Ada sesuatu tentang video game yang merupakan gabungan dari teknologi dan hiburan, benar?",
  ui_story_5081_50810702_32_dialog_content = "Ya. Video game jauh lebih dari sekedar sesuatu untuk dimainkan.",
  ui_story_5081_50810702_33_dialog_content = "Sebuah game yang baik seperti sebuah karya seni—setiap aspek darinya memiliki potensi untuk menarik pemain.",
  ui_story_5081_50810702_34_dialog_content = "Beberapa orang bermain untuk cerita dan fokus pada detail-detail halus dari dunia dalam game.",
  ui_story_5081_50810702_35_dialog_content = "Orang lain lebih tertarik pada karya seni dan desain dari sebuah game dan bahkan mengundang orang lain untuk bermain peran bersama mereka.",
  ui_story_5081_50810702_36_dialog_content = "Terkadang, game bertema seperti itu menghasilkan gelombang minat yang besar. Itulah bagaimana banyak orang menjadi gamer pada awalnya.",
  ui_story_5081_50810702_37_dialog_content = "Ada lebih banyak hal dalam bermain game selain hanya mengalahkan level...",
  ui_story_5081_50810702_38_dialog_content = "Itulah sebabnya orang-orang yang tidak fokus pada kemenangan juga layak untuk menikmati permainan.",
  ui_story_5081_50810702_39_dialog_content = "Odi menyebutkan hal serupa lebih awal hari ini. Dia bilang bahwa bagian terpenting dari video game adalah pemainnya.",
  ui_story_5081_50810702_40_dialog_content = "Saya setuju. Sulit bagi pemain untuk menemukan kebahagiaan dalam video game ketika mereka menjauh dari komunitas game.",
  ui_story_5081_50810702_41_dialog_content = "Itulah mengapa aku membiarkan Gronru meyakinkan aku untuk mengambil alih arcade ini...",
  ui_story_5081_50810702_42_dialog_content = "Gronru lagi, huh?",
  ui_story_5081_50810702_43_dialog_content = "D-Apakah aku mengatakan itu? Maaf, aku tidak bermaksud mengungkitnya lagi! Lupakan saja!",
  ui_story_5081_50810702_44_dialog_content = "Ya, aku tahu prosedurnya. Aku tidak akan mengorek lebih jauh, aku janji.",
  ui_story_5081_50810702_45_dialog_content = "Meskipun seberapa sering kamu meremehkan hal-hal, saya pikir ini adalah sesuatu yang hanya bisa kamu capai...",
  ui_story_5081_50810702_46_dialog_content = "A-Apa itu?",
  ui_story_5081_50810702_47_dialog_content = "Mengelola arcade ini dan memberikan para gamer tempat untuk bersantai dan bersenang-senang.",
  ui_story_5081_50810702_48_dialog_content = "Siapa lagi selain legendaris \"B\" yang bisa melakukannya dengan begitu baik?",
  ui_story_5081_50810702_49_dialog_content = "T-Tapi aku sama sekali tidak pandai bersosialisasi dengan orang! Aku tidak merasa cocok untuk memberikan pengalaman positif kepada para gamer...",
  ui_story_5081_50810702_50_dialog_content = "Aku hanya menyediakan tempat, itu saja.",
  ui_story_5081_50810702_51_dialog_content = "Begitu menurutmu?",
  ui_story_5081_50810702_52_dialog_content = "Karena menurutku, sepertinya kamu berinteraksi dengan para penantang hari ini dengan baik.",
  ui_story_5081_50810702_53_dialog_content = "Ada alasan orang-orang menghormatimu dan berkumpul di tempat ini, tahu kan?",
  ui_story_5081_50810702_54_dialog_content = "Aku tidak begitu istimewa... dan meskipun kamu memuji saya, saya tetap tidak akan memberitahumu—",
  ui_story_5081_50810702_55_dialog_content = "Beri tahu apa?",
  ui_story_5081_50810702_56_dialog_content = "Bos! Kita punya pengunjung baru lagi!",
  ui_story_5081_50810702_57_dialog_content = "Apakah itu penantang? Aku akan segera ke sana...",
  ui_story_5081_50810702_58_dialog_content = "Tidak persis...",
  ui_story_5081_50810702_59_dialog_content = "Dia mengenakan seragam Illumina, dan dia berbicara seolah-olah dia mengikuti skrip. Saya tidak berpikir dia adalah sejenis gamer. Juga...",
  ui_story_5081_50810702_60_dialog_content = "Kamu tidak membuat seseorang marah belakangan ini, bukan PlayerName?",
  ui_story_5081_50810702_61_dialog_content = "Karena pria itu meminta kamu dengan namamu!",
  ui_story_5081_50810801_1_dialog_content = "Ada orang yang mengenakan seragam Illumina mencariku? Jangan bilang...",
  ui_story_5081_50810801_2_dialog_content = "Oh...",
  ui_story_5081_50810801_3_dialog_content = "Anda akhirnya di sini, PlayerName. Bolehkah saya berbicara dengan Anda, tolong?",
  ui_story_5081_50810801_4_dialog_content = "Tentu... Jangan khawatir, semua orang terlalu sibuk bermain game untuk memperhatikan kita.",
  ui_story_5081_50810801_5_dialog_content = "Senang bertemu dengan Anda lagi, Petugas Intelijen Anatoli.",
  ui_story_5081_50810801_6_dialog_content = "Begitu juga, PlayerName. Saya akan langsung ke pokoknya.",
  ui_story_5081_50810801_7_dialog_content = "Pertama, izinkan saya untuk berterima kasih atas usaha kamu dalam membantu Illumina selama masa kritis ini.",
  ui_story_5081_50810801_8_dialog_content = "Jika boleh saya tanya, bagaimana perkembangan penyelidikan Anda?",
  ui_story_5081_50810801_9_dialog_content = "Untuk mengatakannya dengan satu cara, aku telah mengalahkan sekitar lima dari delapan gym...",
  ui_story_5081_50810801_10_dialog_content = "Begitu. Maksudmu misimu sudah selesai sebanyak enam puluh dua koma lima persen?",
  ui_story_5081_50810801_11_dialog_content = "Yah, aku juga harus mengalahkan Elite Four...",
  ui_story_5081_50810801_12_dialog_content = "Bisakah saya meminta Anda menjelaskan hal-hal dengan bahasa yang mudah dimengerti?",
  ui_story_5081_50810801_13_dialog_content = "Haha... Agak sulit mengukur kemajuan saat kamu mencari seseorang.",
  ui_story_5081_50810801_14_dialog_content = "Tapi, aku telah berusaha semampuku untuk menjalankan misi ini untuk Migard dan Komite! Percayalah padaku, aku akan menyelesaikannya!",
  ui_story_5081_50810801_15_dialog_content = "Begitu ya? Sekali lagi, aku berterima kasih atas kontribusimu pada Illumina.",
  ui_story_5081_50810801_16_dialog_content = "Menurut informasi saya, tempat ini memang memiliki beberapa permainan yang sangat menarik.",
  ui_story_5081_50810801_17_dialog_content = "Ditambah dengan suasana yang nyaman ini, ini adalah tempat yang sempurna untuk melupakan segala kekhawatiran dan tenggelam dalam dunia maya.",
  ui_story_5081_50810801_18_dialog_content = "Ketika aku menunggumu, aku khawatir bahwa kau juga telah tersesat di dunia-dunia ini... tapi sepertinya aku terlalu memikirkan banyak hal.",
  ui_story_5081_50810801_19_dialog_content = "Saya tidak akan pernah kehilangan pandangan tentang misi sepenting ini! Kamu benar-benar tidak seharusnya bergurau seperti itu, Anatoli! Hahaha...",
  ui_story_5081_50810801_20_dialog_content = "Jadi, apakah kamu hanya datang ke sini untuk mendapatkan laporan status untuk Migard?",
  ui_story_5081_50810801_21_dialog_content = "Untuk jujur, tidak. Bahkan, bisa dibilang kita memiliki sedikit konflik di antara kita.",
  ui_story_5081_50810801_22_dialog_content = "Konflik?",
  ui_story_5081_50810801_23_dialog_content = "Ini bukan hal yang perlu dikhawatirkan. Saat berbicara tentang misi, tujuan kita masih tetap sama.",
  ui_story_5081_50810801_24_dialog_content = "Para pemain di sini jauh lebih tertarik pada teknologi kuno daripada kebanyakan orang. Saya percaya saya bisa mengumpulkan beberapa informasi yang sangat menarik dari mereka.",
  ui_story_5081_50810801_25_dialog_content = "... Kalau saja aku bisa tinggal sedikit lebih lama.",
  ui_story_5081_50810801_26_dialog_content = "Jika itu yang kamu rasakan, kenapa kita tidak mencari sesuatu untukmu mainkan?",
  ui_story_5081_50810801_27_dialog_content = "Yah, ada satu permainan yang telah menarik minat saya.",
  ui_story_5081_50810801_28_dialog_content = "Yang bernama Krisis Eclipsite.",
  ui_story_5081_50810801_29_dialog_content = "Eclipsite dalam game ini seharusnya cukup realistis, begitu juga dengan senjata yang tersedia untuk pemain.",
  ui_story_5081_50810801_30_dialog_content = "Saya kadang-kadang bertanya-tanya apakah itu dikembangkan dari program latihan Illumina yang gagal.",
  ui_story_5081_50810801_31_dialog_content = "Bagaimana kalau kamu coba saja? Aku masih punya banyak token, setelah semua.",
  ui_story_5081_50810801_32_dialog_content = "Kurasa aku akan. Kemurahan hatimu sangat kami hargai.",
  ui_story_5081_50810801_33_dialog_content = "<color=#e8d9bb>Tik, tik, tik, tik—</color>",
  ui_story_5081_50810801_34_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5081_50810801_35_dialog_content = "Graah...",
  ui_story_5081_50810801_36_dialog_content = "Kontrolnya ternyata sangat lancar dan responsif! Sangat menantang untuk pemain!",
  ui_story_5081_50810801_37_dialog_content = "<color=#e8d9bb>Tik, tik, tik, tik—</color>",
  ui_story_5081_50810801_38_dialog_content = "Pertempuran itu juga sangat realistis! Sayangnya, token tidak bisa digunakan untuk menghidupkan kembali kawan-kawan kita yang gugur dalam kehidupan nyata...",
  ui_story_5081_50810801_39_dialog_content = "...",
  ui_story_5081_50810801_40_dialog_content = "Hah? Kamu belum menyelesaikan level ini, Anatoli.",
  ui_story_5081_50810801_41_dialog_content = "Aku tidak datang ke sini untuk bermain game. Aku hanya ingin mencobanya sebentar sendiri.",
  ui_story_5081_50810801_42_dialog_content = "Dan sekarang setelah aku punya, aku hanya bisa merasa sedikit menyesal.",
  ui_story_5081_50810801_43_dialog_content = "Menyesal?",
  ui_story_5081_50810801_44_dialog_content = "Game ini memiliki potensi untuk berfungsi sebagai program pelatihan yang tepat dan sangat membantu kami dalam pertempuran masa depan...",
  ui_story_5081_50810801_45_dialog_content = "Tapi sepertinya pemain di sini hanya menghargainya sebagai sumber hiburan.",
  ui_story_5081_50810801_46_dialog_content = "Membuatku bertanya-tanya, jika begitu banyak orang merasa senang dalam menghancurkan Eclipsite dalam permainan...",
  ui_story_5081_50810801_47_dialog_content = "Bukankah waktu dan energi mereka lebih baik dihabiskan untuk membasmi Eclipsite yang sebenarnya di medan perang?",
  ui_story_5081_50810801_48_dialog_content = "Apakah ini benar-benar nilai dari video game Astra? Mungkin saya tidak sepenuhnya mengerti, tapi sepertinya ini sia-sia—",
  ui_story_5081_50810801_49_dialog_content = "<color=#e8d9bb>Tik, tik, tik, tik—</color>",
  ui_story_5081_50810801_50_dialog_content = "Hah? Itu—",
  ui_story_5081_50810801_51_dialog_content = "Meninggalkan permainan saat masih belum selesai... Jika ada yang pemborosan, itu adalah kamu.",
  ui_story_5081_50810801_52_dialog_content = "Aku tidak akan membiarkan perilaku seperti ini di arcade saya.",
  ui_story_5081_50810801_53_dialog_content = "Arcade milikmu, katamu? Kamu pasti pemiliknya.",
  ui_story_5081_50810801_54_dialog_content = "Maafkan saya jika saya melanggar aturan di tempat Anda. Saya akan pastikan untuk bermain sampai selesai mulai sekarang.",
  ui_story_5081_50810801_55_dialog_content = "Kamu seorang prajurit dari Illumina, bukan?",
  ui_story_5081_50810801_56_dialog_content = "Memang begitu.",
  ui_story_5081_50810801_57_dialog_content = "Lalu kumpulkan semua keterampilan dan pengalaman latihan Anda—coba untuk mengalahkan skor saya!",
  ui_story_5081_50810801_58_dialog_content = "Saya tidak memiliki keinginan untuk bersaing, tapi jika ini yang kamu inginkan...",
  ui_story_5081_50810801_59_dialog_content = "<color=#e8d9bb>Tik, tik, tik—tik, tik, tik, tik</color>",
  ui_story_5081_50810801_60_dialog_content = "<color=#e8d9bb>Duar! Duar!</color>",
  ui_story_5081_50810801_61_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5081_50810801_62_dialog_content = "L-Luar biasa! Mereka bermain seolah-olah mereka kerasukan oleh monster!",
  ui_story_5081_50810801_63_dialog_content = "Tapi Anatoli... Entah bagaimana, skornya jauh lebih rendah daripada miliknya!",
  ui_story_5081_50810801_64_dialog_content = "Kurasa... belum pernah kulihat dia bermain dengan serius seperti ini sebelumnya...",
  ui_story_5081_50810801_65_dialog_content = "Menurut pendapatmu... apakah aku tidak pantas mendapatkan ini?",
  ui_story_5081_50810801_66_dialog_content = "... Maaf, tapi apakah Anda berbicara dengan saya?",
  ui_story_5081_50810801_67_dialog_content = "Ya. Sebagai seseorang yang tidak bisa melawan Eclipsite di dunia nyata... Apakah menurutmu saya berhak untuk melawan mereka dalam video game?",
  ui_story_5081_50810801_68_dialog_content = "Bukankah mungkin ada orang yang memang tidak ditakdirkan untuk bertarung melawan Eclipsite... atau bahkan meninggalkan keamanan rumah mereka?",
  ui_story_5081_50810801_69_dialog_content = "Tapi meski begitu, mungkin mereka masih ingin membuat perlawanan terhadap monster-monster yang telah menguasai dunia kita...",
  ui_story_5081_50810801_70_dialog_content = "Meskipun hanya dengan memberikan setiap orang tempat untuk berkumpul dan bersenang-senang.",
  ui_story_5081_50810801_71_dialog_content = "Orang seperti itu... masih punya sesuatu untuk ditawarkan ke dunia, bukan menurutmu?",
  ui_story_5081_50810801_72_dialog_content = "Aku…",
  ui_story_5081_50810801_73_dialog_content = "Jangan kehilangan fokus atau kamu akan kalah.",
  ui_story_5081_50810801_74_dialog_content = "Maafkan aku.",
  ui_story_5081_50810801_75_dialog_content = "Aku akan fokuskan seluruh kekuatanku untuk menyelesaikan game ini...",
  ui_story_5081_50810802_1_dialog_content = "<color=#e8d9bb>Misi Selesai!</color>",
  ui_story_5081_50810802_2_dialog_content = "Apakah sudah berakhir sekarang? Saya hampir tidak percaya bahwa begitu banyak waktu telah berlalu.",
  ui_story_5081_50810802_3_dialog_content = "Atau aku kalah dengan selisih yang begitu besar...",
  ui_story_5081_50810802_4_dialog_content = "Saya harus mengakui, keahlian menembak Anda sama tajamnya dengan kemahiran Anda dalam video game.",
  ui_story_5081_50810802_5_dialog_content = "Saya percaya bahwa kemampuanmu hanya dapat dilewati oleh Aurorian yang telah menjalani pelatihan tempur khusus dari Perwira Yingel...",
  ui_story_5081_50810802_6_dialog_content = "Apakah kamu bersenang-senang?",
  ui_story_5081_50810802_7_dialog_content = "Hmm?",
  ui_story_5081_50810802_8_dialog_content = "Ya, benar! Jika saya harus menilai kualitas game ini, saya akan memberikannya penilaian tertinggi yang mungkin.",
  ui_story_5081_50810802_9_dialog_content = "Tapi bisakah kamu beritahu aku kenapa kamu masih memainkannya?",
  ui_story_5081_50810802_10_dialog_content = "Oh! Jangan pedulikan aku, aku hanya menyelesaikan sisa misi sampingan... Aku merasa terganggu jika tidak menyelesaikan seluruh permainan.",
  ui_story_5081_50810802_11_dialog_content = "Dan juga... A-Aku merasa lebih berani saat berbicara dengan orang jika aku melihat layar!",
  ui_story_5081_50810802_12_dialog_content = "Tidak semua orang mendapatkan kesempatan untuk bertarung melawan Eclipsite di garis depan.",
  ui_story_5081_50810802_13_dialog_content = "Beberapa orang bekerja di ladang, sementara yang lain membangun pertahanan...",
  ui_story_5081_50810802_14_dialog_content = "Beberapa terbang ke seluruh Astra mengantarkan pesan penting, dan beberapa lainnya tetap di laboratorium mereka memecahkan masalah teknis...",
  ui_story_5081_50810802_15_dialog_content = "Tetapi saya pikir setiap orang pantas mendapatkan kesempatan untuk bersantai dan melepaskan tekanan, serta kesempatan untuk menantang diri mereka sendiri!",
  ui_story_5081_50810802_16_dialog_content = "Sesuatu yang membantu mereka memahami bahaya Eclipsite sekaligus memperbaharui keinginan mereka untuk bekerja menuju tujuan bersama...",
  ui_story_5081_50810802_17_dialog_content = "Tidakkah kamu pikir ini adalah cara yang baik untuk menghubungkan Aurorian yang tidak bisa melawan Eclipsite dengan mereka yang bisa?",
  ui_story_5081_50810802_18_dialog_content = "Apa, tepatnya?",
  ui_story_5081_50810802_19_dialog_content = "Dia sedang berbicara tentang permainan yang baru saja kamu mainkan, Anatoli.",
  ui_story_5081_50810802_20_dialog_content = "Aku melihat ekspresimu saat kamu bermain juga...",
  ui_story_5081_50810802_21_dialog_content = "Serius, tekun, bangga akan pencapaian Anda, dan terganggu oleh kegagalan Anda.",
  ui_story_5081_50810802_22_dialog_content = "Emosi-emosi itu tidak berbeda dengan yang kamu alami di luar bermain game, itulah sebabnya kamu harus memberikan Batia jawaban yang jujur.",
  ui_story_5081_50810802_23_dialog_content = "Apakah kamu benar-benar berpikir bahwa sesuatu itu hanya berharga jika bisa digunakan dalam perjuangan melawan Eclipsite?",
  ui_story_5081_50810802_24_dialog_content = "...",
  ui_story_5081_50810802_25_dialog_content = "Mohon maafkan aku karena tidak segera menyadari kesalahanku...",
  ui_story_5081_50810802_26_dialog_content = "Beberapa hal yang baru saja saya katakan... ditujukan untuk orang-orang yang bahkan tidak ada di sini sekarang.",
  ui_story_5081_50810802_27_dialog_content = "Mungkin aku mencoba melampiaskan stres dan kekesalanku pada mereka.",
  ui_story_5081_50810802_28_dialog_content = "Izinkan saya menggunakan pengetahuan yang saya peroleh saat bermain game ini untuk memperbaiki jawaban saya.",
  ui_story_5081_50810802_29_dialog_content = "Tentu, silakan.",
  ui_story_5081_50810802_30_dialog_content = "Video game tidaklah sia-sia—jauh dari itu, sebenarnya.",
  ui_story_5081_50810802_31_dialog_content = "Suasana arcade ini adalah cerminan langsung dari misi asli Illumina.",
  ui_story_5081_50810802_32_dialog_content = "Perjuangan dan pengorbanan kita yang tak berujung, bukankah itu semua demi menciptakan dunia yang damai, bebas dari ancaman Eclipsite?",
  ui_story_5081_50810802_33_dialog_content = "Dunia di mana mereka yang tidak bisa melindungi diri dari Eclipsite juga bisa memiliki kehidupan yang panjang dan bahagia...",
  ui_story_5081_50810802_34_dialog_content = "Pengorbanan tak terhitung yang telah kita lakukan hingga saat ini adalah yang benar-benar penting.",
  ui_story_5081_50810802_35_dialog_content = "Berjuang dan berkorban hanya demi melakukannya adalah kehilangan pandangan tentang tujuan dan keinginan kita.",
  ui_story_5081_50810802_36_dialog_content = "Ah... Maaf telah memberikan tanggapan yang begitu panjang.",
  ui_story_5081_50810802_37_dialog_content = "Tapi hati dan pikiran saya sangat terhibur sekarang... Terima kasih, PlayerName dan Nona Batia.",
  ui_story_5081_50810802_38_dialog_content = "...",
  ui_story_5081_50810802_39_dialog_content = "Aku tidak mengatakan apa-apa, tahu. Mungkin ini adalah sesuatu yang permainan ini ingin tunjukkan kepada kamu?",
  ui_story_5081_50810802_40_dialog_content = "Memang, saya tidak pernah mempertimbangkan pikiran dan perasaan mereka yang tidak bisa melawan Eclipsites sebelum bermain game ini.",
  ui_story_5081_50810802_41_dialog_content = "Tapi sekarang aku merasa telah memperoleh pemahaman yang sedikit lebih baik.",
  ui_story_5081_50810802_42_dialog_content = "Saya harus mempertahankan pendekatan yang lebih terbuka saat mengumpulkan intelijen mulai sekarang...",
  ui_story_5081_50810802_43_dialog_content = "Jangan lupa untuk bersantai dan menikmati diri sendiri sesekali! Kamu selalu diterima di arcade!",
  ui_story_5081_50810802_44_dialog_content = "Terima kasih. Saya hanya berharap Chief Yingel juga bisa melihat hal ini seperti itu.",
  ui_story_5081_50810802_45_dialog_content = "<size=30>Dia telah terlalu memaksakan diri akhir-akhir ini, mungkin lebih dari yang diperlukan.</size>",
  ui_story_5081_50810802_46_dialog_content = "... Tapi jangan khawatir. Saya akan memastikan bahwa masalah ini mencapai kesimpulan yang memuaskan.",
  ui_story_5081_50810802_47_dialog_content = "Uh, ada apa?",
  ui_story_5081_50810802_48_dialog_content = "Aku akan menghubungi kamu setelah masalah ini terselesaikan, tenang saja.",
  ui_story_5081_50810802_49_dialog_content = "Sampai saat itu, harap tunggu dengan sabar kabar baik dari saya...",
  ui_story_5081_50810802_50_dialog_content = "... Apakah dia pergi?",
  ui_story_5081_50810802_51_dialog_content = "Ya... Dan rasanya seperti dia menyembunyikan sesuatu yang penting dari kami.",
  ui_story_5081_50810802_X51_dialog_content = "(Setelah mengantar Jomu bersama Odi dan membantu Batia dengan beberapa pekerjaan rumah, hari itu hampir berakhir.)",
  ui_story_5081_50810802_X52_dialog_content = "(Pelanggan mulai pulang karena sudah malam. Ketika hanya Batia dan saya yang tersisa di arcade, kami memutuskan untuk menutup toko dan pergi berjalan-jalan di luar.)",
  ui_story_5081_50810802_X53_dialog_content = "Terima kasih…",
  ui_story_5081_50810802_X54_dialog_content = "Untuk apa kamu berterima kasih padaku kali ini?",
  ui_story_5081_50810802_52_dialog_content = "Untuk banyak hal! Pertama-tama, terima kasih telah membantu saya berbicara dengan prajurit dari Illumina... Tapi saya harus bertanya...",
  ui_story_5081_50810802_53_dialog_content = "Apa yang baru saja aku katakan padanya... Apakah aku terlalu jauh?",
  ui_story_5081_50810802_54_dialog_content = "Setelah semua... A-Aku hanya seorang pemalas tak berguna yang hanya tahu cara bermain game...",
  ui_story_5081_50810802_55_dialog_content = "Itulah alasan saya menghargai permainan seperti ini, jadi saya...",
  ui_story_5081_50810802_56_dialog_content = "Kamu tidak pergi terlalu jauh, jadi berhentilah meragukan dirimu sendiri terlalu banyak!",
  ui_story_5081_50810802_57_dialog_content = "Aku tidak berpikir ada satu pun Aurorian di Astra yang lebih buruk dari aku dalam bertarung melawan Eclipsite.",
  ui_story_5081_50810802_58_dialog_content = "Tapi, apakah itu berarti keberadaanku tidak memiliki nilai?",
  ui_story_5081_50810802_59_dialog_content = "T-Tidak... Sama sekali bukan itu yang kumaksud! Ini hanya...",
  ui_story_5081_50810802_60_dialog_content = "Petugas intelijen itu juga membuat banyak poin bagus... Aku seharusnya tidak mempertanyakan dia seperti itu.",
  ui_story_5081_50810802_61_dialog_content = "Tapi kamu tahu... Aku sebenarnya agak bersemangat untuk melihat masa depan yang dia bicarakan...",
  ui_story_5081_50810802_62_dialog_content = "Dunia yang bebas dari ancaman Eclipsite... Sulit membayangkan sesuatu yang begitu indah.",
  ui_story_5081_50810802_63_dialog_content = "Jika hari itu pernah datang, mungkin Latihan Militer Gabungan akan berubah menjadi konvensi permainan terbesar Astra!",
  ui_story_5081_50810802_64_dialog_content = "Saya yakin kamu akan terlihat sangat keren berdiri di podium pemenang dan memegang piala juara pertama untuk setiap permainan—",
  ui_story_5081_50810802_65_dialog_content = "Berhenti! Aku tidak akan pernah bisa naik ke sana untuk menerima trofi... Itu adalah hal Gronru, bukan milikku!",
  ui_story_5081_50810802_66_dialog_content = "Tapi sampai dunia benar-benar terbebas dari Eclipsite...",
  ui_story_5081_50810802_67_dialog_content = "Mungkin saya ingin bermain game di mana saya bisa menghadapi mereka dengan tim Aurorian yang kuat...",
  ui_story_5081_50810802_68_dialog_content = "Dan akhirnya mengalahkan mereka semua!",
  ui_story_5081_50810802_69_dialog_content = "Meskipun satu video game tidak pernah bisa menangkap semua perjuangan Astra...",
  ui_story_5081_50810802_70_dialog_content = "Saya masih ingin mengalami dan memahami cerita-cerita itu sendiri!",
  ui_story_5081_50810802_71_dialog_content = "Nanti kau bisa mencicipinya.",
  ui_story_5081_50810802_72_dialog_content = "Hah?",
  ui_story_5081_50810802_73_dialog_content = "Aku tahu kamu bisa! Dan jika kamu tidak bisa melakukannya sendiri, minta saja Gronru untuk membuat lebih banyak game untukmu!",
  ui_story_5081_50810802_74_dialog_content = "Jika dia memasukkan kita semua dan cerita-cerita kita, aku yakin itu akan menjadi salah satu permainan terhebat yang pernah ada!",
  ui_story_5081_50810802_75_dialog_content = "Mintanya untuk membuat lebih banyak game? Tapi Gronru sedang mengalami kesulitan sekarang...",
  ui_story_5081_50810802_76_dialog_content = "B-Bos! Cepat datang!",
  ui_story_5081_50810802_77_dialog_content = "Masalah! Masalah! Cuit!",
  ui_story_5081_50810802_78_dialog_content = "Sulit dipercaya... Ini tidak bisa dipercaya!",
  ui_story_5081_50810802_79_dialog_content = "Ada apa?",
  ui_story_5081_50810802_80_dialog_content = "Bos terakhir dari semua penantang baru saja muncul!",
  ui_story_5081_50810802_81_dialog_content = "Dan dengan tentakel-tentakel itu, dia pasti tampak bagian... Jika kamu tidak berhati-hati...",
  ui_story_5081_50810802_82_dialog_content = "Legenda \"B\" akan benar-benar hancur! Cuit!",
  ui_story_5081_50810901_1_dialog_content = "I-Luar biasa...",
  ui_story_5081_50810901_2_dialog_content = "Dia sedang bermain lima game sekaligus... Tidak, enam!",
  ui_story_5081_50810901_3_dialog_content = "Dan dia benar-benar menghancurkan mereka!",
  ui_story_5081_50810901_4_dialog_content = "Gaya bermain ini tidak seperti apa yang pernah kulihat sebelumnya! Sepertinya dia diciptakan dengan satu tujuan...",
  ui_story_5081_50810901_5_dialog_content = "<size=45>Senjata pemungkas yang dibuat khusus untuk menghancurkan legenda!</size>",
  ui_story_5081_50810901_6_dialog_content = "Tidak, tidak…",
  ui_story_5081_50810901_7_dialog_content = "Dia bukan semacam senjata pamungkas atau apa pun. Dia hanya jenis Aurorian yang spesial...",
  ui_story_5081_50810901_8_dialog_content = "...",
  ui_story_5081_50810901_9_dialog_content = "No. 33, ada urusan apa kamu di sini? Apakah kamu datang untuk bermain beberapa game?",
  ui_story_5081_50810901_10_dialog_content = "... Caelestite?",
  ui_story_5081_50810901_11_dialog_content = "Sebentar, tolong. Saya akan menjelaskan kehadiran saya setelah saya menyelesaikan tugas yang ada di tangan.",
  ui_story_5081_50810901_12_dialog_content = "<color=#e8d9bb>Tentakel No. 33 perlahan-lahan berhenti, dan data yang ditampilkan di matanya akhirnya menghilang.</color>",
  ui_story_5081_50810901_13_dialog_content = "<color=#e8d9bb>Mesin arcade di sekelilingnya berkedip dengan pesan kemenangan, dan skornya muncul di semua papan skor mereka.</color>",
  ui_story_5081_50810901_14_dialog_content = "<color=#e8d9bb>Namun, masih ada jarak yang jelas antara skornya dan mereka yang duduk di puncak.</color>",
  ui_story_5081_50810901_15_dialog_content = "Sekarang setelah permainan selesai, izinkan saya menjelaskan alasan saya datang ke sini.",
  ui_story_5081_50810901_16_dialog_content = "Nama saya adalah No. 33, seorang guardian dari reruntuhan kuno Northland.",
  ui_story_5081_50810901_17_dialog_content = "Telah menjadi perhatianku bahwa sebuah kartrid data dari peradaban kuno telah ditemukan dan dipulihkan di tempat ini. Oleh karena itu, aku meminta izin dari Pengadilan Northland untuk bepergian ke sini.",
  ui_story_5081_50810901_18_dialog_content = "Niat asli saya adalah membelinya dan menganalisis isinya.",
  ui_story_5081_50810901_19_dialog_content = "Setelah tiba di arcade ini, namun, saya cepat menyadari bahwa semua game ini dibuat dengan memulihkan data kuno...",
  ui_story_5081_50810901_20_dialog_content = "Dan bahwa file mereka masih layak untuk dianalisis.",
  ui_story_5081_50810901_21_dialog_content = "Untuk alasan ini, saya langsung mulai melakukan penelitian tentang mereka. Saya siap untuk menawarkan pembayaran untuk data yang telah saya kumpulkan dan biaya apa pun yang mungkin saya keluarkan.",
  ui_story_5081_50810901_22_dialog_content = "Ti-Tidak perlu. Game ini dimaksudkan untuk dimainkan, dan kamu sudah menghabiskan token untuk memainkannya.",
  ui_story_5081_50810901_23_dialog_content = "Tapi menggunakan tentakel untuk bermain berbagai game... Aku belum pernah melihat hal seperti itu sebelumnya...",
  ui_story_5081_50810901_24_dialog_content = "Apakah mereka mudah digunakan?",
  ui_story_5081_50810901_25_dialog_content = "Maksudmu tentakelku? Mereka adalah bagian dari sistem guardian dan memungkinkan saya untuk mengelola berbagai struktur di dalam reruntuhan.",
  ui_story_5081_50810901_26_dialog_content = "Mereka tidak terlalu berguna untuk kehidupan sehari-hari Aurorian, tetapi mereka memang sangat membantu saat menjalankan perintah.",
  ui_story_5081_50810901_27_dialog_content = "Dan sekarang, aku menyadari bahwa mereka juga cukup cocok untuk bermain video game. Dibandingkan dengan pemain lain di arcade...",
  ui_story_5081_50810901_28_dialog_content = "Responsivitas, akurasi, dan sensitivitas tentakel saya memberi saya keuntungan yang jelas, tetapi pengetahuan mendalam tentang data game juga sangat penting.",
  ui_story_5081_50810901_29_dialog_content = "Apakah itu alasan Anda tidak dapat mendapatkan skor tertinggi barusan, No. 33?",
  ui_story_5081_50810901_30_dialog_content = "Atau mungkin karena ini adalah pertama kalinya kamu bermain? Mungkin kamu akan bisa menduduki puncak papan peringkat setelah kamu memahami permainan ini!",
  ui_story_5081_50810901_31_dialog_content = "Saya harus mendapatkan lebih banyak pengalaman sebelum sampai pada kesimpulan yang pasti.",
  ui_story_5081_50810901_32_dialog_content = "Semakin kompleks permainannya, semakin sulit pula, tetapi juga mengandung lebih banyak jalur optimal untuk penyelesaian.",
  ui_story_5081_50810901_33_dialog_content = "Adapun skor pada papan peringkat ini, saya tidak memiliki cara untuk menganalisanya saat ini.",
  ui_story_5081_50810901_34_dialog_content = "Saya hanya bisa memandang mereka dengan hormat.",
  ui_story_5081_50810901_35_dialog_content = "Itu sempurna! Lalu... Itu berarti kamu masih perlu mengumpulkan lebih banyak data permainan, 'kan?",
  ui_story_5081_50810901_36_dialog_content = "Mengapa tidak bermain bersama kami dan mendapatkan lebih banyak pengalaman lagi?",
  ui_story_5081_50810901_37_dialog_content = "Tentu saja. Perintah baru saya adalah untuk mengamati Aurorian modern dalam kehidupan sehari-hari mereka...",
  ui_story_5081_50810901_38_dialog_content = "Serta untuk memastikan keamanan masa depan mereka menggunakan data apa pun yang berguna dari peradaban kuno.",
  ui_story_5081_50810901_39_dialog_content = "Beraliansi dengan pemain yang hadir akan menjadi cara yang efisien untuk menjalankan perintah saya.",
  ui_story_5081_50810901_40_dialog_content = "Saya bisa mulai kapan saja.",
  ui_story_5081_50810901_41_dialog_content = "Ayo, semuanya! Mari kita bersenang-senang!",
  ui_story_5081_50810902_1_dialog_content = "<color=#e8d9bb>Dengan perencanaan Batia, setiap orang mulai bermain game melawan No. 33.</color>",
  ui_story_5081_50810902_2_dialog_content = "<color=#e8d9bb>Dengan pengecualian Odi, yang berhasil memenangkan satu atau dua pertandingan, No. 33 mengalahkan setiap orang dengan cara yang mengejutkan.</color>",
  ui_story_5081_50810902_3_dialog_content = "<color=#e8d9bb>Namun, Batia tetap mempertahankan gelarnya sebagai \"B\" legendaris dan tak terkalahkan.</color>",
  ui_story_5081_50810902_4_dialog_content = "Terima kasih, semua orang. Data dan pengamatan yang telah saya kumpulkan hari ini akan sangat berharga untuk penelitian saya.",
  ui_story_5081_50810902_5_dialog_content = "Maaf, tapi bolehkah saya meminjam beberapa permainan yang membutuhkan analisis panjang untuk menyelesaikannya?",
  ui_story_5081_50810902_6_dialog_content = "Saya percaya bahwa data yang tersembunyi dalam game ini akan sangat bermanfaat untuk masa depan semua Aurorian.",
  ui_story_5081_50810902_7_dialog_content = "Saya akan menganalisis mereka sejauh mungkin dan membuat temuan saya tersedia untuk setiap orang.",
  ui_story_5081_50810902_8_dialog_content = "Tentu saja! Ikutlah denganku, dan aku akan membawamu melihat koleksiku! Ambil saja apa pun yang kau pikir akan membantu!",
  ui_story_5081_50810902_9_dialog_content = "Saya akan memilih dengan bijak. Terima kasih atas kemurahan hati Anda.",
  ui_story_5081_50810902_10_dialog_content = "Saya rasa saya belum pernah melihat kamu sebersemangat ini, Batia...",
  ui_story_5081_50810902_11_dialog_content = "Oh, b-benarkah? Memangnya sejelas itu?",
  ui_story_5081_50810902_12_dialog_content = "Ya, tapi aku merasa sama persis seperti kamu sekarang.",
  ui_story_5081_50810902_13_dialog_content = "Di akhir hari, video game adalah cara yang bagus untuk menyatukan orang-orang dan membuat mereka ceria, ya?",
  ui_story_5081_50810902_14_dialog_content = "Siapa tahu? Setelah No. 33 menganalisis data dalam game-game tersebut, mungkin temuannya akan membantu industri game berkembang lebih jauh lagi.",
  ui_story_5081_50810902_15_dialog_content = "Dia bahkan mengatakan bahwa masa depan semua Aurorian mungkin akan mendapatkan manfaat dari permainanmu... Itu cukup menarik, bukan?",
  ui_story_5081_50810902_16_dialog_content = "Kamu benar-benar menyukai video game, PlayerName!",
  ui_story_5081_50810902_17_dialog_content = "Majukan game dan membuatnya lebih mudah diakses oleh dunia... Itu adalah hal terbaik yang bisa saya minta.",
  ui_story_5081_50810902_18_dialog_content = "Aku tak sabar ingin melihat apa yang akan dia temukan...",
  ui_story_5081_50810902_19_dialog_content = "Saya telah membuat pilihan saya. Ketika hasil penelitian saya jelas, saya akan memberi tahu Anda secepat mungkin, nona.",
  ui_story_5081_50810902_20_dialog_content = "B-Semoga berhasil!",
  ui_story_5081_50810902_21_dialog_content = "Aku harus pergi sekarang. Selamat tinggal.",
  ui_story_5081_50810902_22_dialog_content = "S-Sebenarnya... Bolehkah aku bertanya sesuatu sebelum kamu pergi?",
  ui_story_5081_50810902_23_dialog_content = "Dengan segala cara.",
  ui_story_5081_50810902_24_dialog_content = "Ini berkaitan... dengan orang-orang yang membuat game-game ini—peradaban yang hilang dari masa lalu...",
  ui_story_5081_50810902_25_dialog_content = "Bisakah kamu ceritakan kepada saya seperti apa dunia tempat mereka tinggal?",
  ui_story_5081_50810902_26_dialog_content = "Apakah ada... banyak permainan di dunia mereka? Permainan yang dikembangkan dengan lebih banyak makna untuk lebih dari sekedar hiburan?",
  ui_story_5081_50810902_27_dialog_content = "...",
  ui_story_5081_50810902_28_dialog_content = "Ini adalah dunia yang sangat maju, tetapi juga sangat menakutkan.",
  ui_story_5081_50810902_29_dialog_content = "\"Makna,\" tanyamu?",
  ui_story_5081_50810902_30_dialog_content = "Maaf, tetapi menganalisis data ini tidak akan memberikan saya jawaban yang Anda cari.",
  ui_story_5081_50810902_31_dialog_content = "Di dunia ini, makna dari sesuatu bukanlah konstan yang tidak berubah.",
  ui_story_5081_50810902_32_dialog_content = "Bagi mereka yang kedinginan dan kelaparan, apa pun di luar makanan dan pakaian adalah tidak berarti.",
  ui_story_5081_50810902_33_dialog_content = "Bagi mereka yang jiwa kosong, harta benda yang melimpah juga tidak berarti.",
  ui_story_5081_50810902_34_dialog_content = "Tapi di tempat ini, video game menjadi sumber kesenangan, fokus, dan persatuan. Itu membuat mereka memiliki arti.",
  ui_story_5081_50810902_35_dialog_content = "Sejauh perintah saya, teknologi yang memberi manfaat bagi penduduk setempat juga berarti.",
  ui_story_5081_50810902_36_dialog_content = "Video game juga tidak terkecuali.",
  ui_story_5081_50810902_37_dialog_content = "Jadi... Kamu pikir mereka bermakna?",
  ui_story_5081_50810902_38_dialog_content = "Ya. <color=#FFB400>Menurut pendapat saya</color>, mereka bermakna.",
  ui_story_5081_50810902_39_dialog_content = "Dan saya percaya... kamu juga harus melihat makna khusus mereka <color=#FFB400>dalam pendapatmu</color>.",
  ui_story_5081_50810902_40_dialog_content = "Ah...",
  ui_story_5081_50810902_41_dialog_content = "Ya, saya juga berpikir begitu.",
  ui_story_5081_50810902_42_dialog_content = "Pemainlah yang memberi makna pada permainan, bukan permainan itu sendiri.",
  ui_story_5081_50810902_43_dialog_content = "Hal terpenting adalah orang-orang yang dapat menemukan makna dalam video game!",
  ui_story_5081_50810902_44_dialog_content = "Apakah itu mereka yang mengumpulkan game, mengikuti tren terbaru, atau membeli merchandise game...",
  ui_story_5081_50810902_45_dialog_content = "Kamu bahkan mampu meyakinkan Anatoli tentang pentingnya video game!",
  ui_story_5081_50810902_46_dialog_content = "Video game tidak membedakan antara kaya dan miskin atau baik dan jahat. Siapa pun bisa menemukan makna dengan memainkannya!",
  ui_story_5081_50810902_47_dialog_content = "PlayerName…",
  ui_story_5081_50810902_48_dialog_content = "Jika kamu pernah bertemu dengan seseorang yang menggambarkan kehidupan atau gairah orang lain sebagai <color=#FFB400>tak berarti</color>...",
  ui_story_5081_50810902_49_dialog_content = "Jangan biarkan apa pun yang mereka katakan mempengaruhi kamu! Orang-orang seperti itu tidak peduli tentang makna atau nilai dari apa pun!",
  ui_story_5081_50810902_50_dialog_content = "Saya sangat mengagumi cinta Anda terhadap video game, Batia. Saya hanya berharap Anda tidak sering meragukan diri sendiri.",
  ui_story_5081_50810902_51_dialog_content = "Tolong, terus bagikan cintamu untuk game dengan orang lain. Jadikan arcade milikmu sebagai tempat yang aman bagi para gamer di seluruh dunia!",
  ui_story_5081_50810902_52_dialog_content = "Ah... Ahhhh! Oke, aku sudah mengerti! Tidak perlu berlebihan, PlayerName!",
  ui_story_5081_50810902_53_dialog_content = "Haha, maaf! Aku hanya sedikit khawatir tentangmu, jadi aku tidak bisa menahan diri untuk berbicara apa adanya...",
  ui_story_5081_50810902_54_dialog_content = "Terima kasih. Kurasa setiap orang yang suka video game seperti ini.",
  ui_story_5081_50810902_55_dialog_content = "Gronru juga pernah memberitahuku sesuatu seperti itu...",
  ui_story_5081_50810902_56_dialog_content = "Aku mengerti... Kamu sebenarnya cukup dekat dengannya, 'kan?",
  ui_story_5081_50810902_57_dialog_content = "Ya... Eh, PlayerName? Setelah aku tutup arcade hari ini, ada beberapa hal yang ingin kukatakan padamu...",
  ui_story_5081_50811001_1_dialog_content = "Waktu tutup! Semua orang keluar! Cuit!",
  ui_story_5081_50811001_2_dialog_content = "Aku tahu itu, sekarang diamlah!",
  ui_story_5081_50811001_3_dialog_content = "Tsk! Aku mulai merasa sedikit tidak nyaman. Apakah bola bayangan baru saja melewati pintu?",
  ui_story_5081_50811001_4_dialog_content = "Ataukah itu bola api?",
  ui_story_5081_50811001_5_dialog_content = "<color=#e8d9bb>Saat matahari terbenam di cakrawala, para pemain perlahan kembali ke rumah mereka dalam ketidaktahuan yang bahagia.</color>",
  ui_story_5081_50811001_6_dialog_content = "<color=#e8d9bb>Sementara itu, bayangan yang tidak menyenangkan diam-diam menyusup ke tempat ini yang penuh kegembiraan dan hiburan.</color>",
  ui_story_5081_50811001_7_dialog_content = "<color=#e8d9bb>Bisakah kamu merasakan panas yang mengganggu dan ilusi dari kehadirannya?</color>",
  ui_story_5081_50811001_8_dialog_content = "Suasana tiba-tiba menjadi lebih gelap di sini... Huh? Siapa yang meninggalkan game horor ini di sini?",
  ui_story_5081_50811001_9_dialog_content = "Ah maaf, sepertinya itu aku...",
  ui_story_5081_50811001_10_dialog_content = "Saya sedang mencari permainan untuk dimainkan di tempat bertenggerku malam ini, jadi mungkin saya telah meninggalkan beberapa permainan.",
  ui_story_5081_50811001_11_dialog_content = "Kamu tidak takut dengan game ini, bukan PlayerName?",
  ui_story_5081_50811001_12_dialog_content = "Tidak benar-benar, aku hanya sedikit terkejut ketika garis-garis tiba-tiba mulai bermain.",
  ui_story_5081_50811001_13_dialog_content = "Uh, apa maksudmu dengan \"sarang\"mu?",
  ui_story_5081_50811001_14_dialog_content = "Tertarik? Kamu bebas memeriksanya jika mau.",
  ui_story_5081_50811001_15_dialog_content = "Dikelilingi oleh banyak game dan lampu berkedip di malam hari membuatku merasa begitu aman dan hangat...",
  ui_story_5081_50811001_16_dialog_content = "Saya juga memiliki cukup makanan ringan dan minuman untuk bertahan sepanjang bulan!",
  ui_story_5081_50811001_17_dialog_content = "Hihihi...",
  ui_story_5081_50811001_18_dialog_content = "<color=#e8d9bb>Di bawah selimut malam, kamu jatuh ke dalam putus asa ketiadaan.</color>",
  ui_story_5081_50811001_19_dialog_content = "<color=#e8d9bb>Tangisan jiwa-jiwa yang tersiksa dari balik kubur bergema di setiap sudut kegelapan.</color>",
  ui_story_5081_50811001_20_dialog_content = "Ah...",
  ui_story_5081_50811001_21_dialog_content = "Apa kaudengar itu? Efek suara game ini pasti sangat realistis...",
  ui_story_5081_50811001_22_dialog_content = "It-Itu bukan dari permainan saya!",
  ui_story_5081_50811001_23_dialog_content = "L-Lalu apa itu?",
  ui_story_5081_50811001_24_dialog_content = "Jangan bilang itu adalah...",
  ui_story_5081_50811001_25_dialog_content = "Ah...",
  ui_story_5081_50811001_26_dialog_content = "Saya pikir itu datang dari sana!",
  ui_story_5081_50811001_27_dialog_content = "T-Tapi di situlah sarangku!",
  ui_story_5081_50811001_28_dialog_content = "Hei, tunggu!",
  ui_story_5081_50811001_29_dialog_content = "Ahhhhhhh?",
  ui_story_5081_50811001_30_dialog_content = "Ahhhhhhh!",
  ui_story_5081_50811001_31_dialog_content = "A-A hantu! Ada hantu yang menghantui sarangku!",
  ui_story_5081_50811001_32_dialog_content = "Ahhhh! PlayerName! Odi! Sork! Bekk! Seseorang tolong aku!",
  ui_story_5081_50811001_33_dialog_content = "Aku tidak pernah ingin bermain game menyeramkan lagi!",
  ui_story_5081_50811001_34_dialog_content = "Jangan khawatir, aku datang!",
  ui_story_5081_50811001_35_dialog_content = "Hah? Uriel... Apakah itu kamu?",
  ui_story_5081_50811001_36_dialog_content = "Krauk! Mengunyah, mengunyah... Glek, glek, glek...",
  ui_story_5081_50811001_37_dialog_content = "Ah. Camilan-camilan ini biasa saja, tetapi minuman-minuman ini cukup enak...",
  ui_story_5081_50811001_38_dialog_content = "Hai! Jangan tumpahkan apapun di mesin gameku! Ahhh...",
  ui_story_5081_50811001_39_dialog_content = "Tolong, aku tidak seceroboh itu. Aku hanya... membantumu membersihkannya, itu saja.",
  ui_story_5081_50811001_40_dialog_content = "Makhluk-makhluk jahat dan kotor... dengan kehidupan yang begitu tidak berarti.",
  ui_story_5081_50811001_41_dialog_content = "Musnah, musnah, musnah, musnah—",
  ui_story_5081_50811001_42_dialog_content = "Hilang bersamaku, keberadaan lain yang tak berarti...",
  ui_story_5081_50811001_43_dialog_content = "A-Apakah dia mencoba untuk m-membuangku di dunia nyata? Tantangan ini hanya untuk video game saja!",
  ui_story_5081_50811001_44_dialog_content = "... Saya cukup yakin itu bukan yang dia maksud...",
  ui_story_5081_50811001_45_dialog_content = "Dia kebetulan adalah Uriel... salah satu dari Four Angels Lumopolis!",
  ui_story_5081_50811001_46_dialog_content = "Seorang orang terkenal dari Lumopolis? Ap-Apa yang dia lakukan di sini?",
  ui_story_5081_50811001_47_dialog_content = "Ahhhh! Dia menumpahkan remah di seluruh keyboardku!",
  ui_story_5081_50811001_48_dialog_content = "Aku harus menghancurkan dunia ini... Aku harus membakarnya sampai habis...",
  ui_story_5081_50811001_49_dialog_content = "Apakah kamu punya ide berapa lama aku terjebak bersama keberadaan yang terkutuk itu?",
  ui_story_5081_50811001_50_dialog_content = "Dari senja hingga fajar dan kembali ke senja, panas tak pernah berhenti meningkat, dan aku tak pernah berhenti menyeret jiwa-jiwa malang itu ke neraka...",
  ui_story_5081_50811001_51_dialog_content = "Sangat menyakitkan di awal, tapi sekarang... Aku tidak merasakan apa-apa, jadi biarkan semuanya terbakar...",
  ui_story_5081_50811001_52_dialog_content = "Ikutlah denganku dan turunlah ke dalam limbo dari lupa...",
  ui_story_5081_50811001_53_dialog_content = "Mulai menjadi sangat panas di sini!",
  ui_story_5081_50811001_54_dialog_content = "Uriel, kamu harus tenang!",
  ui_story_5081_50811001_55_dialog_content = "Mesin permainanku... Dia akan membakarnya menjadi abu! File penyimpananku... bukan file penyimpananku!",
  ui_story_5081_50811001_56_dialog_content = "Tidak ada waktu... Kita hanya harus menenangkannya dan memindahkan semua dari sini!",
  ui_story_5081_50811001_57_dialog_content = "Odi! Sork! Bekk! Tolong kami!",
  ui_story_5081_50811002_1_dialog_content = "Apakah itu semuanya? Fiuh, saya pikir kita berhasil menyelamatkan sebagian besar...",
  ui_story_5081_50811002_2_dialog_content = "Apakah kita perlu mengambil sesuatu lagi dari ruangan itu?",
  ui_story_5081_50811002_3_dialog_content = "Tidak, kami rasa kami baik-baik saja... Terima kasih, setiap orang...",
  ui_story_5081_50811002_4_dialog_content = "Mengenai mesin game itu... biarkan saja dia memilikinya. Tidak masalah jika dia membakarnya...",
  ui_story_5081_50811002_5_dialog_content = "Meskipun Uriel terlihat sangat murung sebagian besar waktu, aku bertanya-tanya apa yang terjadi padanya?",
  ui_story_5081_50811002_6_dialog_content = "Mungkin aku harus meminta Carleen untuk menyelesaikan ini. Lagipula, Uriel masih sedikit takut pada kaptennya.",
  ui_story_5081_50811002_7_dialog_content = "Carleen bahkan mungkin bisa benar-benar mendinginkannya...",
  ui_story_5081_50811002_8_dialog_content = "... Aneh sekali.",
  ui_story_5081_50811002_9_dialog_content = "Apa yang aneh?",
  ui_story_5081_50811002_10_dialog_content = "Dia adalah salah satu dari Four Angels, yang berarti... dia mungkin telah melenyapkan lebih banyak Eclipsite daripada Aurorian lainnya, 'kan?",
  ui_story_5081_50811002_11_dialog_content = "Ya, saya kira...",
  ui_story_5081_50811002_12_dialog_content = "Dan di sini dia berada, menghabiskan waktu di arcade dan berusaha keras untuk mengalahkan Eclipsite dalam video game...",
  ui_story_5081_50811002_13_dialog_content = "Bukankah seorang pejuang terkenal dari Lumopolis seharusnya memiliki hal-hal yang lebih mulia untuk dilakukan dengan waktunya?",
  ui_story_5081_50811002_14_dialog_content = "Dia pasti melakukannya... Tunggu, biarkan saya mengubah kata-kata itu.",
  ui_story_5081_50811002_15_dialog_content = "Ketika Anda mengalahkan Eclipsite dalam video game, biasanya Anda mendapatkan semacam hadiah, atau itu memberi tahu Anda bahwa Anda telah menyelesaikan level. Hal itu tidak selalu terjadi dalam kehidupan nyata.",
  ui_story_5081_50811002_16_dialog_content = "Untuk Angel yang sedang gundah, mungkin itu yang dia inginkan?",
  ui_story_5081_50811002_17_dialog_content = "Aku paham... Kurasa setiap orang punya alasan mereka sendiri untuk ingin bermain game, ya?",
  ui_story_5081_50811002_18_dialog_content = "Saya yakin ada alasan yang lebih dalam di balik perilaku Uriel, tapi itu bukan alasan untuk memperlakukan kamu seperti ini.",
  ui_story_5081_50811002_19_dialog_content = "Aku hanya akan memberi tahu Carleen—",
  ui_story_5081_50811002_20_dialog_content = "Maaf, semuanya!",
  ui_story_5081_50811002_21_dialog_content = "Aku tidak bisa minta maaf cukup banyak untuk semua masalah yang telah kami sebabkan padamu!",
  ui_story_5081_50811002_22_dialog_content = "Hah? Kamu juga di sini, PlayerName? Bagus! Itu membuat segalanya jadi lebih mudah!",
  ui_story_5081_50811002_23_dialog_content = "Ada apa dengan dunia...",
  ui_story_5081_50811002_24_dialog_content = "Ada lebih banyak Eclipsite di area ini daripada biasanya.",
  ui_story_5081_50811002_25_dialog_content = "Uriel dikirim untuk membasmi mereka dan bertarung tanpa henti selama berhari-hari...",
  ui_story_5081_50811002_26_dialog_content = "Dia sungguh pekerja keras! Ketika dia akhirnya pulang, yang bisa dia katakan hanyalah—",
  ui_story_5081_50811002_27_dialog_content = "\"Kehancuran yang manis... Aku perlu pergi ke tempat di mana aku benar-benar bisa membersihkan Eclipsite...\" Dan tiba-tiba saja dia menghilang!",
  ui_story_5081_50811002_28_dialog_content = "Aku harus bertanya ke seluruh Lumopolis dan Umbraton sebelum mengetahui tentang tempat ini...",
  ui_story_5081_50811002_29_dialog_content = "Sebuah tempat di mana dia benar-benar bisa membersihkan Eclipsite... Dia berbicara tentang permainan di arcade ini! Ah, aku sangat iri!",
  ui_story_5081_50811002_30_dialog_content = "Cemburu?",
  ui_story_5081_50811002_31_dialog_content = "Apakah Lumopolis juga sangat sibuk akhir-akhir ini?",
  ui_story_5081_50811002_32_dialog_content = "Yup! Tidak ada hari libur ketika pekerjaanmu adalah memastikan keamanan semua orang, bagaimanapun juga...",
  ui_story_5081_50811002_33_dialog_content = "Tapi sepertinya Uriel membuat beberapa masalah untuk kalian, ya?",
  ui_story_5081_50811002_34_dialog_content = "Ada yang terluka? Jika ada, Lumopolis akan bertanggung jawab atas semua kerusakan!",
  ui_story_5081_50811002_35_dialog_content = "Jadi, tidak perlu membuat laporan buruk tentang apa yang terjadi di sini... Oke?",
  ui_story_5081_50811002_36_dialog_content = "Serahkan saja pemulihan toko itu padaku!",
  ui_story_5081_50811002_37_dialog_content = "Hah—",
  ui_story_5081_50811002_38_dialog_content = "Itu dia—",
  ui_story_5081_50811002_39_dialog_content = "Oh—",
  ui_story_5081_50811002_40_dialog_content = "Dan sekarang saatnya... untuk menangani bagian yang paling menjengkelkan!",
  ui_story_5081_50811002_41_dialog_content = "Huh? Oh, itu hanya kamu, Raphael...",
  ui_story_5081_50811002_42_dialog_content = "Saya menolak untuk kembali dengan seseorang yang menikmati kerja lembur, jadi hanya—",
  ui_story_5081_50811002_43_dialog_content = "Apa yang kamu bicarakan, Uriel? Saya di sini untuk membantu setiap orang, bukan karena saya sedang bekerja!",
  ui_story_5081_50811002_44_dialog_content = "Untuk mencegah kamu mengganggu publik, aku tidak punya pilihan lain selain menyeretmu kembali ke Lumopolis! Seru, kan?",
  ui_story_5081_50811002_45_dialog_content = "Tapi aku belum selesai di sini... Aku masih perlu membakar seluruh Astra...",
  ui_story_5081_50811002_46_dialog_content = "Sampai jumpa nanti, PlayerName! Oh, dan terima kasih sudah begitu pengertian, nona!",
  ui_story_5081_50811002_47_dialog_content = "Aku tahu kami telah menimbulkan banyak masalah untukmu, tapi izinkan aku mengatakan bahwa arcade milikmu benar-benar luar biasa.",
  ui_story_5081_50811002_48_dialog_content = "Bahkan seorang Aurorian seperti Uriel, yang menganggap segalanya tidak berarti, sangat menyukai tempat ini!",
  ui_story_5081_50811002_49_dialog_content = "Saya pasti akan kembali dan bermain suatu hari nanti juga! Sampai jumpa!",
  ui_story_5081_50811101_1_dialog_content = "... Apakah mereka akhirnya pergi? Cepat kunci pintu itu, Sork!",
  ui_story_5081_50811101_2_dialog_content = "Saya tidak bisa percaya dua orang terkenal muncul berturut-turut. Siapa berikutnya, Tuan Kota sendiri?",
  ui_story_5081_50811101_3_dialog_content = "... Mungkin tidak.",
  ui_story_5081_50811101_4_dialog_content = "Mungkin Queen Bethlehem? Itu terdengar sedikit lebih realistis, bukan?",
  ui_story_5081_50811101_5_dialog_content = "... Saya rasa bukan itu intinya.",
  ui_story_5081_50811101_6_dialog_content = "Aku tidak peduli siapa yang datang, asalkan bukan Sinsa. Jika dia tahu aku tertipu bekerja di sini secara gratis...",
  ui_story_5081_50811101_7_dialog_content = "Aku akan menjadi bahan tertawaan Rediesel Wrench selama bertahun-tahun yang akan datang!",
  ui_story_5081_50811101_8_dialog_content = "Dekade, bahkan! Kicauan!",
  ui_story_5081_50811101_9_dialog_content = "Berhenti, kalian! Kalian menakut-nakuti Batia!",
  ui_story_5081_50811101_10_dialog_content = "Oh...",
  ui_story_5081_50811101_11_dialog_content = "Mereka berterima kasih padaku sebelum mereka pergi.",
  ui_story_5081_50811101_12_dialog_content = "Hah?",
  ui_story_5081_50811101_13_dialog_content = "Uriel... Dia datang ke arcade saya atas kemauannya sendiri?",
  ui_story_5081_50811101_14_dialog_content = "Sepertinya begitu! Saya tidak tahu dia pergi ke arcade untuk melepas penat...",
  ui_story_5081_50811101_15_dialog_content = "Itu berarti toko Anda memberikan kontribusi signifikan dalam perang melawan Eclipsites, Batia!",
  ui_story_5081_50811101_16_dialog_content = "Aku tidak akan pergi sejauh itu. Adapun Uriel...",
  ui_story_5081_50811101_17_dialog_content = "Jika kita bisa bertemu dalam keadaan normal, mungkin saya bisa merekomendasikan beberapa game khusus untuknya.",
  ui_story_5081_50811101_18_dialog_content = "Tapi, hari ini... aku...",
  ui_story_5081_50811101_19_dialog_content = "Bagaimana dengan hari ini?",
  ui_story_5081_50811101_20_dialog_content = "Saya rasa saya belum pernah melihat pelanggan sebanyak ini dalam sehari!",
  ui_story_5081_50811101_21_dialog_content = "Aku tahu bahwa penjualan pra ini akan mendapatkan banyak perhatian dari seluruh Astra...",
  ui_story_5081_50811101_22_dialog_content = "Tapi, saya tidak pernah berharap melihat pelanggan yang aneh dan kuat sebanyak ini! Ada yang tidak beres tentang ini!",
  ui_story_5081_50811101_23_dialog_content = "Jadi akhirnya kamu menyadarinya—tapi sekarang sudah terlambat!",
  ui_story_5081_50811101_24_dialog_content = "?",
  ui_story_5081_50811101_25_dialog_content = "Saya membiarkan rumor seputar legendaris \"B\" dan arkadenya cepat menyebar melalui jaringan intelijen saya...",
  ui_story_5081_50811101_26_dialog_content = "Dan sekarang, saatnya bagi saya untuk menuai hasil kerja keras saya.",
  ui_story_5081_50811101_27_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5081_50811101_28_dialog_content = "Kalian semua telah dikelilingi, jadi tidak ada yang bergerak.",
  ui_story_5081_50811101_29_dialog_content = "?",
  ui_story_5081_50811101_30_dialog_content = "Kebenaran sering tersembunyi di bawah lapisan kegelapan, tetapi melalui penyelidikanku, semua akan terbawa ke cahaya.",
  ui_story_5081_50811101_31_dialog_content = "Setelah penyelidikan yang panjang, akhirnya saya telah mengungkap kebenaran di balik toko ini dan pemilik aslinya.",
  ui_story_5081_50811101_32_dialog_content = "Saya sudah meminta kerjasama dari Shadowlord dan sheriff Lumopolis—",
  ui_story_5081_50811101_33_dialog_content = "Untuk dugaan kepemilikan informasi rahasia, saya dengan ini menyatakan bahwa Hidden Fangs harus menutup pintunya menunggu penyelidikan lebih lanjut!",
  ui_story_5081_50811101_34_dialog_content = "A-Apa kau pikir kau ini siapa? Apa yang memberimu hak untuk melakukan itu?",
  ui_story_5081_50811101_35_dialog_content = "<color=#e8d9bb>Wush—</color>",
  ui_story_5081_50811101_36_dialog_content = "Berikut adalah surat perintah resmi, ditandatangani oleh setiap lembaga pemerintah yang terlibat dalam penyelidikan. Perlu saya katakan lebih banyak?",
  ui_story_5081_50811101_37_dialog_content = "K-Keberatan! Aku sama sekali tidak pernah melakukan hal seperti itu... Sumpah...",
  ui_story_5081_50811101_38_dialog_content = "Keberatanmu tidak membuat perbedaan. Lagipula, <color=#FFB400>kata-kata</color> tidak berarti apa-apa di tempat ini, bukan?",
  ui_story_5081_50811101_39_dialog_content = "Hanya tantangan yang akan berlaku!",
  ui_story_5081_50811101_40_dialog_content = "Sekarang tunggu sebentar saja!",
  ui_story_5081_50811101_41_dialog_content = "Aku tahu kau memiliki surat perintah yang telah ditandatangani secara resmi, dan aku tahu kau pasti telah bekerja sangat keras pada baris-baris itu baru saja...",
  ui_story_5081_50811101_42_dialog_content = "Tapi apa yang sedang kamu lakukan, Petugas Intelijen Yin—",
  ui_story_5081_50811101_43_dialog_content = "Itu bukan namaku! Aku adalah penantang yang dikenal sebagai \"Y\"!",
  ui_story_5081_50811101_44_dialog_content = "Dan aku berhasil menjejakkan kaki di arcade ini tepat sebelum pintunya ditutup!",
  ui_story_5081_50811101_45_dialog_content = "Si tak terkalahkan \"B\" adalah master di tempat ini, ya? Kamu tidak akan menolak tantanganku, bukan?",
  ui_story_5081_50811101_46_dialog_content = "...",
  ui_story_5081_50811101_47_dialog_content = "Jangan khawatir, Batia, aku akan bicara dengannya. Ini bagian dari misiku, setelah semua...",
  ui_story_5081_50811101_48_dialog_content = "Faktanya, saya mendengar Federasi Illumina siap untuk memobilisasi seluruh jaringan intelijen daratan mereka untuk mengejarnya.",
  ui_story_5081_50811101_49_dialog_content = "Untuk jujur, tidak. Bahkan, bisa dibilang kita memiliki sedikit konflik di antara kita.",
  ui_story_5081_50811101_50_dialog_content = "<size=30>Dia telah terlalu memaksakan diri akhir-akhir ini, mungkin lebih dari yang diperlukan.</size>",
  ui_story_5081_50811101_51_dialog_content = "... Tapi jangan khawatir. Saya akan memastikan bahwa masalah ini mencapai kesimpulan yang memuaskan.",
  ui_story_5081_50811101_52_dialog_content = "Jadi mereka telah membicarakan tentangmu selama ini, Yingel!",
  ui_story_5081_50811101_53_dialog_content = "Tidak heran Beretta mengatakan dia melihatmu di luar lebih awal hari ini... Dan apa masalah dengan kacamata hitam itu?",
  ui_story_5081_50811101_54_dialog_content = "Tatapan yang kurasakan saat pertama kali muncul bukan dari Batia... Itu adalah kamu!",
  ui_story_5081_50811101_55_dialog_content = "Jadi... Apa yang akan mereka lakukan pada Gronru setelah mereka menemukannya? Mereka tidak akan menghukumnya, bukan?",
  ui_story_5081_50811101_56_dialog_content = "Siapa tahu? Lagipula, ini bukan bidang keahlian saya.",
  ui_story_5081_50811101_57_dialog_content = "(... Federasi Illumina mengirim Yingel, prajurit terbaik mereka, untuk memburu Gronru!)",
  ui_story_5081_50811101_X57_dialog_content = "(Kamu tidak khawatir tentang ini? Mereka tidak benar-benar akan menyeretmu kembali dengan paksa, 'kan?!)",
  ui_story_5081_50811101_58_dialog_content = "Apa masalahnya, \"B\"? Jika itu sangat mengganggumu, maka terima saja tantanganku!",
  ui_story_5081_50811101_59_dialog_content = "Aku terima!",
  ui_story_5081_50811101_60_dialog_content = "Sebagai pemilik arcade ini, aku harus melindunginya!",
  ui_story_5081_50811101_61_dialog_content = "Tunggu... Jangan bilang kalian berdua akan—",
  ui_story_5081_50811101_62_dialog_content = "Saatnya duel!",
  ui_story_5081_50811102_1_dialog_content = "Ini sungguh semua yang kau punya? Aku mengharapkan lebih dari \"B\" legendaris.",
  ui_story_5081_50811102_2_dialog_content = "Hidupmu bagaikan lilin yang tertiup angin...",
  ui_story_5081_50811102_3_dialog_content = "Begitu menurutmu?",
  ui_story_5081_50811102_4_dialog_content = "Aku telah menyiapkan gerakan membunuh satu giliran ini hanya untukmu! Apakah kamu siap untuk itu?",
  ui_story_5081_50811102_5_dialog_content = "Apa...",
  ui_story_5081_50811102_6_dialog_content = "<color=#e8d9bb>Wuuss, wuuss, wuuss—boom!</color>",
  ui_story_5081_50811102_7_dialog_content = "<size=45>Tidak... Tidakkk!</size>",
  ui_story_5081_50811102_8_dialog_content = "HP Yingel langsung turun ke nol...",
  ui_story_5081_50811102_9_dialog_content = "Serius... Aku bahkan tidak sempat memberikan komentar tentang pertandingan itu!",
  ui_story_5081_50811102_10_dialog_content = "Kedua orang ini terus menjelaskan gerakan mereka setiap giliran, seperti permainan kartu yang membosankan!",
  ui_story_5081_50811102_11_dialog_content = "Heheh, surat perintah itu mungkin tidak berharga lagi sekarang!",
  ui_story_5081_50811102_12_dialog_content = "Tunggu, jangan membuatnya terdengar seperti kita hidup di dunia di mana memenangkan permainan dapat menyelesaikan segalanya!",
  ui_story_5081_50811102_13_dialog_content = "Bagaimana bisa seperti ini? Strategi saya sempurna! Saya telah mengamati Anda di tempat ini begitu lama...",
  ui_story_5081_50811102_14_dialog_content = "Gaya bermain Anda, kebiasaan Anda, dan bahkan pertempuran Anda melawan semua penantang itu...",
  ui_story_5081_50811102_15_dialog_content = "Tidak... Ini belum berakhir! Aku menolak untuk menerima kekalahan!",
  ui_story_5081_50811102_16_dialog_content = "Dua terbaik dari tiga! Kompetisi ini baru saja dimulai!",
  ui_story_5081_50811102_17_dialog_content = "Astaga... Yingel benar-benar mulai terdengar seperti penjahat kartun sekarang.",
  ui_story_5081_50811102_18_dialog_content = "Tidak masalah bagiku! Untuk melindungi arcade ku, aku akan mengalahkanmu sebanyak yang dibutuhkan...",
  ui_story_5081_50811102_19_dialog_content = "Ini adalah apa yang PlayerName dan yang lainnya ajarkan kepada saya tentang menjadi pemilik tempat ini!",
  ui_story_5081_50811102_20_dialog_content = "Saatnya duel!",
  ui_story_5081_50811102_21_dialog_content = "Hentikan sudah—",
  ui_story_5081_50811102_22_dialog_content = "Maafkan gangguannya.",
  ui_story_5081_50811102_23_dialog_content = "Maafkan saya... karena datang begitu terlambat.",
  ui_story_5081_50811102_24_dialog_content = "Officer Yingel sudah ada di sini, saya lihat. Mohon maafkan saya karena tidak menghentikannya lebih cepat.",
  ui_story_5081_50811102_25_dialog_content = "Tidak apa-apa, kamu datang tepat pada waktunya! Masih tidak terlambat untuk membuatnya mundur!",
  ui_story_5081_50811102_26_dialog_content = "Aku mengerti.",
  ui_story_5081_50811102_27_dialog_content = "Petugas Yingel, ada lebih banyak misi ini daripada yang kita pikirkan sebelumnya.",
  ui_story_5081_50811102_28_dialog_content = "Tech Officer Gronru adalah anggota penting dari departemen penelitian kami... tetapi dia juga orang yang sangat beremosi.",
  ui_story_5081_50811102_29_dialog_content = "Saya sudah berbicara dengan Officer Migard dan Komite.",
  ui_story_5081_50811102_30_dialog_content = "Daripada mencoba memaksanya untuk kembali, lebih baik bagi kita untuk melanjutkan dengan tugas-tugas kita sendiri.",
  ui_story_5081_50811102_31_dialog_content = "Untuk saat ini, tolong serahkan penyelidikan tentang keberadaan Petugas Gronru kepada PlayerName. Sedangkan untuk kita—",
  ui_story_5081_50811102_32_dialog_content = "Sudah memanggil bantuan, huh?",
  ui_story_5081_50811102_33_dialog_content = "Hanya gangguan kecil, tidak lebih. Mari kita lanjutkan.",
  ui_story_5081_50811102_34_dialog_content = "Bandinganku kepada akal sehat sepenuhnya tidak didengar!",
  ui_story_5081_50811102_35_dialog_content = "Tampaknya saya harus memperbarui informasi saya mengenai Petugas Yingel sekali lagi...",
  ui_story_5081_50811102_36_dialog_content = "Tidak, Anatoli, kamu pasti sudah melakukan yang terbaik. Hanya saja dia bukan Petugas Intelijen Yingel saat ini—dia adalah penantang yang dikenal sebagai \"Y.\"",
  ui_story_5081_50811102_37_dialog_content = "Aku tahu apa yang sebenarnya kamu cari, \"Y\"! Itulah sebabnya aku mengusulkan agar kita bekerja sama dan menyelesaikan misi kita!",
  ui_story_5081_50811102_38_dialog_content = "!",
  ui_story_5081_50811102_39_dialog_content = "Anatoli sudah memberitahuku. Kamu sudah sangat memaksakan diri dalam bekerja, bukan?",
  ui_story_5081_50811102_40_dialog_content = "Ketika para pemimpin Federasi Illumina menugaskan kamu untuk mencari Gronru, itu karena mereka ingin memberikan kamu tugas yang kurang menstresskan.",
  ui_story_5081_50811102_41_dialog_content = "Tapi pada akhirnya, mereka memutuskan untuk menyerahkan pekerjaan itu kepadaku. Kalau kamu tanya saya, mereka hanya membuat segalanya menjadi lebih rumit!",
  ui_story_5081_50811102_42_dialog_content = "Itulah sebabnya aku lebih memilih untuk menghindari konflik yang tidak perlu dan bekerja sama denganmu untuk menyelesaikan misi!",
  ui_story_5081_50811102_43_dialog_content = "...",
  ui_story_5081_50811102_44_dialog_content = "Aku tahu kamu tidak ingin bermitra dengan siapa pun, tapi aku yakin kamu tidak ingin Illumina kehilangan salah satu ilmuwan terbaik mereka lebih lama lagi, bukan?",
  ui_story_5081_50811102_45_dialog_content = "... Dan apa yang membuatmu yakin bahwa kita akan menemukan Pejabat Teknologi jika kita bekerja sama?",
  ui_story_5081_50811102_46_dialog_content = "Semua informasi yang saya miliki menunjukkan bahwa dia berada di lokasi ini.",
  ui_story_5081_50811102_47_dialog_content = "Namun aku tidak melihat tanda-tanda keberadaannya, bahkan setelah waktu yang lama... Jadi aku berpikir bahwa dengan mengalahkan \"B,\" aku bisa memaksanya untuk mengungkapkan keberadaan Gronru.",
  ui_story_5081_50811102_48_dialog_content = "Apakah kamu mampu mengalahkannya, PlayerName? Jika tidak, saya hanya bisa mengandalkan diri saya sendiri...",
  ui_story_5081_50811102_49_dialog_content = "Batia? Apa pendapatmu tentang Yingel sebagai pemain?",
  ui_story_5081_50811102_50_dialog_content = "Maksudmu dia? Jujur, aku menemukannya cukup menarik. Sepertinya dia sangat menikmati permainan juga...",
  ui_story_5081_50811102_51_dialog_content = "Dan dia tahu cara menghasilkan beberapa strategi tingkat tinggi, meskipun dia terbawa olehnya... Saya pikir dia adalah pemain yang hebat.",
  ui_story_5081_50811102_52_dialog_content = "T-Terhanyut? Itukah pendapatmu tentangku?",
  ui_story_5081_50811102_53_dialog_content = "Tidak, itu tidak benar... Kamu sedang berbicara tentang penantang yang dikenal sebagai \"Y,\" tapi...",
  ui_story_5081_50811102_54_dialog_content = "Lawan Anda adalah Petugas Intelijen Yingel sekarang. Tolong jangan samakan saya dengan penantang terakhir itu.",
  ui_story_5081_50811102_55_dialog_content = "Sekarang bahwa Batia telah mengakui kemampuan Yingel, saya pikir aman bagi saya untuk bertanya sekarang.",
  ui_story_5081_50811102_56_dialog_content = "Gronru sebenarnya sedang bersembunyi di suatu tempat di sini, bukan?",
  ui_story_5081_50811102_57_dialog_content = "Oh... Aku sangat minta maaf, Gronru...",
  ui_story_5081_50811102_58_dialog_content = "Ya... Itu adalah kebenaran.",
  ui_story_5081_50811102_59_dialog_content = "Selama hanya kalian berdua...",
  ui_story_5081_50811102_60_dialog_content = "Aku yakin dia tidak keberatan bertemu denganmu. Silakan, lewat sini.",
  ui_story_5081_50811201_1_dialog_content = "Agak gelap... Tolong jangan tertinggal terlalu jauh.",
  ui_story_5081_50811201_2_dialog_content = "Tak pernah kusangka ada terowongan di bawah tempat ini.",
  ui_story_5081_50811201_3_dialog_content = "Laporan intelijenku tidak menyebutkan apa-apa tentang adanya jalan rahasia...",
  ui_story_5081_50811201_4_dialog_content = "Gronru berusaha keras untuk menyembunyikan tempat ini. Sangat masuk akal jika kamu tidak tahu tentang itu...",
  ui_story_5081_50811201_5_dialog_content = "Inilah kita... Selamat datang di studio bawah tanah Gronru.",
  ui_story_5081_50811201_6_dialog_content = "Ini adalah ruang pribadinya di mana dia dapat menganalisis dan memulihkan game yang baru saja digali dari peradaban kuno.",
  ui_story_5081_50811201_7_dialog_content = "Studio video game? Apakah itu berarti—",
  ui_story_5081_50811201_8_dialog_content = "Kamu benar mengasumsikan bahwa Gronru ada di sini sejak awal, PlayerName... tapi untuk alasan yang berbeda.",
  ui_story_5081_50811201_9_dialog_content = "Dia tidak datang ke sini untuk membeli salinan game fantasi dalam penjualan awal, karena dialah yang memulihkannya pada awalnya.",
  ui_story_5081_50811201_10_dialog_content = "Dengan kata lain...",
  ui_story_5081_50811201_11_dialog_content = "Dia adalah pemilik sejati dari Hidden Fangs, seorang gamer veteran yang mendukung saya dalam menjalankan arcade ini.",
  ui_story_5081_50811201_12_dialog_content = "Jadi laporan intelijenku benar—ini memang markas rahasia miliknya.",
  ui_story_5081_50811201_13_dialog_content = "Mengabaikan tugas-tugas pentingnya sebagai petugas Illumina untuk memperbaiki video game lama...",
  ui_story_5081_50811201_14_dialog_content = "Saya tidak bisa memikirkan hal yang lebih egois untuk dilakukan! Illumina sedang di tengah-tengah—",
  ui_story_5081_50811201_15_dialog_content = "Tengah dari apa?",
  ui_story_5081_50811201_16_dialog_content = "Berhenti, Yingel. Jika PlayerName tidak mendapatkan dukungan dari Batia, mungkin butuh setahun lagi untukmu menemukan tempat ini!",
  ui_story_5081_50811201_17_dialog_content = "Mendapatkan simpati dariku? Dia bahkan tidak setengah jalan mendekati hal itu...",
  ui_story_5081_50811201_18_dialog_content = "Tunggu sebentar! Aku bukan NPC atau semacamnya... Tolong jangan bercanda seperti itu, Gronru!",
  ui_story_5081_50811201_19_dialog_content = "Hanya saja... Sepertinya mereka memiliki sesuatu yang sangat penting untuk diberitahukan kepada kamu, jadi aku membawa mereka kesini.",
  ui_story_5081_50811201_20_dialog_content = "Bagaimanapun, mereka adalah teman dan rekan kerjamu...",
  ui_story_5081_50811201_21_dialog_content = "Itu tidak berarti apa-apa! Bukankah aku sudah bilang jangan biarkan siapa pun masuk ke sini sampai liburanku selesai?",
  ui_story_5081_50811201_22_dialog_content = "... T-Tapi kamu mengatakan \"dengan pengecualian pemain yang sangat menarik\"...",
  ui_story_5081_50811201_23_dialog_content = "\"Pemain yang sangat menarik\"? Kamu tidak sedang berbicara tentang PlayerName dan Yingel, kan?",
  ui_story_5081_50811201_24_dialog_content = "Kamu benar-benar berpikir kedua orang itu memiliki peluang melawan dalang rahasia di balik Hidden Fangs?",
  ui_story_5081_50811201_25_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5081_50811201_26_dialog_content = "Kami diremehkan, PlayerName.",
  ui_story_5081_50811201_27_dialog_content = "Ya... Tapi kita tidak datang ke sini untuk menantang \"otak jenius rahasia\" pada awalnya!",
  ui_story_5081_50811201_28_dialog_content = "Itu tidak penting lagi. Sekarang tidak ada cara untuk menghindari pertempuran ini.",
  ui_story_5081_50811201_29_dialog_content = "Tech Officer Gronru, apakah kamu tahu betapa banyak kekacauan yang telah disebabkan oleh ketidakhadiranmu di Illumina?",
  ui_story_5081_50811201_30_dialog_content = "Aduh, betapa menyakitkannya...",
  ui_story_5081_50811201_31_dialog_content = "Jangan bilang pada saya bahwa senjata anti-Eclipsite terbaru mulai mengalami kerusakan lagi! Jika itu masalahnya, maka gunakan saja yang lain!",
  ui_story_5081_50811201_32_dialog_content = "Senjata lama saya bisa melakukan pekerjaan dengan baik!",
  ui_story_5081_50811201_33_dialog_content = "Atau apakah Komite belum membersihkan diri mereka sendiri?",
  ui_story_5081_50811201_34_dialog_content = "Selalu memanjangkan rapat dengan pidato mereka yang penuh drama dan merasa penting... Apakah setiap orang membuang otak mereka keluar jendela saat mereka mencapai puncak atau bagaimana?",
  ui_story_5081_50811201_35_dialog_content = "Atau mungkin beberapa orang di lab berdebat tentang proyek mana yang harus dikejar dan mana yang harus dibuang lagi?",
  ui_story_5081_50811201_36_dialog_content = "Setiap proyek yang gagal lulus inspeksi langsung dibatalkan tanpa berpikir dua kali, meskipun yang mereka butuhkan hanyalah sedikit dukungan lagi! Hal itu benar-benar membuatku kesal!",
  ui_story_5081_50811201_37_dialog_content = "Keadaan mentalnya...",
  ui_story_5081_50811201_38_dialog_content = "Ini bahkan lebih buruk dari milik Uriel, bukan?",
  ui_story_5081_50811201_39_dialog_content = "Meskipun kamu tidak bisa menanggung tanggung jawab atas semua hal tersebut, itu bukan alasan untuk meninggalkan posmu tanpa persetujuan—",
  ui_story_5081_50811201_40_dialog_content = "Siapa bilang aku tidak mendapatkan persetujuan? Aku telah mengajukan permintaan waktu libur! Dan aku menyetujuinya sendiri!",
  ui_story_5081_50811201_41_dialog_content = "Saya bahkan menempelkan pemberitahuan waktu libur saya di seluruh kantor saya! Jangan bilang kamu tidak melihatnya!",
  ui_story_5081_50811201_42_dialog_content = "Urghhhh, cukup sudah! Aku tidak akan membiarkan kalian berdua merusak permainan Longzhou Tilemaster-ku—",
  ui_story_5081_50811201_43_dialog_content = "Jika kamu ingin saya kembali ke kantor, kamu harus menyeret mayatku yang dingin dan mati ke sana!",
  ui_story_5081_50811201_44_dialog_content = "Master Genteng Longzhou? Saya rasa saya pernah mendengar tentang permainan itu. Itu semacam mahjong...",
  ui_story_5081_50811201_45_dialog_content = "Huh? Tapi kukira kamu sedang menyelesaikan pekerjaanmu pada permainan fantasi, Gronru? Kenapa kamu menekan tombol jeda pada itu?",
  ui_story_5081_50811201_46_dialog_content = "Hmm... T-Tidak masalah! Tidak ada yang boleh mengganggu saya sekarang, kamu mendengar saya? Tidak ada seorang pun!",
  ui_story_5081_50811201_47_dialog_content = "Mari mulai permainan Gronru!",
  ui_story_5081_50811201_48_dialog_content = "... Aku tahu akan berakhir seperti ini.",
  ui_story_5081_50811201_49_dialog_content = "Dapatkan itu, Peng-Peng!",
  ui_story_5081_50811201_50_dialog_content = "\"Peng-Peng\"? ... Oh, kamu maksud si kecil ini.",
  ui_story_5081_50811201_51_dialog_content = "Aku belum selesai! Nikmati ini: Semua Hijau, Empat Berkah, dan Sembilan Lentera Teratai!",
  ui_story_5081_50811201_52_dialog_content = "Hei... Tunggu sebentar saja! Bagaimana aku bisa mengikuti itu?",
  ui_story_5081_50811201_53_dialog_content = "Saya telah masuk ke dalam game! Tetap bertahan, PlayerName!",
  ui_story_5081_50811201_54_dialog_content = "Aku juga dalam posisi!",
  ui_story_5081_50811201_55_dialog_content = "Jujur... Tipe orang apa yang menamai Eclipsite setelah gerakan dalam mahjong?",
  ui_story_5081_50811201_56_dialog_content = "Siapa lagi jika bukan Gronru yang hebat, master dari semua bentuk mahjong!",
  ui_story_5081_50811201_57_dialog_content = "Semua yang berani menentangku akan dilumat di bawah beratnya ubin kolosal milikku!",
  ui_story_5081_50811201_58_dialog_content = "Kamu datang untuk menantang saya, benar? Maka hadapilah, kalian bertiga! Aku akan menunjukkan pada kalian semua—",
  ui_story_5081_50811201_59_dialog_content = "Bahwa saya, Gronkenstein Ruu, adalah gamer sejati dan tak terkalahkan yang dikenal sebagai \"B\"!",
  ui_story_5081_50811201_60_dialog_content = "\"B\" berarti \"bos,\" seperti dalam bos akhir!",
  ui_story_5081_50811300_1_dialog_content = "<color=#e8d9bb>Dan begitu Gronru yang tak terkalahkan akhirnya dikalahkan.</color>",
  ui_story_5081_50811300_2_dialog_content = "Fiuh... Itu nyaris saja. Gronru hampir mengalahkan kita.",
  ui_story_5081_50811300_3_dialog_content = "Memiliki pemain yang kuat seperti Batia di tim kami sangatlah menenangkan.",
  ui_story_5081_50811300_4_dialog_content = "Percayalah, setiap orang telah bermain sebaik mungkin barusan. Tanpa kalian... Saya tidak akan pernah bisa mengalahkan Gronru...",
  ui_story_5081_50811300_5_dialog_content = "Mengalahkan saya? Dalam mimpimu saja! Gronkenstein Ruu tidak akan pernah bisa dikalahkan!",
  ui_story_5081_50811300_6_dialog_content = "Itu baru bentuk pertamaku! Aku masih punya dua bentuk lagi, masing-masing dua kali lebih kuat dari yang terakhir!",
  ui_story_5081_50811300_7_dialog_content = "Aaaaaahhhh—",
  ui_story_5081_50811300_8_dialog_content = "Tunggu, Gronru... Kamu sedang menggunakan kode curang sekarang, bukan?",
  ui_story_5081_50811300_9_dialog_content = "Itu sama sekali tidak adil!",
  ui_story_5081_50811300_10_dialog_content = "\"Adil\"? Kata itu tidak ada di mana pun di Astra!",
  ui_story_5081_50811300_11_dialog_content = "Curang hanyalah bagian lain dari Game Gronru! Jika kamu tidak suka, maka keluarlah!",
  ui_story_5081_50811300_12_dialog_content = "Haaaaaahhhh—",
  ui_story_5081_50811300_13_dialog_content = "Tunggu... Apakah dia benar-benar hanya menggunakan cheat?",
  ui_story_5081_50811300_14_dialog_content = "Mengapa seluruh ruangan bergetar seolah-olah akan menghancurkan diri sendiri?",
  ui_story_5081_50811300_15_dialog_content = "Apa dia membebani mesin game dengan menggunakan terlalu banyak cheat?",
  ui_story_5081_50811300_16_dialog_content = "Setiap perangkat di ruangan ini saling terhubung...",
  ui_story_5081_50811300_17_dialog_content = "G-Gronru! Jika ini terus berlanjut, seluruh arcade akan meledak!",
  ui_story_5081_50811300_18_dialog_content = "Lalu biarkan meledak... Aku lebih memilih itu daripada kalah dari kamu dan harus kembali bekerja!",
  ui_story_5081_50811300_19_dialog_content = "Kenapa aku harus menangani semua dampaknya ketika ini bukan salahku sama sekali?",
  ui_story_5081_50811300_20_dialog_content = "Benci dengan aturan mereka yang tidak adil! Mereka hanya membuat lebih banyak pekerjaan untukku untuk menutupi kesalahan mereka sendiri!",
  ui_story_5081_50811300_21_dialog_content = "Orang-orang sombong itu tidak akan pernah mengerti! Alasan satu-satunya kita bekerja adalah untuk menikmati bermain game di waktu luang kita dengan baik!",
  ui_story_5081_50811300_22_dialog_content = "Sebuah Astra di mana aku tidak bisa bermain game sepuas hatiku... ditakdirkan untuk menghilang, bersama dengan bentuk ketigaku—",
  ui_story_5081_50811300_23_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_5081_50811300_24_dialog_content = "?",
  ui_story_5081_50811300_25_dialog_content = "Getarannya berhenti?",
  ui_story_5081_50811300_26_dialog_content = "Ya. Kita perlu mengeluarkannya dari situ, jadi saya mematikan daya mesinnya.",
  ui_story_5081_50811300_27_dialog_content = "Kamu tidak menyalahkan saya, bukan Gronru? Lagipula, kamu selalu mengaktifkan fitur penyimpanan otomatis untuk permainanmu...",
  ui_story_5081_50811300_28_dialog_content = "Aku tidak peduli lagi tentang data penyimpananku! Aku tidak akan kembali, bahkan jika aku mati sekalipun!",
  ui_story_5081_50811300_29_dialog_content = "Kamu sangat menyedihkan tanpa cheatmu, Gronru.",
  ui_story_5081_50811300_30_dialog_content = "Itu kaya datang dari Anda, Yingel! Bukankah Anda baru saja dibantu oleh Batia? Bahkan tanpa curang, Anda tidak akan pernah berpeluang melawan saya satu lawan satu!",
  ui_story_5081_50811300_31_dialog_content = "Mungkin begitu, tapi aku masih menang... Kita semua menang!",
  ui_story_5081_50811300_32_dialog_content = "Menjijikkan... Terkutuklah kau!",
  ui_story_5081_50811300_33_dialog_content = "Berhenti, kalian berdua! Aku tidak membawa mereka untuk menantangmu, Gronru! Ini hanya...",
  ui_story_5081_50811300_34_dialog_content = "Aku menyadari kamu tidak begitu baik akhir-akhir ini... tapi aku tidak tahu bagaimana membantumu...",
  ui_story_5081_50811300_35_dialog_content = "Setelah semua... Saya tidak tahu apa yang dipikirkan para pemimpin Anda.",
  ui_story_5081_50811300_36_dialog_content = "Tapi, kurasa tidak apa-apa jika kamu tidak suka mereka, Gronru!",
  ui_story_5081_50811300_37_dialog_content = "Itulah sebabnya... Aku ingin membawakan beberapa orang yang mungkin kamu suka!",
  ui_story_5081_50811300_38_dialog_content = "Aku?",
  ui_story_5081_50811300_39_dialog_content = "Dia?",
  ui_story_5081_50811300_40_dialog_content = "J-Jangan lihat aku!",
  ui_story_5081_50811300_41_dialog_content = "Itu benar! Setelah bermain dengan mereka dan melawan mereka, saya bisa bilang bahwa mereka memiliki hasrat yang sebenarnya untuk video game!",
  ui_story_5081_50811300_42_dialog_content = "Dan tidak seperti saya... mereka tidak mengurung diri di kamar mereka setiap hari. Mereka adalah rekan kerja Anda, sekaligus teman Anda.",
  ui_story_5081_50811300_43_dialog_content = "Itulah mengapa saya pikir mereka lebih pandai memahami masalah Anda daripada saya.",
  ui_story_5081_50811300_44_dialog_content = "Batia...",
  ui_story_5081_50811300_45_dialog_content = "Jadi, bisakah kamu hanya menganggap ini sebagai saya yang mengadakan konvensi permainan dadakan di Hidden Fangs?",
  ui_story_5081_50811300_46_dialog_content = "Semoga ini memberi kamu kesempatan untuk berbagi masalahmu dengan kami... sehingga kita bisa menemukan jalan ke depan bersama-sama!",
  ui_story_5081_50811300_47_dialog_content = "*mengendus*",
  ui_story_5081_50811300_48_dialog_content = "Waaaaaaaaah—",
  ui_story_5081_50811300_49_dialog_content = "Saya tidak tahan dengan pertemuan yang menjengkelkan itu atau tumpukan laporan yang selalu harus saya tulis!",
  ui_story_5081_50811300_50_dialog_content = "Tidak pernah ada cukup waktu untuk bermain game, apalagi memulihkannya... Itulah sebabnya saya memutuskan untuk bersembunyi di sini!",
  ui_story_5081_50811300_51_dialog_content = "Sebenarnya, aku berniat menyelesaikan pekerjaanku pada game fantasi itu secepat mungkin, tapi suasana hatiku sangat buruk sehingga aku tidak bisa membuat kemajuan apa-apa...",
  ui_story_5081_50811300_52_dialog_content = "Jadi saya berpikir, \"Mungkin permainan Longzhou Tilemaster akan membantu saya sedikit rileks...\"",
  ui_story_5081_50811300_53_dialog_content = "Tapi begitu saya mulai bermain, saya tidak bisa meletakkan pengendali!",
  ui_story_5081_50811300_54_dialog_content = "Aku bilang pada diriku sendiri akan berhenti setelah mencapai peringkat kedelapan, tapi kemudian aku terus berlanjut hingga peringkat kesembilan, dan kemudian kesepuluh...",
  ui_story_5081_50811300_55_dialog_content = "Selama ini aku memiliki nasib yang sangat buruk, jadi butuh waktu lama untuk membuat kemajuan... Dan sekarang rilis game fantasi itu hanya di depan mata...",
  ui_story_5081_50811300_56_dialog_content = "Tidak mungkin aku akan berhasil tepat waktu sekarang!",
  ui_story_5081_50811300_57_dialog_content = "Pekerjaanku masih belum selesai! Permainannya masih belum selesai! Aku belum menyelesaikan satu hal pun!",
  ui_story_5081_50811300_58_dialog_content = "*Menangis* Mengapa hidup harus begitu berat? Aku tidak ingin bermain lagi—",
  ui_story_5081_50811300_59_dialog_content = "PlayerName! Kamu harus membantu saya menghapus diri saya dari dunia!",
  ui_story_5081_50811300_60_dialog_content = "H-Hei! Jangan mengatakan hal-hal menakutkan seperti itu!",
  ui_story_5081_50811300_61_dialog_content = "Dunia ini membutuhkanmu, Gronru! Lagipula, hidup ini bukanlah permainan single-player...",
  ui_story_5081_50811300_62_dialog_content = "Mengapa tidak membiarkan kami bermain denganmu?",
  ui_story_5081_50811300_63_dialog_content = "Jika kita menghadapi tahap yang disebut kehidupan ini bersama, saya yakin kita bisa melewatinya dengan sukses gemilang! Itu pasti akan lebih menyenangkan daripada melakukannya sendiri, setidaknya!",
  ui_story_5081_50811300_64_dialog_content = "Mengenai siksaan yang berlebihan, tidak perlu, dan menekan di Illumina...",
  ui_story_5081_50811300_65_dialog_content = "... Maksud saya, mengenai pekerjaanmu, saya yakin Anatoli dan saya bisa membantu kamu untuk memperbaiki beberapa proses tersebut.",
  ui_story_5081_50811300_66_dialog_content = "Dan jika berbicara tentang memulihkan video game, Odi pasti tahu apa yang dia lakukan!",
  ui_story_5081_50811300_67_dialog_content = "Mungkin No. 33 juga bisa membantu!",
  ui_story_5081_50811300_68_dialog_content = "Untukku... Aku tidak pandai dalam hal lain selain video game, tapi kamu selalu bisa meminta aku untuk menjadi penguji kamu!",
  ui_story_5081_50811300_69_dialog_content = "Kamu tidak hanya jago bermain video game, Batia.",
  ui_story_5081_50811300_70_dialog_content = "Kita semua adalah gamer di sini, tapi kamu memiliki sesuatu yang spesial yang tidak dimiliki orang lain...",
  ui_story_5081_50811300_71_dialog_content = "Itu adalah Hidden Fangs, tujuan utama para gamer di seluruh dunia! Belum lagi reputasi Anda sebagai gamer legendaris \"B\"!",
  ui_story_5081_50811300_72_dialog_content = "Pikirkan saja semua penantang yang telah kamu kalahkan untuk melindungi arcade-mu hari ini!",
  ui_story_5081_50811300_73_dialog_content = "Aku…",
  ui_story_5081_50811300_74_dialog_content = "Batia... Oh, Batiaaaa—",
  ui_story_5081_50811300_75_dialog_content = "I-Ini akan baik-baik saja, Gronru! Jangan menangis...",
  ui_story_5081_50811300_76_dialog_content = "Kamu sudah tumbuh dewasa sekarang! Kamu telah berubah dari gadis kecil yang pendiam menjadi manajer arcade yang dapat diandalkan!",
  ui_story_5081_50811300_77_dialog_content = "Pidato PlayerName tampaknya masih efektif seperti biasanya...",
  ui_story_5081_50811300_78_dialog_content = "S-Seperti yang aku katakan, aku bukan NPC!",
  ui_story_5081_50811300_79_dialog_content = "Tapi kamu benar-benar luar biasa! Kamu menghadapi begitu banyak masalah sendiri!",
  ui_story_5081_50811300_80_dialog_content = "Kamu bahkan bisa menangani seseorang yang sejengkel Yingel!",
  ui_story_5081_50811300_81_dialog_content = "?",
  ui_story_5081_50811300_82_dialog_content = "Saya pikir saya harus menantangmu lagi hanya untuk menunjukkan betapa <color=#FFB400>menyebalkan</color> saya bisa, Tech Officer Gronru.",
  ui_story_5081_50811300_83_dialog_content = "Oh, jadi kamu mau terus bermain?",
  ui_story_5081_50811300_84_dialog_content = "Sama sekali tidak. Saya hanya mengajukan tantangan.",
  ui_story_5081_50811300_85_dialog_content = "Heheheh, sepertinya video game memang bisa membuat apapun terjadi... Aku merasa jauh lebih baik setelah semua yang terjadi hari ini!",
  ui_story_5081_50811300_86_dialog_content = "Apakah kalian masih ingin menantang saya? Saya siap, tapi saya hanya butuh waktu dulu.",
  ui_story_5081_50811300_87_dialog_content = "Saya ingin menyelesaikan pekerjaan saya pada game fantasi itu sekarang juga! Setelah itu, kalian semua bisa menjadi penguji berharga untuk karya terbaru saya!",
  ui_story_5081_50811300_88_dialog_content = "Ini adalah satu-satunya kesempatan Anda untuk menantang bos akhir yang sebenarnya!",
  ui_story_5081_50811300_89_dialog_content = "Karena setelah saya kembali ke Illumina, prestasi ini tidak akan tersedia dalam versi resmi!",
  ui_story_5081_50811300_90_dialog_content = "Kita akan melihat apakah kamu memiliki apa yang dibutuhkan untuk membukanya di tempat pertama!",
  ui_story_5081_50811300_91_dialog_content = "Jadi sudah diputuskan? Akhirnya kamu akan kembali ke Illumina?",
  ui_story_5081_50811300_92_dialog_content = "... Humph!",
  ui_story_5081_50811300_93_dialog_content = "Hah? Kemana kamu pergi, Yingel?",
  ui_story_5081_50811300_94_dialog_content = "Apakah kamu benar-benar perlu bertanya? Aku akan melakukan latihan menit terakhir sebelum dia selesai memulihkan game.",
  ui_story_5081_50811300_95_dialog_content = "Aku tidak akan berhenti sampai aku mengalahkannya begitu parah sehingga dia memutuskan untuk berhenti bermain game dan kembali bekerja untuk selamanya.",
  ui_story_5081_50811300_96_dialog_content = "Oh... S-Semoga berhasil dengan itu...",
  ui_story_5081_50811300_97_dialog_content = "Bagaimana denganmu, Batia?",
  ui_story_5081_50811300_98_dialog_content = "Jika kamu setuju, saya ingin memilih beberapa game ini untuk bermain bersamamu, PlayerName.",
  ui_story_5081_50811300_99_dialog_content = "Oh, oke! Ini dari sarangmu, kan?",
  ui_story_5081_50811300_100_dialog_content = "Mari kita lihat... Album White Night 2, huh? Kenapa kita tidak memainkan yang ini?",
  ui_story_5081_50811300_101_dialog_content = "Eh... Baiklah.",
  ui_story_5081_50811300_102_dialog_content = "Sesuatu memberitahu saya bahwa Anda akan sangat baik dalam permainan ini. Mari kita lihat pilihan apa yang akan Anda buat...",
  ui_story_5081_50811300_103_dialog_content = "Tentu! Ayo kita nyalakan!",
  ui_story_5081_50811300_104_dialog_content = "Apakah ini benar-benar saatnya untuk bersantai seperti ini? Kita akan menantang Gronru lagi segera, ingat?",
  ui_story_5081_50811300_105_dialog_content = "Kami hanya bermain video game, Yingel! Lagipula, siapa bilang permainan ini akan mudah? Ayo lihat sendiri!",
  ui_story_5081_50811300_106_dialog_content = "<color=#e8d9bb>Jadi, sementara Gronru menyelesaikan sentuhan terakhir pada game terbarunya, kami yang lain juga duduk di sekelilingnya dan bermain game...</color>",
  ui_story_5081_50811300_107_dialog_content = "<color=#e8d9bb>Bersama, kita memiliki malam kesenangan yang sederhana dan murni dalam teman satu sama lain.</color>",
  ui_story_5081_50811300_108_dialog_content = "Penantian akhirnya berakhir, setiap orang! May Saya persembahkan kepada kamu—permainan fantasi yang akan membuat semua Astra menjadi gila!",
  ui_story_5081_50811300_109_dialog_content = "Sebagai tiga pemain pertamanya, saya harap kalian semua sudah siap!",
  ui_story_5081_50811300_110_dialog_content = "Senapan sniperku sudah lelah menunggu.",
  ui_story_5081_50811300_111_dialog_content = "Heh, sepertinya saya bisa mengatur ke tingkat kesulitan yang paling sulit!",
  ui_story_5081_50811300_112_dialog_content = "Bagaimana dengan kalian berdua?",
  ui_story_5081_50811300_113_dialog_content = "Aku siap!",
  ui_story_5081_50811300_114_dialog_content = "Aku juga akan berusaha sebaik mungkin!",
  ui_story_5081_50811300_115_dialog_content = "Baik, maka mari kita mulai hitungan mundur! Tiga! Dua! Satu!",
  ui_story_5081_50811300_116_dialog_content = "Permainan dimulai!"
}
